  ui_story_5037_50370201_9_dialog_content = "¿Qué haces durmiendo aquí? ¡El concierto está a punto de empezar!",
  ui_story_5037_50370201_10_dialog_content = "¡Me tomó tanto tiempo encontrarte!",
  ui_story_5037_50370201_11_dialog_content = "¿Cómo tendría la energía para actuar sin mi sueño reparador?",
  ui_story_5037_50370201_12_dialog_content = "Dame unos minutos más y me iré.",
  ui_story_5037_50370201_13_dialog_content = "<size=45>Maestro-!</size>",
  ui_story_5037_50370201_14_dialog_content = "¡¿Cómo estás tan relajado en un momento como este?!",
  ui_story_5037_50370201_15_dialog_content = "Goldie y PlayerName Ya ensayé un montón.",
  ui_story_5037_50370201_16_dialog_content = "Bueno, si ya lo han hecho, no creo que sea necesario.",
  ui_story_5037_50370201_17_dialog_content = "Es una pérdida de tiempo que todos hagan lo mismo.",
  ui_story_5037_50370201_18_dialog_content = "*Inhala* ¿Estás diciendo tonterías otra vez?",
  ui_story_5037_50370201_19_dialog_content = "Una cosa es cuando es durante la práctica, ¡pero ahora tenemos que ponernos serios!",
  ui_story_5037_50370201_20_dialog_content = "No obtendremos la bonificación si perdemos PlayerName!",
  ui_story_5037_50370201_21_dialog_content = "¡Lo sé! ¡Hagamos que Shira tome mi lugar!",
  ui_story_5037_50370201_22_dialog_content = "¡NO NO!",
  ui_story_5037_50370201_23_dialog_content = "No lo entiendo... ¿Por qué insistes en hacerle la vida difícil a tu antiguo maestro?",
  ui_story_5037_50370201_24_dialog_content = "Hmm, me pregunto quién se jactó de casi convertirse en un ídolo.",
  ui_story_5037_50370201_25_dialog_content = "¿Cuándo presumí, Fia? ¡Era un hecho!",
  ui_story_5037_50370201_26_dialog_content = "Bueno, allá vas.",
  ui_story_5037_50370201_27_dialog_content = "¡Tienes la oportunidad de ser un ídolo hoy! ¿No deberías estar contento?",
  ui_story_5037_50370201_28_dialog_content = "Sólo de nombre está bien. No quiero ser un ídolo de verdad.",
  ui_story_5037_50370201_29_dialog_content = "¡Si lo hiciera, sería un entrenador de ídolos para bestias maravillosas!",
  ui_story_5037_50370201_30_dialog_content = "¡Razón de más para que ganes algo de dinero y puedas cuidar de las criaturas que tienes!",
  ui_story_5037_50370201_31_dialog_content = "El pago por estar en el programa solo puede sostener sus propias necesidades de vida.",
  ui_story_5037_50370201_32_dialog_content = "tienes que vencer PlayerName ¡así que tenemos los medios para mejorar la vida de las maravillosas bestias!",
  ui_story_5037_50370201_33_dialog_content = "Pero trabajé duro y tomé trabajos secundarios...",
  ui_story_5037_50370201_34_dialog_content = "La paga combinada de esos trabajos ni siquiera coincide con este trabajo.",
  ui_story_5037_50370201_35_dialog_content = "Los pobres animales van a morir de hambre si te limitas a esos trabajos secundarios.",
  ui_story_5037_50370201_36_dialog_content = "¡Tengo que mantenerte atado esta vez y ganar ese bono!",
  ui_story_5037_50370201_37_dialog_content = "(No escuché bien lo que dijeron...)",
  ui_story_5037_50370201_38_dialog_content = "(Pero Fia sonaba decidida e impresionante. En comparación, me siento...)",
  ui_story_5037_50370201_39_dialog_content = "¡Guau, esta pastilla para la tos es realmente mentolada y genial!",
  ui_story_5037_50370201_40_dialog_content = "Eres tan considerado al pensar en esto, Productor. PlayerName!",
  ui_story_5037_50370201_41_dialog_content = "...",
  ui_story_5037_50370201_42_dialog_content = "¿Qué tienes en mente?",
  ui_story_5037_50370201_43_dialog_content = "Nada. Estoy feliz de que te guste.",
  ui_story_5037_50370201_44_dialog_content = "¡En el futuro prepararé más sabores relajantes y sabrosos de pastillas para la tos para calmar la garganta!",
  ui_story_5037_50370201_45_dialog_content = "Oye, parece que estás listo para irte.",
  ui_story_5037_50370201_46_dialog_content = "¡Sí! ¡Me aseguraré de que te encante el resultado!",
  ui_story_5037_50370201_47_dialog_content = "Me encanta tu confianza, cariño. Espero que.",
  ui_story_5037_50370201_48_dialog_content = "¿Señora Sheol?",
  ui_story_5037_50370201_49_dialog_content = "Sí, PlayerName?",
  ui_story_5037_50370201_50_dialog_content = "¿Vic actuará con Goldie en el escenario?",
  ui_story_5037_50370201_51_dialog_content = "¿Qué te preocupa?",
  ui_story_5037_50370201_52_dialog_content = "Oh, solo estaba comprobando.",
  ui_story_5037_50370201_53_dialog_content = "Simplemente proceda con lo que haya planeado.",
  ui_story_5037_50370201_54_dialog_content = "El concierto de Vic no está aquí. Está en un escenario vecino.",
  ui_story_5037_50370201_55_dialog_content = "Goldie y Vic realizarán sus shows simultáneamente.",
  ui_story_5037_50370201_56_dialog_content = "¿Otra etapa? Con razón no vi a Vic detrás del escenario.",
  ui_story_5037_50370201_57_dialog_content = "Ya veo. Así que anticipaste esto cuando construiste la sala de conciertos, ¿eh?",
  ui_story_5037_50370201_58_dialog_content = "Es por eso que configura dos escenarios uno al lado del otro.",
  ui_story_5037_50370201_59_dialog_content = "¿Dos escenarios uno al lado del otro?",
  ui_story_5037_50370201_60_dialog_content = "Deberías sorprenderte, cariño. Esta es una de mis mejores obras maestras.",
  ui_story_5037_50370201_61_dialog_content = "Sólo un pasillo separa los dos escenarios.",
  ui_story_5037_50370201_62_dialog_content = "Una vez que comienzan los espectáculos, el público puede seguir sus preferencias y moverse libremente entre los escenarios.",
  ui_story_5037_50370201_63_dialog_content = "Al final, la etapa que logre ganar una multitud más grande será declarada ganadora.",
  ui_story_5037_50370201_64_dialog_content = "La experiencia no tendrá precedentes y también generará publicidad para el reality show.",
  ui_story_5037_50370201_65_dialog_content = "Asegúrate de editar esa última línea de la transmisión, Lilica.",
  ui_story_5037_50370201_66_dialog_content = "¡No hay problema!",
  ui_story_5037_50370201_67_dialog_content = "(¡Me acostumbré tanto a Lilica y su cámara que olvidé que estaba con nosotros!)",
  ui_story_5037_50370201_68_dialog_content = "¡Pues bien, buena suerte, cariño!",
  ui_story_5037_50370201_69_dialog_content = "¿Por qué no nos dijeron nada de esto?",
  ui_story_5037_50370201_70_dialog_content = "¡Ahora necesito reelaborar el programa del concierto para hacerlo más atractivo!",
  ui_story_5037_50370201_71_dialog_content = "¡Ay! Todavía no he comprobado el sonido y la iluminación...",
  ui_story_5037_50370201_72_dialog_content = "Lo comprobaste, PlayerName.",
  ui_story_5037_50370201_73_dialog_content = "¿Qué? ¿Hice?",
  ui_story_5037_50370201_74_dialog_content = "Que le pasa a mi memoria...",
  ui_story_5037_50370201_75_dialog_content = "Estás nervioso, PlayerName?",
  ui_story_5037_50370201_76_dialog_content = "Relájate, ¡nos hemos esforzado lo suficiente en nuestra preparación!",
  ui_story_5037_50370201_77_dialog_content = "No necesitamos pensar en lo que sucederá.",
  ui_story_5037_50370201_78_dialog_content = "¡Mientras hagamos un espectáculo como lo ensayamos y hagamos feliz a la multitud, podemos contarlo como una victoria!",
  ui_story_5037_50370201_79_dialog_content = "Sí, sí, tienes razón, Goldie.",
  ui_story_5037_50370201_80_dialog_content = "¡Solo tenemos que mostrarles lo que hemos estado practicando!",
  ui_story_5037_50370201_81_dialog_content = "<color=#793f76>Cinco minutos</color> al espectáculo!",
  ui_story_5037_50370201_82_dialog_content = "¡Ahhhh!",
  ui_story_5037_50370201_83_dialog_content = "¡No no no! ¡Siento que todavía tengo un montón de cosas que hacer!",
  ui_story_5037_50370201_84_dialog_content = "Relax. ¡Todo lo que tenemos que hacer ahora es esperar a que comience el espectáculo!",
  ui_story_5037_50370201_85_dialog_content = "¿Estás seguro?",
  ui_story_5037_50370201_86_dialog_content = "Lo siento. Espero que mi ansiedad no te esté afectando.",
  ui_story_5037_50370201_87_dialog_content = "Realmente no soy un productor competente.",
  ui_story_5037_50370201_88_dialog_content = "¡Eso no es cierto!",
  ui_story_5037_50370201_89_dialog_content = "¡Esta es solo tu primera vez!",
  ui_story_5037_50370201_90_dialog_content = "Estás mostrando mil veces más compostura ahora que cuando me subí a un escenario por primera vez.",
  ui_story_5037_50370201_91_dialog_content = "¿Tu primera vez en un escenario?",
  ui_story_5037_50370201_92_dialog_content = "Sí. Nadie quería darme una oportunidad en ese entonces.",
  ui_story_5037_50370201_93_dialog_content = "Tuve que luchar por la oportunidad de estar en el escenario.",
  ui_story_5037_50370201_94_dialog_content = "¡A continuación, Goldie nos traerá una canción feliz!",
  ui_story_5037_50370201_95_dialog_content = "H... ¡Hola a todos!",
  ui_story_5037_50370201_96_dialog_content = "¿Quién es?",
  ui_story_5037_50370201_97_dialog_content = "No sé, no me importa.",
  ui_story_5037_50370201_98_dialog_content = "No importa. Es un buen momento para correr al baño.",
  ui_story_5037_50370201_99_dialog_content = "Suspiro...",
  ui_story_5037_50370201_100_dialog_content = "(¿Cómo es que tantos de ellos simplemente se fueron?)",
  ui_story_5037_50370201_101_dialog_content = "(Todos los demás solo están mirando.)",
  ui_story_5037_50370201_102_dialog_content = "(Hablando de eso, ¿por qué estoy aquí?)",
  ui_story_5037_50370201_103_dialog_content = "(Qué estoy haciendo aquí...?)",
  ui_story_5037_50370201_104_dialog_content = "¿Vas a hacer algo o simplemente te quedas ahí?",
  ui_story_5037_50370201_105_dialog_content = "¡Bájate del escenario si no puedes cantar!",
  ui_story_5037_50370201_106_dialog_content = "eh, yo...",
  ui_story_5037_50370201_107_dialog_content = "¿Te abuchearon fuera del escenario?",
  ui_story_5037_50370201_108_dialog_content = "Lo siento, no quise recordarte un recuerdo tan malo.",
  ui_story_5037_50370201_109_dialog_content = "Oh, no te preocupes. Ya no me molesta.",
  ui_story_5037_50370201_110_dialog_content = "¿Ah?",
  ui_story_5037_50370201_111_dialog_content = "Me dije entonces que el comienzo de todo viaje es difícil.",
  ui_story_5037_50370201_112_dialog_content = "Está bien cometer errores, ¡pero no cometas los mismos errores dos veces!",
  ui_story_5037_50370201_113_dialog_content = "Después de eso, nunca me volví a poner tan nervioso como para olvidar mis letras.",
  ui_story_5037_50370201_114_dialog_content = "Pero si no hubiera superado mi miedo escénico la primera vez y me hubiera revolcado en mi miseria...",
  ui_story_5037_50370201_115_dialog_content = "No me habría convertido en lo que soy hoy.",
  ui_story_5037_50370201_116_dialog_content = "¡Muy inspirador!",
  ui_story_5037_50370201_117_dialog_content = "En realidad, todavía me pongo un poco nervioso incluso ahora.",
  ui_story_5037_50370201_118_dialog_content = "Pero un poco de estrés mejorará tu concentración y hará que te vaya mejor.",
  ui_story_5037_50370201_119_dialog_content = "¡No puedo decir que estés nervioso en absoluto!",
  ui_story_5037_50370201_120_dialog_content = "¿En serio? Probablemente sea porque estás demasiado nervioso, así que me veo relajado en comparación.",
  ui_story_5037_50370201_121_dialog_content = "Pero de todos modos, mi punto es...",
  ui_story_5037_50370201_122_dialog_content = "Por favor confia en mi.",
  ui_story_5037_50370201_123_dialog_content = "Después de todo, soy un ídolo veterano curtido en el escenario.",
  ui_story_5037_50370201_124_dialog_content = "Sin mencionar que ahora tengo un excelente productor que seleccionó fantásticas canciones, disfraces y accesorios para mí.",
  ui_story_5037_50370201_125_dialog_content = "¡Ah, sí, y las mejores pastillas para la tos que he probado también!",
  ui_story_5037_50370201_126_dialog_content = "¡Así que no te defraudaré!",
  ui_story_5037_50370201_127_dialog_content = "Goldie...",
  ui_story_5037_50370201_128_dialog_content = "¡Entonces yo tampoco debería decepcionarte!",
  ui_story_5037_50370201_129_dialog_content = "¡Diez segundos para que comience el concierto!",
  ui_story_5037_50370201_130_dialog_content = "Diez... nueve... ocho... siete...",
  ui_story_5037_50370201_131_dialog_content = "¡Es hora de que suba al escenario, productor!",
  ui_story_5037_50370201_132_dialog_content = "¡Rompe una pierna, Goldie!",
  ui_story_5037_50370201_133_dialog_content = "¡Gracias!",
  ui_story_5037_50370301_1_dialog_content = "¡Dondequiera que va Goldie, los Ricitos de Oro la siguen!",
  ui_story_5037_50370301_2_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370301_3_dialog_content = "¡La multitud está emocionada!",
  ui_story_5037_50370301_4_dialog_content = "El espectáculo ha terminado, pero todavía están gritando el nombre de Goldie.",
  ui_story_5037_50370301_5_dialog_content = "Ya estoy de vuelta, PlayerName!",
  ui_story_5037_50370301_6_dialog_content = "¡Bien hecho, Goldie!",
  ui_story_5037_50370301_7_dialog_content = "¿Hey, qué pasa? ¿Por qué parece que estás a punto de llorar?",
  ui_story_5037_50370301_8_dialog_content = "Lo logramos... ¡Lo logramos!",
  ui_story_5037_50370301_9_dialog_content = "Me fue increíblemente bien. Todo el mundo se movió a cada una de sus notas.",
  ui_story_5037_50370301_10_dialog_content = "Sí, yo también lo sentí ahí fuera, ¡era como si fuera uno con el escenario!",
  ui_story_5037_50370301_11_dialog_content = "Tus baladas conmovieron a muchos de ellos hasta las lágrimas.",
  ui_story_5037_50370301_12_dialog_content = "¡Y las canciones rápidas tenían a todos saltando al ritmo!",
  ui_story_5037_50370301_13_dialog_content = "¡Tuviste una actuación impecable hoy!",
  ui_story_5037_50370301_14_dialog_content = "Todo gracias a mi gran productor, por supuesto.",
  ui_story_5037_50370301_15_dialog_content = "¡Nunca antes me había dado cuenta de que podía dominar canciones así!",
  ui_story_5037_50370301_16_dialog_content = "Fue posible solo por la iluminación y el diseño del escenario.",
  ui_story_5037_50370301_17_dialog_content = "No importa la audiencia, incluso yo disfruté la actuación.",
  ui_story_5037_50370301_18_dialog_content = "No pareces un novato en absoluto, ¿sabes?",
  ui_story_5037_50370301_19_dialog_content = "¡En cambio, eres como un productor de ídolos versátil que es capaz de manejar cualquier cosa!",
  ui_story_5037_50370301_20_dialog_content = "Jaja, me halagas... Todavía tengo mucho margen de mejora.",
  ui_story_5037_50370301_21_dialog_content = "Casi cometí un error y no saqué uno de los accesorios a tiempo.",
  ui_story_5037_50370301_22_dialog_content = "Se necesitó tu experiencia para evitar un desastre.",
  ui_story_5037_50370301_23_dialog_content = "Pero no cometerás el mismo error la próxima vez, ¿verdad?",
  ui_story_5037_50370301_24_dialog_content = "¡Absolutamente no!",
  ui_story_5037_50370301_25_dialog_content = "¡Jaja!",
  ui_story_5037_50370301_26_dialog_content = "Oh, Lady Sheol dijo que anunciará los resultados en la agencia.",
  ui_story_5037_50370301_27_dialog_content = "De acuerdo, vamos.",
  ui_story_5037_50370301_28_dialog_content = "¿Qué te pasa, Maestro? ¡No lo hiciste todo en el escenario!",
  ui_story_5037_50370301_29_dialog_content = "Pero, sorprendentemente, les encantó verte ser tu habitual perezoso.",
  ui_story_5037_50370301_30_dialog_content = "¡Pensaron que era una parte deliberada de tu acto!",
  ui_story_5037_50370301_31_dialog_content = "Supongo que tienes un don para ser un ídolo...",
  ui_story_5037_50370301_32_dialog_content = "¿No te dije que casi me convertí en uno?",
  ui_story_5037_50370301_33_dialog_content = "Entonces, ¿por qué no debutaste con éxito hasta hoy?",
  ui_story_5037_50370301_34_dialog_content = "¿Mmm? Me pregunto...",
  ui_story_5037_50370301_35_dialog_content = "¡Porque he estado vigilando de cerca tu entrenamiento!",
  ui_story_5037_50370301_36_dialog_content = "Seguro que Vic y Fia se están divirtiendo.",
  ui_story_5037_50370301_37_dialog_content = "Parece que su concierto también fue un éxito.",
  ui_story_5037_50370301_38_dialog_content = "...",
  ui_story_5037_50370301_39_dialog_content = "¡No luzcas tan estresado! Vic y yo somos ídolos de Starlit Agency.",
  ui_story_5037_50370301_40_dialog_content = "¡Es una noticia fabulosa que ambos tuvimos un exitoso debut!",
  ui_story_5037_50370301_41_dialog_content = "¡Si, tienes razón!",
  ui_story_5037_50370301_42_dialog_content = "Veo que todos han llegado.",
  ui_story_5037_50370301_43_dialog_content = "Buen trabajo por todos lados. Ahora déjame ir directo al grano.",
  ui_story_5037_50370301_44_dialog_content = "El resultado del concierto es el siguiente:",
  ui_story_5037_50370301_45_dialog_content = "...",
  ui_story_5037_50370301_46_dialog_content = "Continuar...",
  ui_story_5037_50370301_47_dialog_content = "¡Una corbata!",
  ui_story_5037_50370301_48_dialog_content = "¿Qué?",
  ui_story_5037_50370301_49_dialog_content = "Nuestro novato se enfrentó al ídolo experimentado, por lo que fue un empate.",
  ui_story_5037_50370301_50_dialog_content = "Nuestro programa de variedades está lleno de giros y vueltas.",
  ui_story_5037_50370301_51_dialog_content = "¡No debería tener que preocuparme por las calificaciones de ahora en adelante!",
  ui_story_5037_50370301_52_dialog_content = "Permítanme recordarles, mis queridos.",
  ui_story_5037_50370301_53_dialog_content = "Ambos ídolos recibieron la misma cantidad de apoyo en este concierto...",
  ui_story_5037_50370301_54_dialog_content = "pero todavía tenemos <color=#793f76>dos</color> más conciertos para ir.",
  ui_story_5037_50370301_55_dialog_content = "Es el <color=#793f76>apoyo acumulativo de fans</color> ganas después de los tres conciertos que estoy considerando.",
  ui_story_5037_50370301_56_dialog_content = "Entonces, independientemente de cómo te hayas sentido con esta actuación,",
  ui_story_5037_50370301_57_dialog_content = "¡Prepárate para el próximo concierto de evaluación!",
  ui_story_5037_50370301_58_dialog_content = "¡Debo ser realmente talentoso para ahogar a la señorita Goldie!",
  ui_story_5037_50370301_59_dialog_content = "Pero no creo que mis viejos huesos puedan resistir más práctica, así que puedo irme a casa ahora—",
  ui_story_5037_50370301_60_dialog_content = "¡¿Me estás tomando el pelo?! Los resultados prueban...",
  ui_story_5037_50370301_61_dialog_content = "que si no te hubieras retenido nada y realmente te hubieras desempeñado a la altura de tu potencial, habríamos vencido a Goldie y PlayerName!",
  ui_story_5037_50370301_62_dialog_content = "Ahora tenemos que empezar de cero otra vez.",
  ui_story_5037_50370301_63_dialog_content = "¡Ni siquiera pienses en holgazanear la próxima vez, Maestro!",
  ui_story_5037_50370301_64_dialog_content = "¡Oye, Fía! ¿A dónde vas?",
  ui_story_5037_50370301_65_dialog_content = "La sala de ensayo para entrenar, duh!",
  ui_story_5037_50370301_66_dialog_content = "Oh, por el amor de... ¿Cuándo puedo tomarme un descanso?",
  ui_story_5037_50370301_67_dialog_content = "Kyllo! ¡Arrástralo aquí!",
  ui_story_5037_50370301_68_dialog_content = "¡Lo!",
  ui_story_5037_50370301_69_dialog_content = "¡Sé gentil! Kyllo...",
  ui_story_5037_50370301_70_dialog_content = "Vic fue tan impresionante?",
  ui_story_5037_50370301_71_dialog_content = "Sí, supe que tenía el potencial para ser popular en el momento en que lo vi.",
  ui_story_5037_50370301_72_dialog_content = "Además, Fia realmente ha estado trabajando duro como su productora.",
  ui_story_5037_50370301_73_dialog_content = "Escuché que ella misma ve practicar a Vic hasta la medianoche todos los días.",
  ui_story_5037_50370301_74_dialog_content = "De hecho, yo mismo lo vi un par de veces.",
  ui_story_5037_50370301_75_dialog_content = "¡Cada vez que Vic holgazaneaba, Fia le decía a Kyllo que le mordiera el tobillo!",
  ui_story_5037_50370301_76_dialog_content = "¿Es esa criatura realmente tan potente como motivador?",
  ui_story_5037_50370301_77_dialog_content = "¿Debería encontrar mi propio Kyllo para morderme el tobillo?",
  ui_story_5037_50370301_78_dialog_content = "No creo que sea necesario.",
  ui_story_5037_50370301_79_dialog_content = "¡Ya trabajas duro sin ese tipo de empuje externo!",
  ui_story_5037_50370301_80_dialog_content = "Yo soy el que realmente necesita un Kyllo.",
  ui_story_5037_50370301_81_dialog_content = "Un novato solo alcanzó a un ídolo notable como tú porque no trabajé lo suficiente.",
  ui_story_5037_50370301_82_dialog_content = "No necesitas verlo de esa manera, PlayerName.",
  ui_story_5037_50370301_83_dialog_content = "La popularidad nunca es una ciencia exacta.",
  ui_story_5037_50370301_84_dialog_content = "Al menos disfruté el espectáculo de hoy y no me arrepiento. ¡Eso es suficiente para mi!",
  ui_story_5037_50370301_85_dialog_content = "Gracias...",
  ui_story_5037_50370301_86_dialog_content = "¡Tú puedes consolarme, pero yo no puedo consolarme a mí mismo!",
  ui_story_5037_50370301_87_dialog_content = "¿Eh?",
  ui_story_5037_50370301_88_dialog_content = "Seguiré trabajando duro para comprender los matices de ser productor.",
  ui_story_5037_50370301_89_dialog_content = "para que pueda planificar un mejor horario de entrenamiento para ti.",
  ui_story_5037_50370301_90_dialog_content = "¡Luego haremos un concierto trascendental!",
  ui_story_5037_50370301_91_dialog_content = "PlayerName...",
  ui_story_5037_50370301_92_dialog_content = "Sólo uno no servirá. Todavía nos quedan dos shows más... ¡Y muchos más en el futuro!",
  ui_story_5037_50370301_93_dialog_content = "Bien, ¡déjame reformular eso!",
  ui_story_5037_50370301_94_dialog_content = "¡Todos nuestros conciertos serán estremecedores a partir de ahora!",
  ui_story_5037_50370301_95_dialog_content = "¡Sí!",
  ui_story_5037_50370301_96_dialog_content = "¡Espero con interes trabajar con usted!",
  ui_story_5037_50370301_97_dialog_content = "Entrevista a amigos post-concierto...",
  ui_story_5037_50370301_98_dialog_content = "¡Acción!",
  ui_story_5037_50370301_99_dialog_content = "En una escala del uno al diez, ¿cómo calificaría el concierto?",
  ui_story_5037_50370301_100_dialog_content = "¡El máximo diez, por supuesto!",
  ui_story_5037_50370301_101_dialog_content = "Yo diría ocho. Todavía hay margen de mejora.",
  ui_story_5037_50370301_102_dialog_content = "¿Qué pueden lograr esos dos juntos?",
  ui_story_5037_50370301_103_dialog_content = "¿Qué? Oh, sí, no vi el concierto.",
  ui_story_5037_50370301_104_dialog_content = "La respuesta fue muy positiva, ¿dijiste?",
  ui_story_5037_50370301_105_dialog_content = "¿Cómo calificaría la actuación contraria?",
  ui_story_5037_50370301_106_dialog_content = "Uh... Probablemente diez también, ya que vimos el esfuerzo que pusieron Vic y Fia.",
  ui_story_5037_50370301_107_dialog_content = "Otros ocho. Aún hay margen de mejora.",
  ui_story_5037_50370301_108_dialog_content = "¿Debo responder?",
  ui_story_5037_50370301_109_dialog_content = "¿Cómo ha cambiado tu amigo recientemente?",
  ui_story_5037_50370301_110_dialog_content = "PlayerName ahora es mucho más disciplinado y ya no se queda dormido.",
  ui_story_5037_50370301_111_dialog_content = "Aprende mucho más rápido de lo que esperaba, y realmente se adaptó al papel de productor con bastante rapidez.",
  ui_story_5037_50370301_112_dialog_content = "No sé, a mí me parecen iguales.",
  ui_story_5037_50370301_113_dialog_content = "¡Y eso es un final para las entrevistas posteriores al concierto!",
  ui_story_5037_50370301_114_dialog_content = "¿Qué? ¿Ya empezaron a practicar?",
  ui_story_5037_50370301_115_dialog_content = "¡Tengo que ir a filmar esto!",
  ui_story_5037_50370401_1_dialog_content = "¿Adónde debería ir este accesorio más grande, productor?",
  ui_story_5037_50370401_2_dialog_content = "Muévalo al centro del escenario y asegúrese de que esté perfectamente centrado.",
  ui_story_5037_50370401_3_dialog_content = "¿Qué tal esta iluminación, productor?",
  ui_story_5037_50370401_4_dialog_content = "Demasiado brillante. Bájalo un poco, por favor.",
  ui_story_5037_50370401_5_dialog_content = "¿Te importaría echar un vistazo a esto, productor?",
  ui_story_5037_50370401_6_dialog_content = "¿Qué pasa con este problema aquí, Productor?",
  ui_story_5037_50370401_7_dialog_content = "¡Productor! ¡Productor!",
  ui_story_5037_50370401_8_dialog_content = "¡Uno a la vez, uno a la vez...!",
  ui_story_5037_50370401_9_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50370401_10_dialog_content = "Uf, me alegro de que haya terminado.",
  ui_story_5037_50370401_11_dialog_content = "Buen trabajo.",
  ui_story_5037_50370401_12_dialog_content = "¿Estás listo, Goldie?",
  ui_story_5037_50370401_13_dialog_content = "¡Todo listo!",
  ui_story_5037_50370401_14_dialog_content = "¿El mismo de siempre?",
  ui_story_5037_50370401_15_dialog_content = "¡El mismo de siempre!",
  ui_story_5037_50370401_16_dialog_content = "Aquí.",
  ui_story_5037_50370401_17_dialog_content = "¡Gracias!",
  ui_story_5037_50370401_18_dialog_content = "Espera, ¿qué es \"lo mismo de siempre, lo mismo de siempre\"? ¿Estás hablando en código?",
  ui_story_5037_50370401_19_dialog_content = "¿Qué le acabas de dar a Goldie? PlayerName? Mi cámara no lo captó.",
  ui_story_5037_50370401_20_dialog_content = "Oh, es una cosa especial que tenemos.",
  ui_story_5037_50370401_21_dialog_content = "Sabiendo que me gustan las pastillas para la tos de menta, mi productor las lleva consigo todo el tiempo.",
  ui_story_5037_50370401_22_dialog_content = "Me acaba de dar una pieza, eso es todo.",
  ui_story_5037_50370401_23_dialog_content = "¿Cuándo desarrollaron ustedes dos tal química?",
  ui_story_5037_50370401_24_dialog_content = "Hmm, en los últimos días.",
  ui_story_5037_50370401_25_dialog_content = "Hemos estado trabajando juntos el tiempo suficiente ahora que podemos saber lo que el otro está pensando con solo mirar.",
  ui_story_5037_50370401_26_dialog_content = "Increíble...",
  ui_story_5037_50370401_27_dialog_content = "¡Espera!",
  ui_story_5037_50370401_28_dialog_content = "¿Qué se supone que voy a filmar si ustedes ni siquiera hablan?",
  ui_story_5037_50370401_29_dialog_content = "¿Quieres que vaya a tener una conversación con él ahora mismo?",
  ui_story_5037_50370401_30_dialog_content = "Eso sería demasiado falso.",
  ui_story_5037_50370401_31_dialog_content = "¡Lo se!",
  ui_story_5037_50370401_32_dialog_content = "¡Puedo entrevistarte como lo hice con tus amigos!",
  ui_story_5037_50370401_33_dialog_content = "¡Ejeje, soy un genio!",
  ui_story_5037_50370401_34_dialog_content = "¿Entrevistó a mis amigos? ¿Cuándo?",
  ui_story_5037_50370401_35_dialog_content = "¡Te enterarás cuando salga el programa!",
  ui_story_5037_50370401_36_dialog_content = "Ahora hagamos tiempo para... ¡la entrevista exclusiva previa al concierto!",
  ui_story_5037_50370401_37_dialog_content = "Equipo Exclusivo PlayerName evaluación concierto entrevista...",
  ui_story_5037_50370401_38_dialog_content = "¡Acción!",
  ui_story_5037_50370401_39_dialog_content = "¿Cuál es la diferencia entre un concierto de evaluación y un concierto de debut?",
  ui_story_5037_50370401_40_dialog_content = "Un concierto de debut solo prueba que puedo firmar como ídolo con la Agencia Starlit.",
  ui_story_5037_50370401_41_dialog_content = "Para mí, el concierto debut es como la puerta de entrada a mi sueño.",
  ui_story_5037_50370401_42_dialog_content = "Pero, ¿qué puedo hacer una vez que alcance mi sueño?",
  ui_story_5037_50370401_43_dialog_content = "Dar lo mejor de mis habilidades para probarme a mí mismo, naturalmente.",
  ui_story_5037_50370401_44_dialog_content = "El concierto de evaluación es una prueba de la agencia, con el objetivo de verificar cuánto hemos avanzado en nuestra formación.",
  ui_story_5037_50370401_45_dialog_content = "Pero para nosotros, es más como una prueba de nuestras habilidades de Goldilocks.",
  ui_story_5037_50370401_46_dialog_content = "Así es. Quiero demostrarles a todos...",
  ui_story_5037_50370401_47_dialog_content = "que no importa donde esté, ¡nunca olvidaré de dónde vengo!",
  ui_story_5037_50370401_48_dialog_content = "¿Sientes alguna presión preparándote para el concierto?",
  ui_story_5037_50370401_49_dialog_content = "¡Ninguno en absoluto!",
  ui_story_5037_50370401_50_dialog_content = "¡Es una broma! Es normal sentir presión.",
  ui_story_5037_50370401_51_dialog_content = "Pero estoy realmente agradecido de que mi productor me haya quitado mucho peso de encima.",
  ui_story_5037_50370401_52_dialog_content = "Pude concentrarme en el entrenamiento, lo que me facilitó mucho las cosas.",
  ui_story_5037_50370401_53_dialog_content = "En cuanto a hasta dónde llegó el entrenamiento... ¡lo verás en el escenario más tarde!",
  ui_story_5037_50370401_54_dialog_content = "¿Crees que producir es un trabajo duro?",
  ui_story_5037_50370401_55_dialog_content = "Honestamente, en el período justo antes del concierto debut, pasé por un momento muy difícil.",
  ui_story_5037_50370401_56_dialog_content = "Cometí un montón de errores en la preparación previa al espectáculo.",
  ui_story_5037_50370401_57_dialog_content = "Pero ahora me he adaptado bastante al trabajo y me he familiarizado con todos sus entresijos.",
  ui_story_5037_50370401_58_dialog_content = "Nunca cometeré el mismo error dos veces.",
  ui_story_5037_50370401_59_dialog_content = "Sí, ¡puedo testificar de eso!",
  ui_story_5037_50370401_60_dialog_content = "PlayerName es un productor muy profesional ahora.",
  ui_story_5037_50370401_61_dialog_content = "Y ha estado tan ocupado. Apenas había tiempo para dormir.",
  ui_story_5037_50370401_62_dialog_content = "Productor PlayerName ¡Realmente trabajé muy duro para prepararme para el concierto!",
  ui_story_5037_50370401_63_dialog_content = "Solo estaba haciendo mi trabajo.",
  ui_story_5037_50370401_64_dialog_content = "Poder ayudarlo a preparar el escenario más lujoso para darle a Goldilocks una actuación para recordar hizo que todo valiera la pena para mí.",
  ui_story_5037_50370401_65_dialog_content = "Para ser honesto, ¡ni siquiera me parece trabajo!",
  ui_story_5037_50370401_66_dialog_content = "¿Podría darnos una pequeña pista sobre lo que ha planeado para nosotros?",
  ui_story_5037_50370401_67_dialog_content = "Es un secreto.",
  ui_story_5037_50370401_68_dialog_content = "Nuestro programa esta vez es totalmente nuevo, nunca antes visto.",
  ui_story_5037_50370401_69_dialog_content = "En realidad, podemos divulgar el tema de nuestro concierto.",
  ui_story_5037_50370401_70_dialog_content = "Correcto.",
  ui_story_5037_50370401_71_dialog_content = "PlayerName se le ocurrieron tres temas diferentes para los tres conciertos.",
  ui_story_5037_50370401_72_dialog_content = "El tema del concierto debut fue <color=#793f76>Nuevo comienzo</color>. Espero que la audiencia capte el significado detrás de eso.",
  ui_story_5037_50370401_73_dialog_content = "El tema del próximo programa es <color=#793f76>Flor en ciernes</color>!",
  ui_story_5037_50370401_74_dialog_content = "Para eso, coreografié una rutina completamente nueva con la ayuda del productor.",
  ui_story_5037_50370401_75_dialog_content = "¡Definitivamente no gastarás dinero para ver un espectáculo antiguo!",
  ui_story_5037_50370401_76_dialog_content = "Yo solo me encargué de la logística. Goldie debería recibir la mayor parte del crédito.",
  ui_story_5037_50370401_77_dialog_content = "Al principio, iba a pedirle que repitiera algunas canciones viejas.",
  ui_story_5037_50370401_78_dialog_content = "Pero ella escribió varias canciones originales solo para el concierto.",
  ui_story_5037_50370401_79_dialog_content = "Eso es porque de repente me inspiré durante el entrenamiento un día.",
  ui_story_5037_50370401_80_dialog_content = "Desde que decidí convertirme en ídolo, la vida ha sido una batalla cuesta arriba que siempre luché por mi cuenta.",
  ui_story_5037_50370401_81_dialog_content = "Ahora, no solo tengo Productor PlayerName para ayudarme...",
  ui_story_5037_50370401_82_dialog_content = "pero también, tengo un oponente que busca el mismo objetivo.",
  ui_story_5037_50370401_83_dialog_content = "No, más que un oponente, creo que Vic es más un compañero en este viaje hacia el estrellato.",
  ui_story_5037_50370401_84_dialog_content = "Todos estos sentimientos novedosos me inspiraron a escribir muchas canciones nuevas.",
  ui_story_5037_50370401_85_dialog_content = "Los escuché muchas veces durante nuestros ensayos, pero cada vez que los escucho...",
  ui_story_5037_50370401_86_dialog_content = "todavía me conmueven hasta la médula.",
  ui_story_5037_50370401_87_dialog_content = "¡Creo que todos encontrarán nuestro programa sincero emocionalmente satisfactorio!",
  ui_story_5037_50370401_88_dialog_content = "Escuché que el productor reparte volantes todos los días para ayudar a Goldie.",
  ui_story_5037_50370401_89_dialog_content = "¿En serio? ¿Es eso cierto?",
  ui_story_5037_50370401_90_dialog_content = "Esta es la primera vez que escucho eso... ¿Cómo es que nunca me lo dijiste? PlayerName?",
  ui_story_5037_50370401_91_dialog_content = "Solo estaba haciendo mi trabajo.",
  ui_story_5037_50370401_92_dialog_content = "¡Ahora recuerdo!",
  ui_story_5037_50370401_93_dialog_content = "Hubo momentos en los que dijiste que estabas agarrando comida o bocadillos...",
  ui_story_5037_50370401_94_dialog_content = "¿Estabas repartiendo volantes en su lugar?",
  ui_story_5037_50370401_95_dialog_content = "Sí. Lo siento, no quería distraerte, Goldie. Por eso no te lo dije.",
  ui_story_5037_50370401_96_dialog_content = "Siempre dices que los resultados no son importantes, y que lo que importa es experimentar el viaje sin remordimientos...",
  ui_story_5037_50370401_97_dialog_content = "pero aún quiero ayudarlo a obtener más apoyo.",
  ui_story_5037_50370401_98_dialog_content = "Esa es la mejor manera de asegurarse de que no haya arrepentimientos, creo.",
  ui_story_5037_50370401_99_dialog_content = "PlayerName...",
  ui_story_5037_50370401_100_dialog_content = "¡Llévame contigo la próxima vez! ¡Una actuación en la calle definitivamente sería más llamativa!",
  ui_story_5037_50370401_101_dialog_content = "¡No olvides que somos un equipo!",
  ui_story_5037_50370401_102_dialog_content = "Un equipo... ¡Sí, somos un equipo!",
  ui_story_5037_50370401_103_dialog_content = "¿Te sientes confiado con el concierto?",
  ui_story_5037_50370401_104_dialog_content = "¿Confías en mí, PlayerName?",
  ui_story_5037_50370401_105_dialog_content = "He visto los ensayos de Goldie. Son perfectos, virtualmente impecables.",
  ui_story_5037_50370401_106_dialog_content = "¡Hoy no es más que un nuevo lugar, así que confío mucho en Goldie!",
  ui_story_5037_50370401_107_dialog_content = "¡Qué casualidad, yo también confío mucho en ti!",
  ui_story_5037_50370401_108_dialog_content = "¿El mismo de siempre?",
  ui_story_5037_50370401_109_dialog_content = "¡El mismo de siempre!",
  ui_story_5037_50370401_110_dialog_content = "¡Vamos! ¡Vamos! ¡Vamos!",
  ui_story_5037_50370401_111_dialog_content = "¿Adónde va este accesorio, productor?",
  ui_story_5037_50370401_112_dialog_content = "¿Dónde está el productor?",
  ui_story_5037_50370401_113_dialog_content = "¡Productor! ¡Productor!",
  ui_story_5037_50370401_114_dialog_content = "¡Ah, necesito ir a encargarme de las cosas!",
  ui_story_5037_50370401_115_dialog_content = "Uf...",
  ui_story_5037_50370401_116_dialog_content = "El concierto sería imposible sin PlayerName.",
  ui_story_5037_50370401_117_dialog_content = "¡Es hora de que me prepare para el escenario ahora!",
  ui_story_5037_50370501_1_dialog_content = "A continuación, anunciaré nuestros resultados.",
  ui_story_5037_50370501_2_dialog_content = "Son muy impactantes esta vez.",
  ui_story_5037_50370501_3_dialog_content = "(¿Qué escandalizaría incluso a Lady Sheol?)",
  ui_story_5037_50370501_4_dialog_content = "(¿Vic ganó...?)",
  ui_story_5037_50370501_5_dialog_content = "El ganador superó la presión provocada por el primer concierto para ganar aún más apoyo en la audiencia esta vez.",
  ui_story_5037_50370501_6_dialog_content = "Estos fueron los frutos del arduo trabajo del ídolo.",
  ui_story_5037_50370501_7_dialog_content = "Así como la del productor, por supuesto.",
  ui_story_5037_50370501_8_dialog_content = "(Trabajo duro de ambas partes... Ese es el Maestro y yo, ¿no es así?)",
  ui_story_5037_50370501_9_dialog_content = "(¡Sí, Master finalmente venció a Goldie!)",
  ui_story_5037_50370501_10_dialog_content = "Y el ganador es...",
  ui_story_5037_50370501_11_dialog_content = "...",
  ui_story_5037_50370501_12_dialog_content = "Jeje!",
  ui_story_5037_50370501_13_dialog_content = "<size=45>Goldie y PlayerName!</size>",
  ui_story_5037_50370501_14_dialog_content = "Se enteró que, PlayerName? ¡Ganamos!",
  ui_story_5037_50370501_15_dialog_content = "¿Ganamos?",
  ui_story_5037_50370501_16_dialog_content = "¿Qué? ¿Cómo puede ser esto?",
  ui_story_5037_50370501_17_dialog_content = "Por fin, un paso más cerca de casa.",
  ui_story_5037_50370501_18_dialog_content = "Los hechos son duros, pero los números no mienten, y esta vez más personas apoyaron a Goldie que a Vic.",
  ui_story_5037_50370501_19_dialog_content = "Pero la actuación de Master obviamente fue mejor que la última vez, entonces, ¿cómo es que ganó Goldie?",
  ui_story_5037_50370501_20_dialog_content = "Bueno, Goldie realmente dio una actuación fantástica esta vez.",
  ui_story_5037_50370501_21_dialog_content = "El espectáculo en sí fue creativo, pero la iluminación y el diseño del escenario también fueron impecables.",
  ui_story_5037_50370501_22_dialog_content = "Lo que es más importante es que su concierto convirtió a muchos de la audiencia en sus fans.",
  ui_story_5037_50370501_23_dialog_content = "Corrieron al Cloudrover Guild y compraron su mercancía.",
  ui_story_5037_50370501_24_dialog_content = "Incluso compraron productos que no tenían nada que ver con Goldie.",
  ui_story_5037_50370501_25_dialog_content = "A través del boca a boca de los Ricitos de Oro...",
  ui_story_5037_50370501_26_dialog_content = "Ver un concierto de Goldie es ahora una de las diez cosas que debe hacer en Umbraton.",
  ui_story_5037_50370501_27_dialog_content = "Todo el mundo espera con ansias el próximo concierto de Starlit Agency.",
  ui_story_5037_50370501_28_dialog_content = "¡Las entradas ya están agotadas! ¿Puedes ceerlo?",
  ui_story_5037_50370501_29_dialog_content = "¿Quieres decir que no tengo que rogarle a la gente que compre boletos ahora?",
  ui_story_5037_50370501_30_dialog_content = "Nunca pensé que recuperaría mi inversión incluso antes de que saliera al aire el reality show.",
  ui_story_5037_50370501_31_dialog_content = "Ya no tienes que hacer promociones adicionales para conseguir nuevos fans.",
  ui_story_5037_50370501_32_dialog_content = "¡Concéntrate en tu actuación y disfruta del concierto final!",
  ui_story_5037_50370501_33_dialog_content = "Gracias, señora Sheol.",
  ui_story_5037_50370501_34_dialog_content = "¡Nos esforzaremos por mejorar y recompensarte a ti y a los fanáticos con mejores actuaciones!",
  ui_story_5037_50370501_35_dialog_content = "Creo que todavía no he sabido nada de ti, Vic.",
  ui_story_5037_50370501_36_dialog_content = "¿Por qué no lo olvidamos?",
  ui_story_5037_50370501_37_dialog_content = "Ya que perdí, ¡podrías dejarme ir a casa ahora!",
  ui_story_5037_50370501_38_dialog_content = "No lo compro, simplemente no lo compro.",
  ui_story_5037_50370501_39_dialog_content = "Creo que todos ustedes conspiraron contra el Maestro y contra mí.",
  ui_story_5037_50370501_40_dialog_content = "¡Dime, Señora Seol!",
  ui_story_5037_50370501_41_dialog_content = "Así es como escribiste el guión, ¿verdad?",
  ui_story_5037_50370501_42_dialog_content = "¿Un guión para un reality show?",
  ui_story_5037_50370501_43_dialog_content = "Eres un genio, Fia.",
  ui_story_5037_50370501_44_dialog_content = "¡Claro que soy yo! Jeje.",
  ui_story_5037_50370501_45_dialog_content = "Espera un segundo, ¿qué te hizo decir eso?",
  ui_story_5037_50370501_46_dialog_content = "¿Cómo es que no se me ocurrió algo tan creativo como escribir un guión para el reality show?",
  ui_story_5037_50370501_47_dialog_content = "Probablemente recuperaría mi dinero más rápido.",
  ui_story_5037_50370501_48_dialog_content = "Sin embargo, Fia, los resultados de esta ronda son genuinos.",
  ui_story_5037_50370501_49_dialog_content = "Si aún tienes dudas, no dudes en ver la repetición del concierto.",
  ui_story_5037_50370501_50_dialog_content = "Ven a hablar conmigo en cualquier momento si tienes preguntas después.",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50370501_52_dialog_content = "¿Cómo hicieron eso? ¡¿Cómo lograron el truco?!",
  ui_story_5037_50370501_53_dialog_content = "¿¡Goldie se cambió de ropa en solo un segundo!?",
  ui_story_5037_50370501_54_dialog_content = "¿Y apareció de la nada en la audiencia, luego voló de regreso al escenario?",
  ui_story_5037_50370501_55_dialog_content = "En contraste, nuestro concierto se quedó más que un poco corto.",
  ui_story_5037_50370501_56_dialog_content = "No es de extrañar que nunca pudiste hacerlo antes...",
  ui_story_5037_50370501_57_dialog_content = "Oh, ejem.",
  ui_story_5037_50370501_58_dialog_content = "¿Así que finalmente lo entiendes ahora? A pesar de mi gran talento, no puedo estar a la altura de un ídolo profesional.",
  ui_story_5037_50370501_59_dialog_content = "No es demasiado pronto para conceder ahora. Iré a empacar.",
  ui_story_5037_50370501_60_dialog_content = "¡Alto!",
  ui_story_5037_50370501_61_dialog_content = "Lo sé incluso sin que lo digas...",
  ui_story_5037_50370501_62_dialog_content = "que no es tu culpa que perdimos.",
  ui_story_5037_50370501_63_dialog_content = "Soy el productor, pero estaba tan obsesionado con tu entrenamiento que descuidé casi todos los demás aspectos del espectáculo y el escenario.",
  ui_story_5037_50370501_64_dialog_content = "Pensé que eras la clave del éxito todo este tiempo...",
  ui_story_5037_50370501_65_dialog_content = "¡Hasta que vi el programa de Goldie y me di cuenta de cuánto potencial puede tener un concierto!",
  ui_story_5037_50370501_66_dialog_content = "Tu desempeño fue sobresaliente.",
  ui_story_5037_50370501_67_dialog_content = "Pero fallé en darte el escenario perfecto.",
  ui_story_5037_50370501_68_dialog_content = "Honestamente, terminar el concierto fue lo suficientemente bueno para mí, así que no te preocupes por eso y vámonos a casa...",
  ui_story_5037_50370501_69_dialog_content = "¡De ninguna manera, no puedo ir todavía!",
  ui_story_5037_50370501_70_dialog_content = "Tenemos un último programa que hacer. Todavía podemos cambiar las cosas.",
  ui_story_5037_50370501_71_dialog_content = "¡Esta vez, te prometo que podrás alcanzar tu sueño de ídolo y no te arrepentirás!",
  ui_story_5037_50370501_72_dialog_content = "¿Qué...?",
  ui_story_5037_50370501_73_dialog_content = "Acabo de ver la repetición del concierto de Vic.",
  ui_story_5037_50370501_74_dialog_content = "Tu actuación fue como la de un ídolo profesional, Vic.",
  ui_story_5037_50370501_75_dialog_content = "Solo había algunos bailes que no mostraban adecuadamente tu encanto.",
  ui_story_5037_50370501_76_dialog_content = "¿En serio? ¿Cuáles?",
  ui_story_5037_50370501_77_dialog_content = "Haré una revisión más tarde y te lo mostraré, Fia.",
  ui_story_5037_50370501_78_dialog_content = "Por cierto, escribí una nueva balada que creo que le quedaría bien a Vic.",
  ui_story_5037_50370501_79_dialog_content = "¡Te lo daré a ti también cuando termine con la reseña!",
  ui_story_5037_50370501_80_dialog_content = "¡Maravilloso!",
  ui_story_5037_50370501_81_dialog_content = "Pero es... ¿es esto apropiado?",
  ui_story_5037_50370501_82_dialog_content = "Eres nuestro competidor, así que ¿por qué nos ayudas?",
  ui_story_5037_50370501_83_dialog_content = "Se supone que los ídolos traen esperanza y bondad a las personas.",
  ui_story_5037_50370501_84_dialog_content = "¿Cómo puedo ser llamado ídolo si ni siquiera puedo traer bondad a quienes me rodean?",
  ui_story_5037_50370501_85_dialog_content = "Recuerdo lo que dijiste antes en una entrevista...",
  ui_story_5037_50370501_86_dialog_content = "Más que un oponente, creo que Vic es más parecido a un compañero en este viaje hacia el estrellato.",
  ui_story_5037_50370501_87_dialog_content = "Fue realmente brillante...",
  ui_story_5037_50370501_88_dialog_content = "¡¡Asombroso!!",
  ui_story_5037_50370501_89_dialog_content = "¿Así es como se supone que debe actuar un ídolo?",
  ui_story_5037_50370501_90_dialog_content = "¡Oh, no!",
  ui_story_5037_50370501_91_dialog_content = "¡La gente va a pensar que el Maestro es una broma por decir lo que le dije en la entrevista!",
  ui_story_5037_50370501_92_dialog_content = "(Me pregunto qué dijeron en la entrevista...)",
  ui_story_5037_50370501_93_dialog_content = "¿Te importaría borrar la entrevista que hicimos y filmar otra, Lilica?",
  ui_story_5037_50370501_94_dialog_content = "Me temo que eso no es posible.",
  ui_story_5037_50370501_95_dialog_content = "Esto es un reality show, ¿sabes?",
  ui_story_5037_50370501_96_dialog_content = "¡Ven aquí, Kyllo!",
  ui_story_5037_50370501_97_dialog_content = "¡Lo!",
  ui_story_5037_50370501_98_dialog_content = "Oye, ¿qué crees que estás haciendo?",
  ui_story_5037_50370501_99_dialog_content = "¡No rehacer incluso si haces que Kyllo me muerda el tobillo!",
  ui_story_5037_50370501_100_dialog_content = "¡Espera, no huyas!",
  ui_story_5037_50370501_101_dialog_content = "Si estás de acuerdo, ¡puedes jugar con Kyllo!",
  ui_story_5037_50370501_102_dialog_content = "Hmm, creo que Fia se ha olvidado por completo de mí...",
  ui_story_5037_50370501_103_dialog_content = "¡Finalmente puedo dormir bien!",
  ui_story_5037_50370501_104_dialog_content = "¡Hasta luego!",
  ui_story_5037_50370501_105_dialog_content = "¡El concierto de evaluación finalmente ha terminado, productor!",
  ui_story_5037_50370501_106_dialog_content = "Trabajaste muy duro para lograrlo, Goldie.",
  ui_story_5037_50370501_107_dialog_content = "Y qué espectáculo tan espectacular fue... ¿Me atrevo a llamarlo el mejor de todos los tiempos?",
  ui_story_5037_50370501_108_dialog_content = "no seamos precipitados, PlayerName.",
  ui_story_5037_50370501_109_dialog_content = "¿No tenemos uno más para ir?",
  ui_story_5037_50370501_110_dialog_content = "Verdadero. ¡El mejor espectáculo es siempre el siguiente!",
  ui_story_5037_50370501_111_dialog_content = "Jaja, esa es una gran línea!",
  ui_story_5037_50370501_112_dialog_content = "¿Ya tienes decidido el tema del último concierto?",
  ui_story_5037_50370501_113_dialog_content = "Oh, es cierto, todavía necesito desarrollarlo.",
  ui_story_5037_50370501_114_dialog_content = "¡No te preocupes por mí, descansa un poco!",
  ui_story_5037_50370501_115_dialog_content = "¡Está bien! Tú también haces lo mismo, PlayerName!",
  ui_story_5037_50370501_116_dialog_content = "Malvavisco.",
  ui_story_5037_50370501_117_dialog_content = "¡Wau!",
  ui_story_5037_50370501_118_dialog_content = "Había un ladrón robando cosas en el concierto.",
  ui_story_5037_50370501_119_dialog_content = "¿También te diste cuenta?",
  ui_story_5037_50370501_120_dialog_content = "¡Wau!",
  ui_story_5037_50370501_121_dialog_content = "No puedo creer que alguien se atreva a hacer eso en mi show...",
  ui_story_5037_50370501_122_dialog_content = "¿Estás listo, malvavisco?",
  ui_story_5037_50370501_123_dialog_content = "¡Vamos a impartir justicia rápida esta noche!",
  ui_story_5037_50370501_124_dialog_content = "¡Wau!",
  ui_story_5037_50370501_125_dialog_content = "Entrevista a amigos post-concierto...",
  ui_story_5037_50370501_126_dialog_content = "¡Acción!",
  ui_story_5037_50370501_127_dialog_content = "En una escala del uno al diez, ¿cómo calificaría el concierto?",
  ui_story_5037_50370501_128_dialog_content = "¡Doce seguro!",
  ui_story_5037_50370501_129_dialog_content = "Cerca de un diez.",
  ui_story_5037_50370501_130_dialog_content = "Pfft, no puedo creer que ese tipo estuviera realmente cantando y bailando en el escenario...",
  ui_story_5037_50370501_131_dialog_content = "Pero no quiero dar una puntuación.",
  ui_story_5037_50370501_132_dialog_content = "¿Por qué? Porque no quiero que esos dos piensen demasiado de sí mismos.",
  ui_story_5037_50370501_133_dialog_content = "¿Cómo te sientes acerca del concierto del oponente?",
  ui_story_5037_50370501_134_dialog_content = "¡Diez!",
  ui_story_5037_50370501_135_dialog_content = "Estuvo impecable, pero el espectáculo de Goldie obviamente fue mucho más atractivo.",
  ui_story_5037_50370501_136_dialog_content = "Nueve.",
  ui_story_5037_50370501_137_dialog_content = "No lo vi, pero probablemente no tan bien como Fia y Vic.",
  ui_story_5037_50370501_138_dialog_content = "¿Hay algo que quieras decirle a tu amigo?",
  ui_story_5037_50370501_139_dialog_content = "Se tu mismo y ve por ellos, PlayerName!",
  ui_story_5037_50370501_140_dialog_content = "El esfuerzo produce resultados.",
  ui_story_5037_50370501_141_dialog_content = "¿Escuché que hay premios en metálico?",
  ui_story_5037_50370501_142_dialog_content = "¡Será mejor que se lo lleven a casa!",
  ui_story_5037_50370501_143_dialog_content = "Si no...!",
  ui_story_5037_50370501_144_dialog_content = "¡No envuelva los tentáculos alrededor de la cámara!",
  ui_story_5037_50370601_1_dialog_content = "Equipo Exclusivo PlayerName entrevista pre-final del concierto...",
  ui_story_5037_50370601_2_dialog_content = "¡Acción!",
  ui_story_5037_50370601_3_dialog_content = "¿Cuál es el tema que habéis elegido para el concierto final?",
  ui_story_5037_50370601_4_dialog_content = "Nuestro tema esta vez es \"Juventud desenfrenada\".",
  ui_story_5037_50370601_5_dialog_content = "Oh por cierto...",
  ui_story_5037_50370601_6_dialog_content = "El concierto es final solo de nombre. Goldie no dejará la Agencia Starlit.",
  ui_story_5037_50370601_7_dialog_content = "Así es, desde \"Nuevo comienzo\" hasta \"Flor en ciernes\" y \"Juventud desenfrenada\"...",
  ui_story_5037_50370601_8_dialog_content = "Las tres actuaciones están destinadas a presentar el microcosmos de la metamorfosis de un ídolo a lo largo del reality show.",
  ui_story_5037_50370601_9_dialog_content = "Goldie permanecerá activa incluso después de que finalice el programa.",
  ui_story_5037_50370601_10_dialog_content = "Eso es verdad. Tendré más shows por venir!",
  ui_story_5037_50370601_11_dialog_content = "Aunque puede que ya no sea el productor de Goldie para entonces...",
  ui_story_5037_50370601_12_dialog_content = "...",
  ui_story_5037_50370601_13_dialog_content = "Bueno, es muy difícil convertirse en productor de la Agencia Starlit.",
  ui_story_5037_50370601_14_dialog_content = "Tienes que enviar un currículum y pasar todo tipo de pruebas.",
  ui_story_5037_50370601_15_dialog_content = "Incluso un productor destacado como PlayerName tendría dudas.",
  ui_story_5037_50370601_16_dialog_content = "Si no fuera por el reality show, probablemente me habría perdido en la confusión entre los talentos de Umbraton.",
  ui_story_5037_50370601_17_dialog_content = "Después de que termine el programa, no creo que pueda vencer a otras personas para convertirme en un verdadero productor.",
  ui_story_5037_50370601_18_dialog_content = "Pero estoy satisfecho con la oportunidad de ver a Goldie en esta parte de su carrera.",
  ui_story_5037_50370601_19_dialog_content = "PlayerName...",
  ui_story_5037_50370601_20_dialog_content = "¡Es demasiado pronto para ponerse sentimental!",
  ui_story_5037_50370601_21_dialog_content = "¿Escribiste nuevas canciones para este concierto, Goldie?",
  ui_story_5037_50370601_22_dialog_content = "Por supuesto.",
  ui_story_5037_50370601_23_dialog_content = "Después de aprender PlayerName eligió \"Juventud desenfrenada\" para el tema...",
  ui_story_5037_50370601_24_dialog_content = "Me pregunté: \"¿Qué es exactamente la juventud?\"",
  ui_story_5037_50370601_25_dialog_content = "Inmediatamente, las imágenes llenaron mi cabeza.",
  ui_story_5037_50370601_26_dialog_content = "¿Es persiguiéndose, despreocupados, por las calles de Umbraton?",
  ui_story_5037_50370601_27_dialog_content = "¿Es escuchar una conferencia en un salón de clases con ojos soñolientos?",
  ui_story_5037_50370601_28_dialog_content = "¿O es sudar en tu trabajo para ganarte la vida?",
  ui_story_5037_50370601_29_dialog_content = "Entonces me recordé a mí mismo, la juventud no es rígida y está grabada en piedra.",
  ui_story_5037_50370601_30_dialog_content = "¡Cada forma de juventud merece ser celebrada!",
  ui_story_5037_50370601_31_dialog_content = "A partir de esas imágenes compuse las canciones que deseaba interpretar.",
  ui_story_5037_50370601_32_dialog_content = "¿Cómo te sientes acerca de las nuevas canciones de Goldie esta vez? PlayerName?",
  ui_story_5037_50370601_33_dialog_content = "¡Oh, nunca puedes equivocarte con sus canciones!",
  ui_story_5037_50370601_34_dialog_content = "Los que escribió para \"Unbridled Youth\" son particularmente cautivadores.",
  ui_story_5037_50370601_35_dialog_content = "Especialmente la canción sobre la separación de caminos...",
  ui_story_5037_50370601_36_dialog_content = "Lady Sheol ya lo tomó para el tema final del reality show.",
  ui_story_5037_50370601_37_dialog_content = "Es cierto que nada es para siempre y la despedida es inevitable...",
  ui_story_5037_50370601_38_dialog_content = "pero seguiré trabajando duro, seguiré siendo relevante y creceré junto a todos.",
  ui_story_5037_50370601_39_dialog_content = "¡Así que mantén tus ojos en el desarrollo de mi carrera!",
  ui_story_5037_50370601_40_dialog_content = "¿Algo que quieras decirle a tu productor, Goldie?",
  ui_story_5037_50370601_41_dialog_content = "¿Qué? ¿Estás preguntando eso antes del concierto?",
  ui_story_5037_50370601_42_dialog_content = "Está bien.",
  ui_story_5037_50370601_43_dialog_content = "De todos modos, ¡podría estar demasiado emocionada para hablar después del concierto!",
  ui_story_5037_50370601_44_dialog_content = "¿Ah?",
  ui_story_5037_50370601_45_dialog_content = "Ejem, lo que me gustaría decirle a mi productor es:",
  ui_story_5037_50370601_46_dialog_content = "Gracias por aguantarme todo este tiempo.",
  ui_story_5037_50370601_47_dialog_content = "Para ser honesto, siempre he ido solo en este negocio, así que no estoy acostumbrado a tener un productor.",
  ui_story_5037_50370601_48_dialog_content = "Es solo para el programa de telerrealidad que acepté contratarte como mi productor.",
  ui_story_5037_50370601_49_dialog_content = "Pero desde entonces, has pasado de ser un novato total a un profesional consumado.",
  ui_story_5037_50370601_50_dialog_content = "No solo manejaste mi agenda, sino que también trataste con los paparazzi y resolviste los detalles del concierto...",
  ui_story_5037_50370601_51_dialog_content = "Tu presencia me permitió crear y ensayar con tranquilidad.",
  ui_story_5037_50370601_52_dialog_content = "De hecho, me resulta cada vez más difícil imaginar hacer esto sin ti.",
  ui_story_5037_50370601_53_dialog_content = "Tal vez nunca vuelvas a ser productor, pero aún quiero que sepas...",
  ui_story_5037_50370601_54_dialog_content = "eres el mejor productor para mi...",
  ui_story_5037_50370601_55_dialog_content = "... hasta aquí.",
  ui_story_5037_50370601_56_dialog_content = "Pero soy el único productor que has tenido.",
  ui_story_5037_50370601_57_dialog_content = "No he terminado aún. ¡Tienes mi apoyo en el futuro sin importar a dónde vayas o lo que hagas!",
  ui_story_5037_50370601_58_dialog_content = "Estoy seguro de que sobresaldrás en lo que elijas hacer.",
  ui_story_5037_50370601_59_dialog_content = "Y cuando llegue ese momento...",
  ui_story_5037_50370601_60_dialog_content = "Yo también...",
  ui_story_5037_50370601_61_dialog_content = "¿Goldie?",
  ui_story_5037_50370601_62_dialog_content = "Tos...",
  ui_story_5037_50370601_63_dialog_content = "<size=30>Por favor, edita eso, Lilica, ¡y déjame empezar de nuevo!</size>",
  ui_story_5037_50370601_64_dialog_content = "¡Tienes mi apoyo en el futuro sin importar a dónde vayas o lo que hagas!",
  ui_story_5037_50370601_65_dialog_content = "Estoy seguro de que sobresaldrás en lo que elijas hacer.",
  ui_story_5037_50370601_66_dialog_content = "¡Mientras haces eso, seguiré esforzándome en el camino que elegí, construyendo sobre la base que me has preparado!",
  ui_story_5037_50370601_67_dialog_content = "¿Algo que quieras decirle a Goldie, productor?",
  ui_story_5037_50370601_68_dialog_content = "Quiero agradecer a Goldie también.",
  ui_story_5037_50370601_69_dialog_content = "Gracias a tu apoyo, hice tantas cosas con las que no me hubiera atrevido a soñar.",
  ui_story_5037_50370601_70_dialog_content = "¡Llegamos hasta aquí solo porque ya eres una estrella brillante!",
  ui_story_5037_50370601_71_dialog_content = "Todas las habilidades que he aprendido y desarrollado durante este tiempo...",
  ui_story_5037_50370601_72_dialog_content = "¡Cada bit es un reflejo de la brillantez que es Goldie!",
  ui_story_5037_50370601_73_dialog_content = "Tú también eres brillante, PlayerName!",
  ui_story_5037_50370601_74_dialog_content = "Incluso cuando ya no esté a tu lado, Goldie...",
  ui_story_5037_50370601_75_dialog_content = "Siempre serás una estrella brillante.",
  ui_story_5037_50370601_76_dialog_content = "¡Un día, serás un ídolo legendario en Astra!",
  ui_story_5037_50370601_77_dialog_content = "Y siempre tendrás mis saludos y bendiciones.",
  ui_story_5037_50370601_78_dialog_content = "Equipo Exclusivo PlayerName entrevista pre-final del concierto...",
  ui_story_5037_50370601_79_dialog_content = "es una envoltura!",
  ui_story_5037_50370601_80_dialog_content = "...",
  ui_story_5037_50370601_81_dialog_content = "...",
  ui_story_5037_50370601_82_dialog_content = "Uh, ¿qué pasa con el silencio incómodo?",
  ui_story_5037_50370601_83_dialog_content = "¿No debería haber hecho esas preguntas?",
  ui_story_5037_50370601_84_dialog_content = "¿Este tipo de entrevista pone un freno a la atmósfera del programa?",
  ui_story_5037_50370601_85_dialog_content = "Por favor, dime que no afectará tu próxima actuación...",
  ui_story_5037_50370601_86_dialog_content = "Está bien, Lilica.",
  ui_story_5037_50370601_87_dialog_content = "¡Ves, estoy totalmente bien!",
  ui_story_5037_50370601_88_dialog_content = "¡Maravilloso, esa es la sonrisa de Goldie con la que estamos familiarizados!",
  ui_story_5037_50370601_89_dialog_content = "Productor PlayerName!",
  ui_story_5037_50370601_90_dialog_content = "Sí, aquí.",
  ui_story_5037_50370601_91_dialog_content = "¡Gracias!",
  ui_story_5037_50370601_92_dialog_content = "Espera, ¿me perdí algo otra vez?",
  ui_story_5037_50370601_93_dialog_content = "¡Ah!",
  ui_story_5037_50370601_94_dialog_content = "Estas mentas realmente me calman.",
  ui_story_5037_50370601_95_dialog_content = "Disculpe, ¿hacia dónde va el concierto de Goldie?",
  ui_story_5037_50370601_96_dialog_content = "¿Cómo llegó un miembro de la audiencia al backstage?",
  ui_story_5037_50370601_97_dialog_content = "¡Simplemente siga este pasaje y gire a la izquierda!",
  ui_story_5037_50370601_98_dialog_content = "Wow, no puedo creer esta suerte! ¿No es esta Goldie en persona?",
  ui_story_5037_50370601_99_dialog_content = "¡Sí lo es! ¿Puedes firmar mi camiseta, Goldie?",
  ui_story_5037_50370601_100_dialog_content = "¡Vine todo el camino desde Northland!",
  ui_story_5037_50370601_101_dialog_content = "¡Yo también soy fan! ¡Soy de la Llave Rediesel!",
  ui_story_5037_50370601_102_dialog_content = "¡Soy de la isla de las nubes!",
  ui_story_5037_50370601_103_dialog_content = "¡Soy de Euforia!",
  ui_story_5037_50370601_104_dialog_content = "¡Todos, todos!",
  ui_story_5037_50370601_105_dialog_content = "Goldie tendrá tiempo para autografiar y tomarse fotos con todos después del espectáculo.",
  ui_story_5037_50370601_106_dialog_content = "Deberías dirigirte al lugar ahora porque el concierto comenzará pronto.",
  ui_story_5037_50370601_107_dialog_content = "¿Autógrafos y fotos después del show?",
  ui_story_5037_50370601_108_dialog_content = "¡Voy a ir al concierto primero, entonces!",
  ui_story_5037_50370601_109_dialog_content = "¡Apuro! ¡Apuesto a que los que lleguen primero serán los primeros en la fila para autógrafos!",
  ui_story_5037_50370601_110_dialog_content = "No necesitas apresurarte. ¡Todos tendrán una oportunidad!",
  ui_story_5037_50370601_111_dialog_content = "Huyeron tan rápido que no creo que captaran nada de lo que dije.",
  ui_story_5037_50370601_112_dialog_content = "¡Hay tanta gente esta vez, de todas partes!",
  ui_story_5037_50370601_113_dialog_content = "¡Es una buena señal para la futura gira Astra de Goldie!",
  ui_story_5037_50370601_114_dialog_content = "¿Qué pasa, Goldie?",
  ui_story_5037_50370601_115_dialog_content = "De repente estoy tan nervioso.",
  ui_story_5037_50370601_116_dialog_content = "Se siente como si estuviera subiendo al escenario por primera vez...",
  ui_story_5037_50370601_117_dialog_content = "Mira a la audiencia, Goldie.",
  ui_story_5037_50370601_118_dialog_content = "¡Vinieron porque te aman!",
  ui_story_5037_50370601_119_dialog_content = "Y mereces ser amado.",
  ui_story_5037_50370601_120_dialog_content = "PlayerName...",
  ui_story_5037_50370601_121_dialog_content = "¡Estás en lo correcto!",
  ui_story_5037_50370601_122_dialog_content = "No soy la persona que solía ser.",
  ui_story_5037_50370601_123_dialog_content = "¡Tú solo mira!",
  ui_story_5037_50370601_124_dialog_content = "actuaré...",
  ui_story_5037_50370601_125_dialog_content = "a lo mejor de mis habilidades!",
  ui_story_5037_50370701_1_dialog_content = "El concierto de graduación fue un éxito.",
  ui_story_5037_50370701_2_dialog_content = "La iluminación y la utilería fueron perfectas, al igual que la actuación de Goldie.",
  ui_story_5037_50370701_3_dialog_content = "Presentamos todo lo que queríamos hasta el más mínimo detalle.",
  ui_story_5037_50370701_4_dialog_content = "La multitud coreó el nombre de Goldie y se quedó allí durante mucho tiempo.",
  ui_story_5037_50370701_5_dialog_content = "No había nada más que emoción y alegría en todo el escenario.",
  ui_story_5037_50370701_6_dialog_content = "Pero entonces...",
  ui_story_5037_50370701_7_dialog_content = "¿Por qué de repente me siento triste?",
  ui_story_5037_50370701_8_dialog_content = "¡Oh!",
  ui_story_5037_50370701_9_dialog_content = "¡Casi lo olvido, se supone que Lady Sheol debe anunciar los resultados finales ahora mismo!",
  ui_story_5037_50370701_10_dialog_content = "¡Se me hace tarde!",
  ui_story_5037_50370701_11_dialog_content = "Uf... uf...",
  ui_story_5037_50370701_12_dialog_content = "¡Perdón por llegar tarde!",
  ui_story_5037_50370701_13_dialog_content = "Un poco más y creo que decidiste renunciar, productor. PlayerName.",
  ui_story_5037_50370701_14_dialog_content = "¿Dónde está Goldie? ¿Cómo es que viniste solo?",
  ui_story_5037_50370701_15_dialog_content = "Goldie está atada, mezclándose con los fans.",
  ui_story_5037_50370701_16_dialog_content = "¡Hmph! ¡Mi maestro actualmente está siendo invadido por fanáticos que también quieren fotos!",
  ui_story_5037_50370701_17_dialog_content = "Mis queridos ídolos seguro que son populares.",
  ui_story_5037_50370701_18_dialog_content = "Está bien. ¡Muy buena señal!",
  ui_story_5037_50370701_19_dialog_content = "Me encantaría esperar a que terminen para poder felicitarlos a ambos en persona.",
  ui_story_5037_50370701_20_dialog_content = "Pero tengo una cita con un ejecutivo de un estudio de cine más tarde.",
  ui_story_5037_50370701_21_dialog_content = "Pareces más ocupado que nosotros.",
  ui_story_5037_50370701_22_dialog_content = "Está bien, solo dinos el resultado, Lady Sheol.",
  ui_story_5037_50370701_23_dialog_content = "No puedes esperar, ¿verdad, Fia?",
  ui_story_5037_50370701_24_dialog_content = "Pero eso no es algo malo. Era evidente desde el concierto de Vic...",
  ui_story_5037_50370701_25_dialog_content = "que aprendiste a planificar un espectáculo en muy poco tiempo.",
  ui_story_5037_50370701_26_dialog_content = "El concierto de graduación de Vic mostró mejoras significativas en la presentación.",
  ui_story_5037_50370701_27_dialog_content = "¡Claro que me esforcé mucho!",
  ui_story_5037_50370701_28_dialog_content = "En cuanto a Goldie, su espectáculo ya era casi insuperable.",
  ui_story_5037_50370701_29_dialog_content = "Pero PlayerName aun así logró insertar sorpresas en el escenario para que la audiencia disfrutara.",
  ui_story_5037_50370701_30_dialog_content = "Junto con las nuevas canciones de Goldie, fue conmovedor y conmovedor.",
  ui_story_5037_50370701_31_dialog_content = "¿Qué? Pensé que solo yo recibiría todos los elogios.",
  ui_story_5037_50370701_32_dialog_content = "Ahora en cuanto a los resultados, Team Fia—",
  ui_story_5037_50370701_33_dialog_content = "¿Que que que?",
  ui_story_5037_50370701_34_dialog_content = "¡¿Gané?!",
  ui_story_5037_50370701_35_dialog_content = "Déjame terminar, cariño.",
  ui_story_5037_50370701_36_dialog_content = "Desafortunadamente, el Equipo Fia perdió contra el Equipo PlayerName por un margen muy estrecho.",
  ui_story_5037_50370701_37_dialog_content = "Ganaron por apenas 10 boletos.",
  ui_story_5037_50370701_38_dialog_content = "¿Ah?",
  ui_story_5037_50370701_39_dialog_content = "Después de contar los resultados de los tres conciertos, la victoria es para...",
  ui_story_5037_50370701_40_dialog_content = "<size=45>PlayerName y Goldie!</size>",
  ui_story_5037_50370701_41_dialog_content = "...",
  ui_story_5037_50370701_42_dialog_content = "Waah...!",
  ui_story_5037_50370701_43_dialog_content = "Trabajé tan duro...",
  ui_story_5037_50370701_44_dialog_content = "Pasé mucho tiempo manteniendo a raya a mi maestro indisciplinado, pero también tuve que quedarme despierto toda la noche aprendiendo cómo montar un concierto...",
  ui_story_5037_50370701_45_dialog_content = "Fia, te perderás mi próximo anuncio si no te calmas.",
  ui_story_5037_50370701_46_dialog_content = "¿Qué?",
  ui_story_5037_50370701_47_dialog_content = "Fia y Vic lograron ganar muchos fanáticos durante este período de tiempo a través de sus esfuerzos y contribuyeron a muchas ventas de mercadería de Cloudrover Guild.",
  ui_story_5037_50370701_48_dialog_content = "A la luz de su excelente desempeño...",
  ui_story_5037_50370701_49_dialog_content = "¡También obtendrás un bono!",
  ui_story_5037_50370701_50_dialog_content = "Un bono...",
  ui_story_5037_50370701_51_dialog_content = "¡¿Dinero del premio?!",
  ui_story_5037_50370701_52_dialog_content = "Lo sabía. ¡El Maestro y yo no sufrimos por nada! ¡El trabajo duro realmente puede conducir a buenos resultados! *Sollozo*",
  ui_story_5037_50370701_53_dialog_content = "¡Ejem, hay más!",
  ui_story_5037_50370701_54_dialog_content = "El ganador de Hardest Working Idol en nuestro reality show es...",
  ui_story_5037_50370701_55_dialog_content = "Vic!",
  ui_story_5037_50370701_56_dialog_content = "¿Maestro? ¿El maestro ganó algo?",
  ui_story_5037_50370701_57_dialog_content = "¿Y el ídolo más trabajador de todas las cosas?",
  ui_story_5037_50370701_58_dialog_content = "¡Master venció a Goldie y recibió el apoyo de todos!",
  ui_story_5037_50370701_59_dialog_content = "¡Estoy tan orgullosa de mi maestro!",
  ui_story_5037_50370701_60_dialog_content = "¡Jeje, esto también es un guiño a Kyllo y mis esfuerzos!",
  ui_story_5037_50370701_61_dialog_content = "¡Lo!",
  ui_story_5037_50370701_62_dialog_content = "perdónanos, PlayerName, pero este es nuestro!",
  ui_story_5037_50370701_63_dialog_content = "Vic trabajó muy duro, de hecho, así que siento que se lo merece.",
  ui_story_5037_50370701_64_dialog_content = "A continuación, el Mejor Productor va para...",
  ui_story_5037_50370701_65_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_66_dialog_content = "¿Qué?",
  ui_story_5037_50370701_67_dialog_content = "¿Yo, mejor productor?",
  ui_story_5037_50370701_68_dialog_content = "¡...!",
  ui_story_5037_50370701_69_dialog_content = "Hmph, bien.",
  ui_story_5037_50370701_70_dialog_content = "Lo admito PlayerName Dominé las habilidades de un productor más rápido y mejor que yo.",
  ui_story_5037_50370701_71_dialog_content = "¡Pero también es mayor que yo!",
  ui_story_5037_50370701_72_dialog_content = "Espera a que tenga su edad. ¡Seguro que seré más genial!",
  ui_story_5037_50370701_73_dialog_content = "fia?",
  ui_story_5037_50370701_74_dialog_content = "Ella simplemente se fue así.",
  ui_story_5037_50370701_75_dialog_content = "Está bien, es probable que vuelva con su amo.",
  ui_story_5037_50370701_76_dialog_content = "Puede que tenga una lengua afilada, pero su corazón está en el lugar correcto.",
  ui_story_5037_50370701_77_dialog_content = "¿Cómo tienes esa percepción de Fia?",
  ui_story_5037_50370701_78_dialog_content = "Si bien no soy Caelestite y no tengo habilidades psíquicas...",
  ui_story_5037_50370701_79_dialog_content = "Soy más perceptivo con la gente que incluso tú.",
  ui_story_5037_50370701_80_dialog_content = "¿De qué otra forma crees que comencé desde cero y construí Cloudrover Guild hasta donde está ahora?",
  ui_story_5037_50370701_81_dialog_content = "...",
  ui_story_5037_50370701_82_dialog_content = "Lilica.",
  ui_story_5037_50370701_83_dialog_content = "¡Estoy aquí, Señora Sheol!",
  ui_story_5037_50370701_84_dialog_content = "Me encanta todo el metraje B-roll que tomaste para el programa.",
  ui_story_5037_50370701_85_dialog_content = "Con una edición adecuada, será un reality show de calidad.",
  ui_story_5037_50370701_86_dialog_content = "Para entonces, te estarán esperando muchas nuevas oportunidades de dirección.",
  ui_story_5037_50370701_87_dialog_content = "¡Me aseguraré de que edite el mejor programa de la historia!",
  ui_story_5037_50370701_88_dialog_content = "¡Y no dude en pedirme cualquier cosa en el futuro, Lady Sheol!",
  ui_story_5037_50370701_89_dialog_content = "Por supuesto. También espero que surjan historias interesantes después del concierto.",
  ui_story_5037_50370701_90_dialog_content = "Vigílalos para que no te pierdas nada.",
  ui_story_5037_50370701_91_dialog_content = "¡Está bien!",
  ui_story_5037_50370701_92_dialog_content = "¡Lo tengo!",
  ui_story_5037_50370701_93_dialog_content = "Eres bienvenido a quedarte y ser productor, PlayerName.",
  ui_story_5037_50370701_94_dialog_content = "Sólo recuerda enviar tu currículum a mi oficina.",
  ui_story_5037_50370701_95_dialog_content = "¡Está bien!",
  ui_story_5037_50370701_96_dialog_content = "Y estoy fuera de tiempo. Tengo que ir a ocuparme de asuntos de negocios ahora.",
  ui_story_5037_50370701_97_dialog_content = "¡Esperamos buenas noticias de todos ustedes!",
  ui_story_5037_50370701_98_dialog_content = "¡Adiós, Señora Sheol!",
  ui_story_5037_50370701_99_dialog_content = "Hmm, ¿es este el final de mi carrera como productor?",
  ui_story_5037_50370701_100_dialog_content = "...",
  ui_story_5037_50370701_101_dialog_content = "¿Qué... qué haces con esa cámara en mi cara, Lilica?",
  ui_story_5037_50370701_102_dialog_content = "El reality show aún no ha terminado.",
  ui_story_5037_50370701_103_dialog_content = "tengo que seguir trabajando",
  ui_story_5037_50370701_104_dialog_content = "Pero el concierto ha terminado, y no hay nada más que hacer...",
  ui_story_5037_50370701_105_dialog_content = "¿Qué más te queda por filmar?",
  ui_story_5037_50370701_106_dialog_content = "Tu, por supuesto.",
  ui_story_5037_50370701_107_dialog_content = "Mejor Productor!",
  ui_story_5037_50370701_108_dialog_content = "¿Hay algo que deba hacer?",
  ui_story_5037_50370701_109_dialog_content = "Pregúntese.",
  ui_story_5037_50370701_110_dialog_content = "¿Me pregunto a mi mismo?",
  ui_story_5037_50370701_111_dialog_content = "Sí, por ejemplo... ¿a quién tienes más ganas de ver en este momento?",
  ui_story_5037_50370701_112_dialog_content = "¿A quién quiero ver?",
  ui_story_5037_50370701_113_dialog_content = "Así es, ¡el día aún no ha terminado!",
  ui_story_5037_50370701_114_dialog_content = "me gustaria ir a ver...",
  ui_story_5037_50370701_115_option_content = "Goldie",
  ui_story_5037_50370701_116_dialog_content = "¡Tengo que ir a decirle que ganamos!",
  ui_story_5037_50370701_117_option_content = "vic y fia",
  ui_story_5037_50370701_118_dialog_content = "¡Tengo que ir a felicitar a Vic!",
  ui_story_5037_50370701_119_option_content = "vicio y carleen",
  ui_story_5037_50370701_120_dialog_content = "Quiero agradecerles a los dos...",
  ui_story_5037_50370701_121_dialog_content = "¡Quiero decirle a Goldie que ganamos lo antes posible!",
  ui_story_5037_50370701_122_dialog_content = "Entonces le diré lo que quería decirle...",
  ui_story_5037_50370701_123_dialog_content = "¡Espera!",
  ui_story_5037_50370701_124_dialog_content = "¡Pero ya dije esas cosas!",
  ui_story_5037_50370701_125_dialog_content = "Supongo que debería hablar sobre el dinero del premio.",
  ui_story_5037_50370701_126_dialog_content = "\"¡Goldie, con este dinero podrás comprar más vestidos!\"",
  ui_story_5037_50370701_127_dialog_content = "Eso suena incómodo...",
  ui_story_5037_50370701_128_dialog_content = "\"¡Ganamos el dinero gracias a ti, Goldie!\"",
  ui_story_5037_50370701_129_dialog_content = "No, eso me hace sonar como si la estuviera adulando.",
  ui_story_5037_50370701_130_dialog_content = "\"¡Buen trabajo, Goldie!\"",
  ui_story_5037_50370701_131_dialog_content = "Eso suena como demasiado de un eufemismo...",
  ui_story_5037_50370701_132_dialog_content = "Goldie! Goldie! Goldie!",
  ui_story_5037_50370701_133_dialog_content = "¡Gracias por todo tu apoyo!",
  ui_story_5037_50370701_134_dialog_content = "Por favor, formen una fila a la vez, ¡no se tropiecen!",
  ui_story_5037_50370701_135_dialog_content = "El concierto terminó hace mucho tiempo, ¡pero todavía tiene tantos fanáticos zumbando a su alrededor!",
  ui_story_5037_50370701_136_dialog_content = "Ella parece estar pasando un buen rato con ellos.",
  ui_story_5037_50370701_137_dialog_content = "No debería irrumpir.",
  ui_story_5037_50370701_138_dialog_content = "¡Puedo usar este tiempo para averiguar qué le voy a decir más tarde!",
  ui_story_5037_50370701_139_dialog_content = "<size=45>PlayerName!</size>",
  ui_story_5037_50370701_140_dialog_content = "¿Me estaba llamando Goldie?",
  ui_story_5037_50370701_141_dialog_content = "<size=50>PlayerName, ven aquí rápido!</size>",
  ui_story_5037_50370701_142_dialog_content = "¿Quiere que hable con los fans también?",
  ui_story_5037_50370701_143_dialog_content = "No creo que deba ir. Todos son sus fans y no estarían interesados en mí.",
  ui_story_5037_50370701_144_dialog_content = "¡Por favor dame un minuto, vuelvo enseguida!",
  ui_story_5037_50370701_145_dialog_content = "¡Dondequiera que va Goldie, los Ricitos de Oro la siguen!",
  ui_story_5037_50370701_146_dialog_content = "Espera...",
  ui_story_5037_50370701_147_dialog_content = "¿Por qué viene por aquí?",
  ui_story_5037_50370701_148_dialog_content = "¿Qué haces aquí parado, productor?",
  ui_story_5037_50370701_149_dialog_content = "Oh, solo vine a decirte...",
  ui_story_5037_50370701_150_dialog_content = "¡Ganamos!",
  ui_story_5037_50370701_151_dialog_content = "Ya era hora de que te enteraras, PlayerName.",
  ui_story_5037_50370701_152_dialog_content = "¿Ya lo sabías?",
  ui_story_5037_50370701_153_dialog_content = "Sí, justo después de terminar la última canción.",
  ui_story_5037_50370701_154_dialog_content = "Hicimos nuestro mejor esfuerzo en cada presentación y no dejamos ningún remordimiento en el escenario.",
  ui_story_5037_50370701_155_dialog_content = "Ya ganamos cuando nos conquistamos a nosotros mismos.",
  ui_story_5037_50370701_156_dialog_content = "Así es como ves esto.",
  ui_story_5037_50370701_157_dialog_content = "Muchos fanáticos elogiaron los diseños del escenario. ¿Por qué no te mezclas con ellos?",
  ui_story_5037_50370701_158_dialog_content = "Bueno, yo...",
  ui_story_5037_50370701_159_dialog_content = "¡No es de buena educación que los ídolos o los productores de ídolos hagan esperar a los fanáticos!",
  ui_story_5037_50370701_160_dialog_content = "¡Lamento haberte hecho esperar, mi querida Ricitos de Oro!",
  ui_story_5037_50370701_161_dialog_content = "Me gustaría presentarles a alguien para todos ustedes.",
  ui_story_5037_50370701_162_dialog_content = "¡Redoble de tambores por favor!",
  ui_story_5037_50370701_163_dialog_content = "H-Hola a todos!",
  ui_story_5037_50370701_164_dialog_content = "Así es, la persona tímida a mi lado es la legendaria Caelestite, PlayerName!",
  ui_story_5037_50370701_165_dialog_content = "También, PlayerName es el productor que me ha estado ayudando todo este tiempo!",
  ui_story_5037_50370701_166_dialog_content = "¡Los espectáculos fueron muy bien gracias a él!",
  ui_story_5037_50370701_167_dialog_content = "Me halaga. En realidad, soy muy nuevo en el papel.",
  ui_story_5037_50370701_168_dialog_content = "¿El productor de Goldie era un novato? no lo habría adivinado.",
  ui_story_5037_50370701_169_dialog_content = "Ya sabes lo que dicen, ¡nunca juzgues un libro por su portada!",
  ui_story_5037_50370701_170_dialog_content = "Me llamaría a mí mismo un intransigente Goldie fanático que ha estado allí desde el primer día.",
  ui_story_5037_50370701_171_dialog_content = "Goldie ya era sobresaliente en todos los aspectos, pero conseguir un productor...",
  ui_story_5037_50370701_172_dialog_content = "¡realmente la ayudó a mejorar mucho y la ayudó a encontrar su propio estilo!",
  ui_story_5037_50370701_173_dialog_content = "No entiendo toda esa jerga.",
  ui_story_5037_50370701_174_dialog_content = "¡Todo lo que sé es que nunca había estado en un espectáculo tan agradable y delicioso!",
  ui_story_5037_50370701_175_dialog_content = "Todo es gracias al productor. PlayerName!",
  ui_story_5037_50370701_176_dialog_content = "Productor PlayerName! Productor PlayerName! Productor PlayerName!",
  ui_story_5037_50370701_177_dialog_content = "...",
  ui_story_5037_50370701_178_dialog_content = "(Es un poco vergonzoso escuchar a tanta gente decir mi nombre...)",
  ui_story_5037_50370701_179_dialog_content = "(Todo lo que hice fue algunas cosas detrás del escenario. ¿Eso incluso justifica algún aplauso?)",
  ui_story_5037_50370701_180_dialog_content = "Productor PlayerName...",
  ui_story_5037_50370701_181_dialog_content = "Por supuesto que te mereces los aplausos.",
  ui_story_5037_50370701_182_dialog_content = "¡Has trabajado tan duro últimamente!",
  ui_story_5037_50370701_183_dialog_content = "(¿Cómo supo Goldie lo que estaba pensando?)",
  ui_story_5037_50370701_184_dialog_content = "(¡Y hasta me robó la línea!)",
  ui_story_5037_50370701_185_dialog_content = "Creo que todos quieren hablar contigo. PlayerName!",
  ui_story_5037_50370701_186_dialog_content = "¿Ah?",
  ui_story_5037_50370701_187_dialog_content = "¡Autógrafo, por favor, Productor!",
  ui_story_5037_50370701_188_dialog_content = "¡No soy un Lovegator, pero también quiero el autógrafo de PlayerName!",
  ui_story_5037_50370701_189_dialog_content = "¡Yo también!",
  ui_story_5037_50370701_190_dialog_content = "¡Y yo!",
  ui_story_5037_50370701_191_dialog_content = "Que esta pasando...?!",
  ui_story_5037_50370701_192_dialog_content = "Habría practicado mi firma si hubiera sabido que esto iba a pasar...",
  ui_story_5037_50370701_193_dialog_content = "¡Wow!",
  ui_story_5037_50370701_194_dialog_content = "¡Nunca antes había contado tantos Nightium!",
  ui_story_5037_50370701_195_dialog_content = "¿Así que esto es lo que se siente ser rico?",
  ui_story_5037_50370701_196_dialog_content = "¡Lady Sheol es demasiado generosa!",
  ui_story_5037_50370701_197_dialog_content = "¿Con quién hablas, Fia?",
  ui_story_5037_50370701_198_dialog_content = "No veo a nadie más alrededor.",
  ui_story_5037_50370701_199_dialog_content = "¿Con quién más podría estar hablando además de mi maestro?",
  ui_story_5037_50370701_200_dialog_content = "¿Tu maestro?",
  ui_story_5037_50370701_201_dialog_content = "Qué... Ni siquiera me habría dado cuenta si no lo hubieras mencionado...",
  ui_story_5037_50370701_202_dialog_content = "¡Ese amo holgazán mío se quedó dormido debajo de la mesa otra vez!",
  ui_story_5037_50370701_203_dialog_content = "¡Arrastra a Master ahora, Kyllo!",
  ui_story_5037_50370701_204_dialog_content = "¡Lo!",
  ui_story_5037_50370701_205_dialog_content = "¿Ah?",
  ui_story_5037_50370701_206_dialog_content = "De todos modos, ¿de dónde vienes? PlayerName?",
  ui_story_5037_50370701_207_dialog_content = "Bueno, la puerta estaba abierta, así que entré.",
  ui_story_5037_50370701_208_dialog_content = "¡¿Qué?! ¡¿Cómo pude haber olvidado cerrar la puerta antes de contar el dinero?!",
  ui_story_5037_50370701_209_dialog_content = "E-Está bien, Fia. Lo cierro por ti.",
  ui_story_5037_50370701_210_dialog_content = "¡¿Pero qué pasa si un ladrón se coló?!",
  ui_story_5037_50370701_211_dialog_content = "¡Uf, no, tengo que contar todo el Nightium otra vez!",
  ui_story_5037_50370701_212_dialog_content = "¡Lo-lo!",
  ui_story_5037_50370701_213_dialog_content = "Nnng... No más entrenamiento, por favor...",
  ui_story_5037_50370701_214_dialog_content = "Vic?",
  ui_story_5037_50370701_215_dialog_content = "¡Vamos a correr, Little Furball! Ruuuun!",
  ui_story_5037_50370701_216_dialog_content = "¿Está... hablando en sueños?",
  ui_story_5037_50370701_217_dialog_content = "Ochenta y tres, ochenta y cuatro, ochenta y cinco...",
  ui_story_5037_50370701_218_dialog_content = "Fia, no habrá más, no importa cuántas veces lo cuentes.",
  ui_story_5037_50370701_219_dialog_content = "Además, ¿no crees que deberías comprobar cómo está tu amo? Solo míralo.",
  ui_story_5037_50370701_220_dialog_content = "Kyllo lo sacó de debajo de la mesa, ¡pero todavía no se ha despertado!",
  ui_story_5037_50370701_221_dialog_content = "¡Sólo un segundo! Llegaré a ti una vez que cuente hasta cien...",
  ui_story_5037_50370701_222_dialog_content = "Noventa y ocho, noventa y nueve... ¡Cien!",
  ui_story_5037_50370701_223_dialog_content = "Muy bien, ahora, ¿qué estabas diciendo hace un momento?",
  ui_story_5037_50370701_224_dialog_content = "Uh, tal vez deberías ver cómo está tu maestro.",
  ui_story_5037_50370701_225_dialog_content = "Está completamente insensible.",
  ui_story_5037_50370701_226_dialog_content = "Oh, solo está tomando una de sus siestas, eso es todo.",
  ui_story_5037_50370701_227_dialog_content = "Los últimos días realmente han hecho un número en él...",
  ui_story_5037_50370701_228_dialog_content = "¡Aunque supongo que eso es bastante normal para alguien que nunca ha trabajado un día en su vida!",
  ui_story_5037_50370701_229_dialog_content = "Ruuuuuuuuuun!!!",
  ui_story_5037_50370701_230_dialog_content = "Oye Vic? ¿Estas despierto ahora?",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? ¡¿Qué estás haciendo aquí?!",
  ui_story_5037_50370701_232_dialog_content = "¡R-Corre! ¡Kyllo se ha vuelto loco! ¡Sigue obligándome a entrenar!",
  ui_story_5037_50370701_233_dialog_content = "¿Estás seguro de que no estabas soñando?",
  ui_story_5037_50370701_234_dialog_content = "¿eh? Uh, ¿Fia también está aquí...?",
  ui_story_5037_50370701_235_dialog_content = "Espera, ¡¿de dónde salió todo ese Nightium?!",
  ui_story_5037_50370701_236_dialog_content = "¡Definitivamente estoy soñando ahora!",
  ui_story_5037_50370701_237_dialog_content = "Aunque debo decir que este sueño se siente mucho mejor que el anterior.",
  ui_story_5037_50370701_238_dialog_content = "¿Fia? ¿Cómo convencemos a Vic de que no está soñando?",
  ui_story_5037_50370701_239_dialog_content = "Jejeje. ¡Parece que es hora de que Kyllo vuelva a brillar! ¡Cosiguele!",
  ui_story_5037_50370701_240_dialog_content = "!",
  ui_story_5037_50370701_241_dialog_content = "¡N-Ahora solo espera un segundo, Fia! ¡Tu amo está bien despierto ahora, lo juro!",
  ui_story_5037_50370701_242_dialog_content = "Pobre Vic. Imagina tener tanto miedo de Kyllo.",
  ui_story_5037_50370701_243_dialog_content = "Hmm, parece que este Nightium es el verdadero negocio.",
  ui_story_5037_50370701_244_dialog_content = "Lady Sheol realmente es una persona generosa, ¿eh?",
  ui_story_5037_50370701_245_dialog_content = "Todo lo que hicimos fue participar en su reality show durante unos días, y ella nos pagó esta cantidad de Nightium a cambio...",
  ui_story_5037_50370701_246_dialog_content = "Me pregunto cuánto gana un verdadero ídolo.",
  ui_story_5037_50370701_247_dialog_content = "¿Por qué te importa cuánto ganan los demás, Fia? Deberíamos estar satisfechos con lo que ya tenemos, ¿no crees?",
  ui_story_5037_50370701_248_dialog_content = "Suspiro... Supongo que tienes razón.",
  ui_story_5037_50370701_249_dialog_content = "Es raro que te escuche decir algo serio por una vez...",
  ui_story_5037_50370701_250_dialog_content = "¡Tonterías, siempre soy así! Ahora, si me disculpan, ¡hay una mesa en un nuevo buffet de Umbraton con mi nombre!",
  ui_story_5037_50370701_251_dialog_content = "... ¡En tus sueños!",
  ui_story_5037_50370701_252_dialog_content = "¿Qué? ¡¿Por que no?!",
  ui_story_5037_50370701_253_dialog_content = "¡Durante los últimos días, no he hecho nada más que escuchar sus ridículas demandas!",
  ui_story_5037_50370701_254_dialog_content = "Si no estoy entrenando, estoy cuidando mi peso. ¡Ni siquiera puedo recordar la última vez que tuve una comida decente!",
  ui_story_5037_50370701_255_dialog_content = "No entramos en este tipo de dinero todos los días, ¿sabes? ¡Deberíamos darnos un capricho cuando tengamos la oportunidad!",
  ui_story_5037_50370701_256_dialog_content = "Parece que aún no comprende muy bien nuestra situación, Maestro.",
  ui_story_5037_50370701_257_dialog_content = "Esto puede parecer mucho dinero a primera vista.",
  ui_story_5037_50370701_258_dialog_content = "Pero una vez que tomas en cuenta tus bocadillos de Drakolion, nuestros gastos habituales de comida, las reparaciones de la casa y mi salario de trabajo...",
  ui_story_5037_50370701_259_dialog_content = "¡Eso consume más de la mitad del dinero!",
  ui_story_5037_50370701_260_dialog_content = "Y cuando consideramos lo poco confiable que será como fuente de ingresos...",
  ui_story_5037_50370701_261_dialog_content = "¡No tengo idea de cuánto nos va a durar este dinero!",
  ui_story_5037_50370701_262_dialog_content = "Espera, ¿qué quieres decir con sus ingresos?",
  ui_story_5037_50370701_263_dialog_content = "Vic ¡Tiene tanto potencial como ídolo! ¿Por qué no seguiría haciéndolo?",
  ui_story_5037_50370701_264_dialog_content = "Ahorrarme, PlayerName.",
  ui_story_5037_50370701_265_dialog_content = "Para mí haber durado tantos días fue nada menos que un milagro, ¿y quieres que lo haga por el resto de mi vida?",
  ui_story_5037_50370701_266_dialog_content = "Solo de pensarlo me da pesadillas.",
  ui_story_5037_50370701_267_dialog_content = "PlayerName ¡Tiene toda la razón, Maestro!",
  ui_story_5037_50370701_268_dialog_content = "Pasas todo tu tiempo en casa en lugar de buscar trabajo, y ni siquiera cuidas bien a las maravillosas bestias...",
  ui_story_5037_50370701_269_dialog_content = "También podrías usarte a ti mismo como un ídolo.",
  ui_story_5037_50370701_270_dialog_content = "¿Y quien sabe? Una vez que se transmita el programa de telerrealidad, es posible que tenga incluso más fanáticos que antes, ¡Maestro!",
  ui_story_5037_50370701_271_dialog_content = "Oh, querida, pequeña Fia...",
  ui_story_5037_50370701_272_dialog_content = "Dale un poco de holgura a tu amo, ¿quieres?",
  ui_story_5037_50370701_273_dialog_content = "¡No! ¡Vas a ser un ídolo grande y exitoso, y te va a gustar!",
  ui_story_5037_50370701_274_dialog_content = "¡¿Qué-?!",
  ui_story_5037_50370701_275_dialog_content = "¡Oh, mira, todavía tenemos tiempo suficiente para incluir más entrenamiento! ¡Vamos, Maestro!",
  ui_story_5037_50370701_276_dialog_content = "P-Pero no quiero seguir entrenando... Estoy totalmente agotado...",
  ui_story_5037_50370701_277_dialog_content = "¿Kyllo? Creo que nuestro amo necesita un poco de motivación.",
  ui_story_5037_50370701_278_dialog_content = "¡Nooo—!",
  ui_story_5037_50370701_279_dialog_content = "Suspiro... Nunca había visto al Maestro correr tan rápido en mi vida.",
  ui_story_5037_50370701_280_dialog_content = "Tanto por estar \"totalmente exhausto\", ¿eh? ¡Oye! Si tienes suficiente energía para huir, ¡todavía tienes suficiente energía para entrenar!",
  ui_story_5037_50370701_281_dialog_content = "Víc...",
  ui_story_5037_50370701_282_dialog_content = "¡Cuelga ahí!",
  ui_story_5037_50370701_283_dialog_content = "\"Mejor Productor\", ¿eh...?",
  ui_story_5037_50370701_284_dialog_content = "Jejeje... Sé que no debería dejar que el premio de Lady Sheol se me suba a la cabeza.",
  ui_story_5037_50370701_285_dialog_content = "Pensando en el día que llegué por primera vez a la Agencia Starlit, realmente no tenía idea de lo que estaba haciendo. Me preocupaba hacerle la vida a Goldie más difícil de lo que ya era.",
  ui_story_5037_50370701_286_dialog_content = "¡Pero logré ayudar a Goldie con sus tres conciertos e incluso logré que Lady Sheol me reconociera!",
  ui_story_5037_50370701_287_dialog_content = "Hombre, no puedo esperar para sorprender a Vice y Carleen con esto.",
  ui_story_5037_50370701_288_dialog_content = "Deberían estar en algún lugar cercano, ¿verdad?",
  ui_story_5037_50370701_289_dialog_content = "Me pregunto si están en esta habitación.",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>¡TOC Toc!</color>",
  ui_story_5037_50370701_291_dialog_content = "¡Perdón por la intrusión!",
  ui_story_5037_50370701_292_dialog_content = "Qué gracioso... Las luces de esta habitación suelen estar encendidas. ¿Por qué está tan oscuro aquí hoy?",
  ui_story_5037_50370701_293_dialog_content = "¿Vicio? ¿Carleen? Huh, supongo que no están aquí después de todo.",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5037_50370701_295_dialog_content = "¡¿Eh?!",
  ui_story_5037_50370701_296_dialog_content = "¡¡¡Sorpresa!!!",
  ui_story_5037_50370701_297_dialog_content = "¡Felicitaciones por organizar un concierto de graduación perfecto!",
  ui_story_5037_50370701_298_dialog_content = "Y felicidades por completar sus misiones, PlayerName.",
  ui_story_5037_50370701_299_dialog_content = "¿Q-Qué es todo esto...?",
  ui_story_5037_50370701_300_dialog_content = "Una selección de los mejores alimentos y bebidas de un nuevo buffet de alta gama recientemente inaugurado en Umbraton.",
  ui_story_5037_50370701_301_dialog_content = "Y también, ¡este enorme pastel! Se ve sabroso, ¿eh?",
  ui_story_5037_50370701_302_dialog_content = "Desde que empezaste a entrenar para ser productor, no has estado comiendo bien.",
  ui_story_5037_50370701_303_dialog_content = "Así que... Decidimos armar una pequeña fiesta de celebración solo para ti, PlayerName! ¿Ver? ¡Tiene todos tus favoritos!",
  ui_story_5037_50370701_304_dialog_content = "Vicio, Carleen...",
  ui_story_5037_50370701_305_dialog_content = "¿Cuánto tiempo han estado planeando esto?",
  ui_story_5037_50370701_306_dialog_content = "¡No tenía ni idea!",
  ui_story_5037_50370701_307_dialog_content = "¡Jejeje! Se nos ocurrió la idea hace un tiempo, en realidad.",
  ui_story_5037_50370701_308_dialog_content = "Y con lo ocupado que ha estado hoy, tuvimos mucho tiempo para prepararnos.",
  ui_story_5037_50370701_309_dialog_content = "¿Eso significa que ustedes dos saben los resultados del concierto de hoy?",
  ui_story_5037_50370701_310_dialog_content = "¡No! Esperábamos que nos lo dijeras.",
  ui_story_5037_50370701_311_dialog_content = "Er... ¿Qué harías si perdiéramos? ¿Todavía tendríamos una razón para celebrar?",
  ui_story_5037_50370701_312_dialog_content = "Vice y ya estuve de acuerdo en que sin importar los resultados de hoy,",
  ui_story_5037_50370701_313_dialog_content = "todo su arduo trabajo es razón suficiente para celebrar.",
  ui_story_5037_50370701_314_dialog_content = "No solo estudiaste tu corazón, PlayerName. ¡Te quedaste con eso hasta el final! Eso es un gran logro en mis ojos!",
  ui_story_5037_50370701_315_dialog_content = "¡Por eso vamos a festejar pase lo que pase!",
  ui_story_5037_50370701_316_dialog_content = "U-ustedes... Arrrgh, ¡¿por qué tienen que ser tan amables?!",
  ui_story_5037_50370701_317_dialog_content = "¿Ver? ¡Ahora tengo algo en el ojo, gracias a ti!",
  ui_story_5037_50370701_318_dialog_content = "Así que de todos modos, ¿quién ganó hoy?",
  ui_story_5037_50370701_319_dialog_content = "¡Pensé que habías dicho que no importaba!",
  ui_story_5037_50370701_320_dialog_content = "¡Jajaja! Eso es porque confiamos en ti, PlayerName!",
  ui_story_5037_50370701_321_dialog_content = "Además, estabas murmurando algo sobre algo que querías decirnos cuando estabas afuera. ¿Así que qué es lo?",
  ui_story_5037_50370701_322_dialog_content = "Jejeje. ¿Adivina qué? Goldie ¡y gané hoy!",
  ui_story_5037_50370701_323_dialog_content = "Y no solo eso, ¡Lady Sheol me dio el premio a Mejor Productor!",
  ui_story_5037_50370701_324_dialog_content = "¡Guau! ¡No tenía idea de que incluso tenían un premio por eso!",
  ui_story_5037_50370701_325_dialog_content = "Parece que Lady Sheol tiene un ojo bastante perspicaz. No creo que tu increíble progreso se haya perdido para ella en absoluto, PlayerName.",
  ui_story_5037_50370701_326_dialog_content = "Entonces, ¿el premio vino con algún premio en efectivo? ¿Eh? ¡¿Eh?!",
  ui_story_5037_50370701_327_dialog_content = "Yo, eh... No lo creo.",
  ui_story_5037_50370701_328_dialog_content = "Jejeje, eso tiene sentido. Después de todo, ninguna cantidad de dinero podría compararse con el honor de recibir ese premio, ¿verdad?",
  ui_story_5037_50370701_329_dialog_content = "Acordado. Debería ser mucho más fácil encontrar trabajo en el futuro con él.",
  ui_story_5037_50370701_330_dialog_content = "¡Así es! ¡Estás básicamente al mismo nivel que cualquier otro productor profesional ahora!",
  ui_story_5037_50370701_331_dialog_content = "Pero si no fuera por ustedes, muchachos, ayudándome todo el tiempo, nunca hubiera tenido la confianza para llegar tan lejos.",
  ui_story_5037_50370701_332_dialog_content = "Carleen, Vice, gracias a los dos por estar siempre a mi lado y enseñarme tanto estos últimos días.",
  ui_story_5037_50370701_333_dialog_content = "¡No lo menciones! Sin embargo, solo hay un pequeño error en tu declaración.",
  ui_story_5037_50370701_334_dialog_content = "¿Ah?",
  ui_story_5037_50370701_335_dialog_content = "No solo te hemos estado ayudando durante los últimos días, ¿verdad?",
  ui_story_5037_50370701_336_dialog_content = "Ella está en lo correcto. Hemos estado juntos todo este tiempo, ¿no?",
  ui_story_5037_50370701_337_dialog_content = "Si, tienes razón.",
  ui_story_5037_50370701_338_dialog_content = "¡Déjame intentar de nuevo!",
  ui_story_5037_50370701_339_dialog_content = "Oh, solo relájate, ¿quieres? Todos somos amigos aquí, ¡así que no hay necesidad de ser tan formal!",
  ui_story_5037_50370701_340_dialog_content = "De todos modos, ¿adivinen qué?",
  ui_story_5037_50370701_341_dialog_content = "¡En mi último viaje de regreso a Illumina, noté que toda la región se había metido en ídolos!",
  ui_story_5037_50370701_342_dialog_content = "¡Creo que la oficial Vivian incluso está planeando algún tipo de gran evento para elegir un grupo de ídolos para representar a toda la Federación Illumina!",
  ui_story_5037_50370701_343_dialog_content = "¿Qué? Ídolos de Illumina?!",
  ui_story_5037_50370701_344_dialog_content = "¡Vamos a rugir y animar el espectáculo!",
  ui_story_5037_50370701_345_dialog_content = "¿Mmm? ¿Qué pasa con la multitud terriblemente silenciosa?",
  ui_story_5037_50370701_346_dialog_content = "¿Estaban todos tan estupefactos por mi espectacular actuación que se olvidaron de aplaudir?",
  ui_story_5037_50370701_347_dialog_content = "Jajajajajajajaja!",
  ui_story_5037_50370701_348_dialog_content = "*Inhalar*",
  ui_story_5037_50370701_349_dialog_content = "¿Mmm? Hay algo mal, PlayerName? Te ves un poco pálido.",
  ui_story_5037_50370701_350_dialog_content = "¡N-No es nada!",
  ui_story_5037_50370701_351_dialog_content = "¡Estoy seguro de que la búsqueda del máximo ídolo de Illumina será una experiencia inolvidable!",
  ui_story_5037_50370701_352_dialog_content = "Estos concursos de ídolos son de hecho dignos de una seria consideración. ¿Quizás debería sugerirle a mi padre un evento similar para Lumopolis?",
  ui_story_5037_50370701_353_dialog_content = "Er, ¿crees que los nobles de Lumopolis estarían de acuerdo con este tipo de cosas?",
  ui_story_5037_50370701_354_dialog_content = "Sospecho que no será fácil.",
  ui_story_5037_50370701_355_dialog_content = "Pero no se puede negar la riqueza de conocimientos que obtuve de esta experiencia.",
  ui_story_5037_50370701_356_dialog_content = "De hecho, creo que finalmente veo el verdadero valor de mostrar el encanto de uno para que el mundo lo vea.",
  ui_story_5037_50370701_357_dialog_content = "Por extraño que parezca, siento como si de repente me hubieran quitado un peso de los hombros.",
  ui_story_5037_50370701_358_dialog_content = "¡Sí, entiendo!",
  ui_story_5037_50370701_359_dialog_content = "¡Creo que te has acercado un paso más en tu viaje para suceder a tu padre, Carleen!",
  ui_story_5037_50370701_360_dialog_content = "¿De verdad crees que esto tiene algo que ver con eso?",
  ui_story_5037_50370701_361_dialog_content = "Lo hace si realmente lo piensas.",
  ui_story_5037_50370701_362_dialog_content = "¿Cómo es eso?",
  ui_story_5037_50370701_363_dialog_content = "¡La comida está empezando a enfriarse! ¡Vamos a profundizar en!",
  ui_story_5037_50370701_364_dialog_content = "Tienes razón. Celebremos nuestra victoria mientras la comida aún está caliente.",
  ui_story_5037_50370701_365_dialog_content = "A PlayerName, el Mejor Productor!",
  ui_story_5037_50370701_366_dialog_content = "¡Salud!",
  ui_story_5037_50370701_367_option_content = "¡Salud!",
  ui_story_5037_50370801_1_dialog_content = "Entrenamiento de coreografía, ejercicios vocales, una sesión de preguntas y respuestas, contacto con el propietario del lugar para la reunión de fans...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "Debería comunicarme con el dueño en algún momento entre el almuerzo y la cena, pero el reportero estará aquí esta tarde...",
  ui_story_5037_50370801_4_dialog_content = "...",
  ui_story_5037_50370801_5_dialog_content = "También necesito reservar suficiente tiempo para que Goldie descanse, así como para cambiarse y maquillarse. Con todo esto sucediendo en un día...",
  ui_story_5037_50370801_6_dialog_content = "¿...?",
  ui_story_5037_50370801_7_dialog_content = "¡Tendré que pasar todo el día trabajando de nuevo!",
  ui_story_5037_50370801_8_dialog_content = "¿PlayerName?",
  ui_story_5037_50370801_9_dialog_content = "¡¡¡Bwaaaa!!!",
  ui_story_5037_50370801_10_dialog_content = "Oh, solo eres tú, Goldie. Mi corazón casi saltó fuera de mi pecho en este momento.",
  ui_story_5037_50370801_11_dialog_content = "¿Puedo preguntar qué estás murmurando aquí?",
  ui_story_5037_50370801_12_dialog_content = "En realidad, parece que estás bastante bajo de energía. ¿Quieres ir a practicar algunos pasos de baile conmigo para levantarte el ánimo?",
  ui_story_5037_50370801_13_dialog_content = "¡Un poco de ejercicio puede ayudar mucho cuando se trata de mantenerse saludable!",
  ui_story_5037_50370801_14_dialog_content = "¡Después de todo, un productor saludable es esencial para el éxito de un ídolo! ¿De qué otra manera te mantendrás al día con todos mis conciertos y eventos?",
  ui_story_5037_50370801_15_dialog_content = "Sí, pero todavía estoy planeando el horario...",
  ui_story_5037_50370801_16_dialog_content = "Hay tantas cosas que hacer todos los días que tan pronto como termino con una, ya llego tarde a la siguiente...",
  ui_story_5037_50370801_17_dialog_content = "¡Incluso tratar de encajar unos minutos de descanso es casi imposible ahora!",
  ui_story_5037_50370801_18_dialog_content = "Supongo que no soy tan buen productor, después de todo...",
  ui_story_5037_50370801_19_dialog_content = "¡De ninguna manera! ¡Eres un productor fantástico!",
  ui_story_5037_50370801_20_dialog_content = "¡Solo ha sido uno durante unos días, pero está completamente familiarizado con los requisitos diarios del trabajo! Eso no es algo que cualquiera pueda hacer, ¿sabes?",
  ui_story_5037_50370801_21_dialog_content = "Así que no seas demasiado duro contigo mismo, ¿de acuerdo? Toma, ¿quieres acariciar a Marshmallow?",
  ui_story_5037_50370801_22_dialog_content = "¡Siempre me siento mejor después de acariciar su pelaje suave y esponjoso!",
  ui_story_5037_50370801_23_dialog_content = "¡Wau!",
  ui_story_5037_50370801_24_dialog_content = "Seguro Por qué no-",
  ui_story_5037_50370801_25_dialog_content = "¡Espera!",
  ui_story_5037_50370801_26_dialog_content = "¿Qué ocurre?",
  ui_story_5037_50370801_27_dialog_content = "¡Olvidé llamar al periódico por la entrevista de mañana! Todavía no he fijado un tiempo para ello!",
  ui_story_5037_50370801_28_dialog_content = "Lo siento, Goldie! ¡Tengo que irme!",
  ui_story_5037_50370801_29_dialog_content = "...",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>Un momento después</color>",
  ui_story_5037_50370801_31_dialog_content = "Uf... Gracias a Dios que lo hice a tiempo.",
  ui_story_5037_50370801_32_dialog_content = "Son uno de los periódicos más importantes que existen. Si los hubiera dejado colgados, habría dañado la reputación de Goldie.",
  ui_story_5037_50370801_33_dialog_content = "Bienvenido de nuevo, PlayerName!",
  ui_story_5037_50370801_34_dialog_content = "Oh hola, Goldie! Lo siento, tenía tanta prisa que olvidé despedirme...",
  ui_story_5037_50370801_35_dialog_content = "Esta bien. Sé que es porque has estado muy ocupado con el trabajo últimamente.",
  ui_story_5037_50370801_36_dialog_content = "Ser productor puede ser bastante difícil. Aunque me he ido adaptando lentamente al trabajo en los últimos días,",
  ui_story_5037_50370801_37_dialog_content = "el trabajo sigue siendo muy exigente!",
  ui_story_5037_50370801_38_dialog_content = "Si todo lo que tuviera que hacer fuera planificar los horarios, no sería nada difícil.",
  ui_story_5037_50370801_39_dialog_content = "Pero además de toda la planificación, tengo que luchar contra los paparazzi en todo momento y pensar en las cosas correctas para decir cada vez...",
  ui_story_5037_50370801_40_dialog_content = "Es agotador...",
  ui_story_5037_50370801_41_dialog_content = "Sé que es un trabajo duro.",
  ui_story_5037_50370801_42_dialog_content = "Pero no importa lo cansado que estés, siempre encuentras la manera de hacer el trabajo. PlayerName!",
  ui_story_5037_50370801_43_dialog_content = "¡Eso es lo que me parece tan increíble de ti!",
  ui_story_5037_50370801_44_dialog_content = "¡Gracias, Goldie! ¡Solo escucharte decir eso me hace sentir mucho menos agotado!",
  ui_story_5037_50370801_45_dialog_content = "¿Ver? Todos necesitan aliento de vez en cuando, ¡no importa quiénes sean!",
  ui_story_5037_50370801_46_dialog_content = "Ahora que lo mencionas... ¿Te encargaste de todo esto tú sola antes, Goldie?",
  ui_story_5037_50370801_47_dialog_content = "No solo ser un ídolo, sino también ser tu propio productor...",
  ui_story_5037_50370801_48_dialog_content = "Entrenando, planificando, esquivando a los paparazzi...",
  ui_story_5037_50370801_49_option_content = "¡Debes ser bastante increíble para haber hecho todo eso por tu cuenta!",
  ui_story_5037_50370801_50_dialog_content = "Jaja... No fue nada, de verdad.",
  ui_story_5037_50370801_51_option_content = "Manejar todo por tu cuenta debe haber sido difícil...",
  ui_story_5037_50370801_52_dialog_content = "Lo fue, pero lo logré al final.",
  ui_story_5037_50370801_53_dialog_content = "Incluso para alguien como yo, manejar dos trabajos completamente diferentes no fue fácil.",
  ui_story_5037_50370801_54_dialog_content = "Me encontré con todo tipo de obstáculos en el pasado. Incluso hubo momentos en los que quise rendirme y renunciar.",
  ui_story_5037_50370801_55_dialog_content = "¿De verdad tenías ganas de dejarlo antes? Ni siquiera puedo imaginar eso.",
  ui_story_5037_50370801_56_dialog_content = "Es uno de mis mayores secretos, ¡así que no se lo digas a otras personas!",
  ui_story_5037_50370801_57_dialog_content = "¡No lo soñaría! Como su productor, ¡nunca diría ni haría nada que pudiera lastimarlo a usted o a su reputación!",
  ui_story_5037_50370801_58_dialog_content = "¡Jejeje! ¡Alegra oírlo!",
  ui_story_5037_50370801_59_dialog_content = "Pero para responder a tu pregunta... Sí, tuve que manejar todo el trabajo por mi cuenta cuando me convertí en un ídolo.",
  ui_story_5037_50370801_60_dialog_content = "Entrenando, planificando y evitando a los paparazzi... todo.",
  ui_story_5037_50370801_61_dialog_content = "En ese entonces, ¡solo dormía una o dos horas todos los días!",
  ui_story_5037_50370801_62_dialog_content = "Tenía que levantarme temprano todas las mañanas para compensar cualquier entrenamiento que me perdí el día anterior.",
  ui_story_5037_50370801_63_dialog_content = "¡Eso es una locura!",
  ui_story_5037_50370801_64_dialog_content = "Estoy acostumbrado a quedarme despierto hasta tarde, pero ¿solo duermo una o dos horas? Ni siquiera podría levantarme de la cama al día siguiente, y mucho menos hacerlo todos los días...",
  ui_story_5037_50370801_65_dialog_content = "Eso era básicamente yo.",
  ui_story_5037_50370801_66_dialog_content = "Uno o dos días es manejable para la mayoría de las personas, pero ¿durante varios años? ¿Para siempre?",
  ui_story_5037_50370801_67_dialog_content = "Cada vez que terminaba mi entrenamiento, me acostaba en mi cama y mi mente exhausta pensaba en un futuro sin fin de ese tipo de estilo de vida.",
  ui_story_5037_50370801_68_dialog_content = "¡Pero al final, pudiste luchar en los momentos difíciles y convertirte en el famoso ídolo que eres hoy!",
  ui_story_5037_50370801_69_dialog_content = "¡Así es!",
  ui_story_5037_50370801_70_dialog_content = "Cada vez que tengo ganas de rendirme, lanzo mi bala de la suerte al aire. Si aterriza apuntando hacia abajo, ¡significa que algo bueno va a suceder!",
  ui_story_5037_50370801_71_dialog_content = "En aquel entonces, mi bala de la suerte siempre apuntaba hacia abajo, así que sabía que si seguía adelante... ¡me convertiría en el ídolo que siempre soñé ser!",
  ui_story_5037_50370801_72_dialog_content = "Realmente tienes un espíritu indomable...",
  ui_story_5037_50370801_73_dialog_content = "¡Jejeje!",
  ui_story_5037_50370801_74_dialog_content = "Pero las cosas son un poco diferentes ahora, ¿sabes?",
  ui_story_5037_50370801_75_dialog_content = "te tengo conmigo ¡El mejor productor que podría pedir!",
  ui_story_5037_50370801_76_dialog_content = "¡Gracias a ti, puedo concentrarme en mi entrenamiento sin preocuparme por otras cosas!",
  ui_story_5037_50370801_77_dialog_content = "¡Mi progreso nunca ha sido más rápido!",
  ui_story_5037_50370801_78_dialog_content = "¿H-he... sido realmente tan útil?",
  ui_story_5037_50370801_79_dialog_content = "¡Absolutamente!",
  ui_story_5037_50370801_80_dialog_content = "¡Me alegra oír eso!",
  ui_story_5037_50370801_81_dialog_content = "Me sentía tan inútil antes... Como si solo te estuviera creando más problemas.",
  ui_story_5037_50370801_82_dialog_content = "Pero oírte decir eso me hace sentir mucho más confiado.",
  ui_story_5037_50370801_83_dialog_content = "¡Como tu productor, seguiré haciendo lo mejor que pueda por ti, Goldie! ¡Sólo déjamelo a mi!",
  ui_story_5037_50370801_84_dialog_content = "¡Te sostendré!",
  ui_story_5037_50370901_1_dialog_content = "<color=#828282>Después del entrenamiento de la mañana</color>",
  ui_story_5037_50370901_2_dialog_content = "De nuevo, gracias por tu ayuda, PlayerName!",
  ui_story_5037_50370901_3_dialog_content = "Terminé con mi entrenamiento matutino, así que ahora tengo tiempo para descansar un poco.",
  ui_story_5037_50370901_4_dialog_content = "No lo menciones, Goldie. ¡Disfruta de tu descanso!",
  ui_story_5037_50370901_5_dialog_content = "<color=#828282>¡Toc, toc!</color>",
  ui_story_5037_50370901_6_dialog_content = "¡Adelante!",
  ui_story_5037_50370901_7_dialog_content = "PlayerName! ¡Ah, y Goldie también!",
  ui_story_5037_50370901_8_dialog_content = "¡Hola, Gronru!",
  ui_story_5037_50370901_9_dialog_content = "¿Gronru? ¿Qué estás haciendo aquí?",
  ui_story_5037_50370901_10_dialog_content = "Oh, solo comprando algunos materiales, eso es todo. Escuché que ahora eres un productor importante en Umbraton, ¡así que pensé en pasarme y ver cómo funciona!",
  ui_story_5037_50370901_11_dialog_content = "¡También traje el último juego que diseñé! ¿Qué dices? ¿Quieres jugar algunas rondas?",
  ui_story_5037_50370901_12_dialog_content = "Por supuesto yo-",
  ui_story_5037_50370901_13_dialog_content = "Er, quiero decir... No ahora mismo, lo siento.",
  ui_story_5037_50370901_14_dialog_content = "¿Eh? ¿No quieres desafiarme hoy? Debo decir que eso no es propio de ti en absoluto...",
  ui_story_5037_50370901_15_dialog_content = "Porque todavía tengo mucho trabajo que hacer esta tarde. Es fácil para mí perder la noción del tiempo cuando juego videojuegos...",
  ui_story_5037_50370901_16_dialog_content = "Tienes razón, sí... Oh, bueno, ¡quizás la próxima vez! No los molestaré más, muchachos.",
  ui_story_5037_50370901_17_dialog_content = "Sigan con el buen trabajo, PlayerName! ¡Tú también, Goldie!",
  ui_story_5037_50370901_18_dialog_content = "¡Espero con ansias tu concierto!",
  ui_story_5037_50370901_19_dialog_content = "¡Gracias! ¡Espero verte allí también!",
  ui_story_5037_50370901_20_dialog_content = "¡Adiós!",
  ui_story_5037_50370901_21_dialog_content = "¡Nos vemos!",
  ui_story_5037_50370901_22_dialog_content = "Muy bien, es hora de prepararse para las tareas de esta tarde...",
  ui_story_5037_50370901_23_dialog_content = "Espera, ahora es el momento del descanso, ¿no? Es mejor descansar, para tener la energía para hacer el resto del trabajo del día.",
  ui_story_5037_50370901_24_dialog_content = "Lo sé, lo sé... Pero el concierto está a la vuelta de la esquina.",
  ui_story_5037_50370901_25_dialog_content = "Nos estamos quedando sin tiempo, pero el trabajo sigue acumulándose. A veces, no queda más remedio que ceder un poco de nuestro tiempo libre...",
  ui_story_5037_50370901_26_dialog_content = "... ¿Habéis aprovechado vuestros descansos para trabajar en el concierto estos últimos días?",
  ui_story_5037_50370901_27_dialog_content = "Uh... ¿E-Algo así como...?",
  ui_story_5037_50370901_28_dialog_content = "¡Eso no funcionará!",
  ui_story_5037_50370901_29_dialog_content = "¡Sin un descanso adecuado, la calidad de su trabajo solo se verá afectada! ¡No podrás hacer nada a este ritmo!",
  ui_story_5037_50370901_30_dialog_content = "Para compensar todos los descansos que pasaste trabajando, ¡vas a tomarte toda la tarde libre!",
  ui_story_5037_50370901_31_dialog_content = "¡Ve a dar un paseo, toma un poco de aire fresco y no vuelvas hasta que estés bien y descansado!",
  ui_story_5037_50370901_32_dialog_content = "E-Eso no es realmente necesario...",
  ui_story_5037_50370901_33_dialog_content = "¡No aceptaré un no por respuesta! Esto afecta tanto a su salud como a su eficiencia en el trabajo.",
  ui_story_5037_50370901_34_dialog_content = "P-Pero si soy tu productor, ¿qué harás si no estoy?",
  ui_story_5037_50370901_35_dialog_content = "No tienes que preocuparte por eso. Te lo dije, fui mi propio productor durante mucho tiempo. Esto no es gran cosa.",
  ui_story_5037_50370901_36_dialog_content = "¡Ahora descansa un poco y no regreses a la oficina hasta mañana por la mañana!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5037_50370901_38_dialog_content = "(Me acaba de empujar por la puerta...)",
  ui_story_5037_50370901_39_dialog_content = "(Hmm... Supongo que iré a dar un paseo entonces.)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>Unos minutos más tarde en un café.</color>",
  ui_story_5037_50370901_41_dialog_content = "¿Qué puedo conseguirte?",
  ui_story_5037_50370901_42_dialog_content = "Déjame echar un vistazo al menú...",
  ui_story_5037_50370901_43_dialog_content = "¿\"Pastel Tricolor\"?",
  ui_story_5037_50370901_44_dialog_content = "Nuestra misión es realizar tres conciertos dentro de un período de tiempo determinado.",
  ui_story_5037_50370901_45_dialog_content = "Todavía nos quedan dos conciertos más...",
  ui_story_5037_50370901_46_dialog_content = "¡¿Por qué de repente estoy pensando en eso?! ¡Vuelve al menú!",
  ui_story_5037_50370901_47_dialog_content = "A ver... ¿Tortas gemelas?",
  ui_story_5037_50370901_48_dialog_content = "Una vez que comienzan los espectáculos, el público puede seguir sus preferencias y moverse libremente entre los escenarios.",
  ui_story_5037_50370901_49_dialog_content = "Al final, la etapa que logre ganar una multitud más grande será declarada ganadora.",
  ui_story_5037_50370901_50_dialog_content = "Suspiro... Me pregunto qué podemos hacer para mantener la atención de la gente.",
  ui_story_5037_50370901_51_dialog_content = "¿Kyllo es realmente un motivador tan potente?",
  ui_story_5037_50370901_52_dialog_content = "¿Debería encontrar mi propio Kyllo para morderme el tobillo?",
  ui_story_5037_50370901_53_dialog_content = "¡¿Por qué no puedo dejar de preocuparme?!",
  ui_story_5037_50370901_54_dialog_content = "Lo siento, creo que todavía necesito más tiempo para mirar el menú.",
  ui_story_5037_50370901_55_dialog_content = "No es un problema. Solo llámame cuando estés listo.",
  ui_story_5037_50370901_56_dialog_content = "Aunque no estoy en el trabajo, no puedo dejar de pensar en el concierto de evaluación. Faltan solo unos días...",
  ui_story_5037_50370901_57_dialog_content = "Tampoco he planeado el horario de Goldie para mañana. No puedo evitar sentirme incómodo cada vez que pienso en ello...",
  ui_story_5037_50370901_58_dialog_content = "Suspiro... El café y el pastel no saben tan bien cuando estoy tan estresado.",
  ui_story_5037_50370901_59_dialog_content = "Me pregunto cómo va el entrenamiento de Goldie...",
  ui_story_5037_50370901_60_dialog_content = "Está bien si echo un vistazo para asegurarme de que está bien. ¿Derecha?",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>Fuera de la agencia</color>",
  ui_story_5037_50370901_62_dialog_content = "Esta debería ser la sala de ensayo. Debería poder mirar dentro a través de la ventana.",
  ui_story_5037_50370901_63_dialog_content = "Puedo ver Goldie... Pero esa persona a su lado...",
  ui_story_5037_50370901_64_dialog_content = "¿Hola, Goldie? ¡Soy del Daily Babel, la fuente de los cotilleos más candentes de todo Umbraton!",
  ui_story_5037_50370901_65_dialog_content = "Me di cuenta de que le azotaste la puerta a tu productor hoy.",
  ui_story_5037_50370901_66_dialog_content = "¡Se dice en la calle que nunca te llevaste bien con él y que lo despediste en el acto! ¿Es eso cierto?",
  ui_story_5037_50370901_67_dialog_content = "PlayerName y yo estamos en los mejores términos, muchas gracias. Siempre hemos sido muy buenos amigos.",
  ui_story_5037_50370901_68_dialog_content = "Entonces, ¿cómo explicas la escena de antes?",
  ui_story_5037_50370901_69_dialog_content = "Echar a tu productor y dejarlo tirado en la calle... ¡Nunca había visto un espectáculo tan lamentable!",
  ui_story_5037_50370901_70_dialog_content = "Eso fue porque—",
  ui_story_5037_50370901_71_dialog_content = "Mierda... ¡Es ese odioso paparazzi de antes!",
  ui_story_5037_50370901_72_dialog_content = "Goldie nunca lo conoció ni trató con él antes... ¡Si no lo detiene, volverá a inventar cosas!",
  ui_story_5037_50370901_73_dialog_content = "¡Tengo que ayudarla!",
  ui_story_5037_50370901_74_dialog_content = "Qué pequeño y triste productor... Arrojado al mundo frío como un perro no deseado, sin ni siquiera un...",
  ui_story_5037_50370901_75_dialog_content = "¡Ey! ¿Que está pasando aqui?",
  ui_story_5037_50370901_76_dialog_content = "¡¿PlayerName?!",
  ui_story_5037_50370901_77_dialog_content = "¡E-Eres tú!",
  ui_story_5037_50370901_78_dialog_content = "¿Te escuché decir algo sobre Goldie y yo no me llevo bien?",
  ui_story_5037_50370901_79_option_content = "Niega rotundamente los rumores.",
  ui_story_5037_50370901_80_dialog_content = "¡Eso es ridículo! Goldie y yo somos el mejor dúo profesional posible de la historia.",
  ui_story_5037_50370901_81_option_content = "Explica pacientemente la situación.",
  ui_story_5037_50370901_82_dialog_content = "Nuestra relación está perfectamente bien. Trabajamos muy bien juntos, de hecho.",
  ui_story_5037_50370901_83_dialog_content = "*se burla*",
  ui_story_5037_50370901_84_dialog_content = "¡Es cierto!",
  ui_story_5037_50370901_85_dialog_content = "Y ni se te ocurra torcer nuestras palabras, o de lo contrario...",
  ui_story_5037_50370901_86_dialog_content = "¡Okey, okey!",
  ui_story_5037_50370901_87_dialog_content = "Lo siento, ¡pero debería irme!",
  ui_story_5037_50370901_88_dialog_content = "Vaya... Gracias a Dios que regresaste, PlayerName.",
  ui_story_5037_50370901_89_dialog_content = "De lo contrario, no sé a qué habría recurrido para hacer que ese tipo se fuera.",
  ui_story_5037_50370901_90_dialog_content = "Nunca supe que los paparazzi pudieran ser tan dedicados a su trabajo...",
  ui_story_5037_50370901_91_dialog_content = "Se abalanzó prácticamente en el momento en que me fui.",
  ui_story_5037_50370901_92_dialog_content = "Eso me recuerda... ¿No se supone que deberías estar de permiso?",
  ui_story_5037_50370901_93_dialog_content = "¿Qué estás haciendo en la oficina?",
  ui_story_5037_50370901_94_dialog_content = "Yo, eh... Bueno, porque...",
  ui_story_5037_50370901_95_dialog_content = "Suspiro. Mira, sé que me dijiste que descansara un poco, pero no puedo hacerlo ahora.",
  ui_story_5037_50370901_96_dialog_content = "A decir verdad... No puedo dejar de preocuparme por el concierto de evaluación.",
  ui_story_5037_50370901_97_dialog_content = "Tan pronto como empiezo a pensar en ello, pierdo el apetito y no puedo descansar.",
  ui_story_5037_50370901_98_dialog_content = "Entiendo...",
  ui_story_5037_50370901_99_dialog_content = "Sí... Es por eso que solo quiero terminar con las cosas, ¿sabes? No creo que pueda descansar bien hasta que termine el concierto.",
  ui_story_5037_50370901_100_dialog_content = "Mmm...",
  ui_story_5037_50370901_101_dialog_content = "Para ser honesto, me siento de la misma manera.",
  ui_story_5037_50370901_102_dialog_content = "Solía ser perfectamente capaz de tratar con estos reporteros chismosos... Nada de lo que dijeron o escribieron realmente me molestaba antes.",
  ui_story_5037_50370901_103_dialog_content = "Pero desde que empezamos a trabajar juntos... he confiado cada vez más en ti para manejar cosas como esta.",
  ui_story_5037_50370901_104_dialog_content = "Ahora puedo decir que me he oxidado un poco cuando se trata de regañar a esos tipos.",
  ui_story_5037_50370901_105_dialog_content = "¿Te estoy haciendo perder tu ventaja?",
  ui_story_5037_50370901_106_dialog_content = "¡De ninguna manera! En todo caso, verte aparecer hace un momento me hizo sentir más fuerte. PlayerName!",
  ui_story_5037_50370901_107_dialog_content = "Desde que te convertiste en mi productor, he podido dedicarme a entrenar, mejorando todas mis habilidades por montones.",
  ui_story_5037_50370901_108_dialog_content = "No soy la misma Goldie que solía ser. ¡Soy un Super Goldie nuevo y mejorado!",
  ui_story_5037_50370901_109_dialog_content = "Jajajaja! Bueno, me alivia que no creas que te estoy reteniendo.",
  ui_story_5037_50370901_110_dialog_content = "Un productor fantástico como tú nunca podría hacer algo así. PlayerName!",
  ui_story_5037_50370901_111_dialog_content = "Pero cuando se trata de descansar...",
  ui_story_5037_50370901_112_dialog_content = "Ya no tienes que preocuparte por mí, Goldie. Sé que estamos muy ocupados en este momento, ¡pero prometo que de ahora en adelante descansaré lo suficiente y haré ejercicio!",
  ui_story_5037_50370901_113_dialog_content = "Entonces también me aseguraré de seguir todas tus decisiones.",
  ui_story_5037_50370901_114_dialog_content = "¡Creo en ti!",
  ui_story_5037_50371001_1_dialog_content = "¡El concierto de evaluación finalmente ha terminado!",
  ui_story_5037_50371001_2_dialog_content = "¡Finalmente superamos nuestro mayor desafío! Gracias a dios.",
  ui_story_5037_50371001_3_dialog_content = "Tan pronto como tengo un momento para relajarme, de repente empiezo a sentirme tan fatigado...",
  ui_story_5037_50371001_4_dialog_content = "¡Entonces deberías celebrar descansando lo suficiente hoy!",
  ui_story_5037_50371001_5_dialog_content = "Sí, ya era hora.",
  ui_story_5037_50371001_6_dialog_content = "¿Entonces, qué debemos hacer?",
  ui_story_5037_50371001_7_dialog_content = "¡Espera, lo tengo! ¿Quieres oírme cantar?",
  ui_story_5037_50371001_8_dialog_content = "¡Estoy preparando una nueva canción para el concierto de graduación!",
  ui_story_5037_50371001_9_dialog_content = "Todavía le faltan algunas partes, pero el resto de la canción ya está terminado.",
  ui_story_5037_50371001_10_dialog_content = "¡Por supuesto! ¡Apuesto a que ya suena increíble!",
  ui_story_5037_50371001_11_dialog_content = "Entonces sin más preámbulos...",
  ui_story_5037_50371001_12_dialog_content = "♪ Aunque debemos ir por caminos separados, sé que estaremos bien ♪",
  ui_story_5037_50371001_13_dialog_content = "♪ A mil millas de distancia, pero nuestra estrella siempre brillará ♪",
  ui_story_5037_50371001_14_dialog_content = "♪ Así que por favor no llores; nuestro futuro aún está por delante ♪",
  ui_story_5037_50371001_15_dialog_content = "♪ A través de esta canción, me despido, aunque sé que nos encontraremos de nuevo ♪",
  ui_story_5037_50371001_16_dialog_content = "(Increíble...)",
  ui_story_5037_50371001_17_dialog_content = "(Pero esta vez, la letra menciona decir adiós... Y la melodía suena más suave que sus canciones anteriores).",
  ui_story_5037_50371001_18_dialog_content = "Bien, PlayerName? ¿Qué piensas?",
  ui_story_5037_50371001_19_option_content = "¡Fue hermoso!",
  ui_story_5037_50371001_20_dialog_content = "¡Por que gracias!",
  ui_story_5037_50371001_21_option_content = "Es diferente de tus canciones anteriores.",
  ui_story_5037_50371001_22_dialog_content = "Ah, entonces te diste cuenta.",
  ui_story_5037_50371001_23_dialog_content = "Después de todo, es una canción para el concierto de graduación... ¡Así que, naturalmente, la escribí con toda la gratitud de mi corazón!",
  ui_story_5037_50371001_24_dialog_content = "Pero se siente como si hubiera algo más que solo gratitud.",
  ui_story_5037_50371001_25_dialog_content = "Suena un poco triste y melancólico... No sé.",
  ui_story_5037_50371001_26_dialog_content = "Porque es una canción de despedida.",
  ui_story_5037_50371001_27_dialog_content = "¿Pero de quién te despides, Goldie?",
  ui_story_5037_50371001_28_dialog_content = "Hay algo que todavía no entiendo... ¿Qué es exactamente un concierto de graduación?",
  ui_story_5037_50371001_29_dialog_content = "Se llevan a cabo conciertos de graduación para los ídolos que renuncian y se van.",
  ui_story_5037_50371001_30_dialog_content = "Es una oportunidad para que el ídolo se despida de sus fans.",
  ui_story_5037_50371001_31_dialog_content = "¡¿Qué-?!",
  ui_story_5037_50371001_32_dialog_content = "Ya no vas a ser ídolo después de este concierto???",
  ui_story_5037_50371001_33_dialog_content = "¿De qué estás hablando? Todavía tengo muchos años de ser un ídolo en mí.",
  ui_story_5037_50371001_34_dialog_content = "¡Este concierto es solo para un video promocional! ¡Mi verdadero concierto de graduación no será hasta dentro de mucho, mucho tiempo!",
  ui_story_5037_50371001_35_dialog_content = "Además... Como mi productor, ¡quería que experimentaras lo que es trabajar con una ídolo hasta el final de su carrera!",
  ui_story_5037_50371001_36_dialog_content = "Todavía planeo ser un ídolo después, ¡tonto!",
  ui_story_5037_50371001_37_dialog_content = "Me asustaste como una mierda...",
  ui_story_5037_50371001_38_dialog_content = "Por un segundo, pensé que habías terminado con ser un ídolo.",
  ui_story_5037_50371001_39_dialog_content = "¡Claro que no!",
  ui_story_5037_50371001_40_dialog_content = "Para mí, este próximo concierto es solo la conclusión de un capítulo en mi carrera.",
  ui_story_5037_50371001_41_dialog_content = "¡Servirá como cierre de todo el tiempo que pasamos juntos y de todas las dificultades y victorias que compartimos!",
  ui_story_5037_50371001_42_dialog_content = "Comprendo.",
  ui_story_5037_50371001_43_dialog_content = "Honestamente, no puedo imaginarte haciendo otra cosa en la vida...",
  ui_story_5037_50371001_44_dialog_content = "En mi opinión, eres el epítome de un ídolo.",
  ui_story_5037_50371001_45_dialog_content = "¡No puedo decirte cuánto significa eso para mí!",
  ui_story_5037_50371001_46_dialog_content = "Si esa es la impresión que te doy, ¡entonces significa que estoy haciendo bien mi trabajo!",
  ui_story_5037_50371001_47_dialog_content = "Pero al final del día... solo soy una persona común, como todos los demás.",
  ui_story_5037_50371001_48_dialog_content = "Algún día tendré que dar un verdadero concierto de graduación y despedirme de mis fans.",
  ui_story_5037_50371001_49_dialog_content = "Hablemos de algo menos deprimente...",
  ui_story_5037_50371001_50_dialog_content = "¿Lo es? Realmente no lo creo.",
  ui_story_5037_50371001_51_dialog_content = "¿No?",
  ui_story_5037_50371001_52_dialog_content = "La graduación es solo otra parte de la vida de un ídolo, e inevitablemente nos llega a todos, ya sea que le demos la bienvenida o no.",
  ui_story_5037_50371001_53_dialog_content = "¡En lugar de tratar de evitarlo, quiero hacer todo lo posible para asegurarme de que mi propio concierto de graduación sea el mejor de todos!",
  ui_story_5037_50371001_54_dialog_content = "Pase lo que pase, no quiero arrepentirme, ni para mí ni para mis fans.",
  ui_story_5037_50371001_55_dialog_content = "Pase lo que pase, quiero asegurarme de brillar en sus corazones por el resto de sus vidas.",
  ui_story_5037_50371001_56_dialog_content = "¡Es por eso que voy a seguir dando lo mejor de mí hasta que llegue el día de la graduación!",
  ui_story_5037_50371001_57_dialog_content = "¡Eso se parece mucho a ti!",
  ui_story_5037_50371001_58_dialog_content = "Entonces, una vez que sea el momento de dejar de ser un ídolo... ¿Qué harás entonces?",
  ui_story_5037_50371001_59_dialog_content = "Hmm... ¡Todavía no lo he decidido!",
  ui_story_5037_50371001_60_dialog_content = "Tengo muchas ideas, pero ahora mismo... ¡Mi favorito es abrir mi propio café para mascotas!",
  ui_story_5037_50371001_61_dialog_content = "¡De esa manera, puedo trabajar y hacerle compañía a Marshmallow al mismo tiempo!",
  ui_story_5037_50371001_62_dialog_content = "¡Suena como una gran idea!",
  ui_story_5037_50371001_63_dialog_content = "Beber café y jugar con lindos animalitos... suena como el sueño.",
  ui_story_5037_50371001_64_dialog_content = "¡Estoy ahí contigo!",
  ui_story_5037_50371001_65_dialog_content = "Cada vez que me siento cansado, acariciar el pelaje suave y esponjoso de Marshmallow siempre me ayuda a relajarme.",
  ui_story_5037_50371001_66_dialog_content = "Como ídolo, mi trabajo es animar a todos con el poder del canto y el baile.",
  ui_story_5037_50371001_67_dialog_content = "¡Un café para mascotas me ayudaría a seguir alegrando la vida de todos después de jubilarme!",
  ui_story_5037_50371001_68_dialog_content = "Pase lo que pase en la vida, sé que estaré bien con eso.",
  ui_story_5037_50371101_1_dialog_content = "(Hoy encontré una carta de Vic en la oficina. Estaba dirigida a mí).",
  ui_story_5037_50371101_2_dialog_content = "(Dijo que lo esperara en el salón de baile más tarde hoy... Que quería preguntarme algunas cosas en privado.)",
  ui_story_5037_50371101_3_dialog_content = "¡Usted vino!",
  ui_story_5037_50371101_4_dialog_content = "¿Hmm? Eres tu, Fia?",
  ui_story_5037_50371101_5_dialog_content = "Ay, ay, ay... ¡Disminuye la velocidad, Fia! ¡Vas a arrancarle la oreja a tu pobre amo!",
  ui_story_5037_50371101_6_dialog_content = "¿Qué están haciendo ustedes aquí?",
  ui_story_5037_50371101_7_dialog_content = "Te dije que no había razón para molestarte con esto, Fia!",
  ui_story_5037_50371101_8_dialog_content = "Incluso si PlayerName es nuestro amigo, ¡aún necesita aclarar las cosas!",
  ui_story_5037_50371101_9_dialog_content = "... ¿Podría alguien explicar qué está pasando?",
  ui_story_5037_50371101_10_dialog_content = "Muy bien, déjame ser directo. ¿Qué pasa con ese paparazzi que ha estado corriendo por aquí todos los días?",
  ui_story_5037_50371101_11_dialog_content = "¿Paparazzi?",
  ui_story_5037_50371101_12_dialog_content = "Oh, ¿te refieres a ese tipo de aspecto incompleto con barba?",
  ui_story_5037_50371101_13_dialog_content = "¡Sí, ese es! ¡Así que lo conoces!",
  ui_story_5037_50371101_14_dialog_content = "¡Ese idiota sigue irrumpiendo e interrumpiendo el entrenamiento de mi maestro inútil!",
  ui_story_5037_50371101_15_dialog_content = "Lo que es peor es que cada vez que lo echo... ¡Al día siguiente, publica un artículo cruel que calumnia al Maestro y alaba a Goldie en su lugar!",
  ui_story_5037_50371101_16_dialog_content = "¡Di la verdad! ¿Está trabajando para ustedes?",
  ui_story_5037_50371101_17_dialog_content = "... ¿De verdad crees que yo haría algo así?",
  ui_story_5037_50371101_18_dialog_content = "¡A nosotros también nos acosa todos los días!",
  ui_story_5037_50371101_19_dialog_content = "¿En serio?",
  ui_story_5037_50371101_20_dialog_content = "¿Ver? ¡Te dije que no eran ellos!",
  ui_story_5037_50371101_21_dialog_content = "El mismo periódico que me calumnió también ha hecho lo mismo con Goldie en el pasado.",
  ui_story_5037_50371101_22_dialog_content = "¿D-De veras?",
  ui_story_5037_50371101_23_dialog_content = "Supongo que solo he estado leyendo cosas sobre mi bueno para nada Maestro...",
  ui_story_5037_50371101_24_dialog_content = "Sin embargo, ahora que lo mencionas... creo que también recuerdo haber visto artículos difamatorios sobre Vic.",
  ui_story_5037_50371101_25_dialog_content = "Pero si ustedes no lo enviaron aquí, ¿quién lo hizo?",
  ui_story_5037_50371101_26_dialog_content = "Creo que sigue viniendo porque cree que este lugar está lleno de chismes sobre los que escribir.",
  ui_story_5037_50371101_27_dialog_content = "Aunque me aseguro de cerrar la puerta con llave todos los días antes de irme, siempre se las arregla para entrar...",
  ui_story_5037_50371101_28_dialog_content = "¡Lo juro, simplemente no hay forma de deshacerse de él!",
  ui_story_5037_50371101_29_dialog_content = "¡Lo sé, eh! ¡Él también nos está costando muchos fans!",
  ui_story_5037_50371101_30_dialog_content = "Así que supongo que todo esto fue solo un malentendido...",
  ui_story_5037_50371101_31_dialog_content = "Lo siento por sospechar de ti.",
  ui_story_5037_50371101_32_dialog_content = "No te preocupes por eso, Fía. ¿Necesitan algo más?",
  ui_story_5037_50371101_33_dialog_content = "¡No! El Maestro todavía tiene mucho entrenamiento por hacer, ¡así que nos vemos más tarde!",
  ui_story_5037_50371101_34_dialog_content = "Hagamos todo lo posible, ¿de acuerdo?",
  ui_story_5037_50371101_35_dialog_content = "Claro, entonces—",
  ui_story_5037_50371101_36_dialog_content = "<size=45>¡Espera!</size>",
  ui_story_5037_50371101_37_dialog_content = "¿Eh? ¿Ahora que?",
  ui_story_5037_50371101_38_dialog_content = "Tengo una pequeña petición, PlayerName.",
  ui_story_5037_50371101_39_dialog_content = "¿S-Sí...?",
  ui_story_5037_50371101_40_dialog_content = "¿Podrías... podrías enseñarme cómo lidiar con los paparazzi? ¡Te lo ruego!",
  ui_story_5037_50371101_41_dialog_content = "¡¿Eh?! M-Cuidado con mi espacio personal!",
  ui_story_5037_50371101_42_dialog_content = "¡Deja de usar mi diadema para secarte las lágrimas!",
  ui_story_5037_50371101_43_dialog_content = "*Olfatea* Está bien...",
  ui_story_5037_50371101_44_dialog_content = "Gracias a ese estúpido reportero y todas sus mentiras... ¡He perdido más fans de los que puedo permitirme perder!",
  ui_story_5037_50371101_45_dialog_content = "La única forma de compensar a mis fanáticos perdidos es entrenar más duro que nunca y participar en tantos eventos de ídolos como sea posible.",
  ui_story_5037_50371101_46_dialog_content = "Fia tampoco me dejará salir... ¡Me mira como un halcón durante el entrenamiento, así que no puedo holgazanear ni por un segundo!",
  ui_story_5037_50371101_47_dialog_content = "Vaya, justo en la última sesión de entrenamiento, traté de recuperar el aliento por unos momentos... ¡Y ella hizo que Kyllo me mordiera la pierna!",
  ui_story_5037_50371101_48_dialog_content = "Solo mira esto, PlayerName! ¡Mi pierna tiene más marcas de mordeduras que un juguete para masticar! Tienes que salvarme...",
  ui_story_5037_50371101_49_dialog_content = "¡Bien, bien! ¡Te enseñaré lo que sé!",
  ui_story_5037_50371101_50_dialog_content = "¡Sabía que podía contar contigo!",
  ui_story_5037_50371101_51_dialog_content = "Ahora, por dónde deberíamos empezar...",
  ui_story_5037_50371101_52_dialog_content = "¿Por qué no echamos un vistazo a la edición de hoy del Daily Drivel primero? Vamos a ver...",
  ui_story_5037_50371101_53_dialog_content = "\"Vic una vez se describió a sí mismo como un eterno joven de 18 años, pero su edad real es mucho mayor que eso\"?!",
  ui_story_5037_50371101_54_dialog_content = "Quiero decir, esto suena como una declaración verdadera.",
  ui_story_5037_50371101_55_dialog_content = "¡Ay, lo recuerdo! Supongo que dije eso sobre mí, sí...",
  ui_story_5037_50371101_56_dialog_content = "¡¿Cómo es esto una mentira, entonces?!",
  ui_story_5037_50371101_57_dialog_content = "¡Mi edad real es un secreto!",
  ui_story_5037_50371101_58_dialog_content = "Bien... Supongo que está bien, solo recuerda mantenerlo en secreto.",
  ui_story_5037_50371101_59_dialog_content = "¿Qué más dice? ¿\"Vic cree que es mucho más joven y enérgico que el siempre popular Goldie\"?",
  ui_story_5037_50371101_60_dialog_content = "¿eh? ¡Esas fueron sus palabras, no las mías! ¡Dijo eso mientras felicitaba mi desempeño!",
  ui_story_5037_50371101_61_dialog_content = "Entonces... ¿Cómo respondiste?",
  ui_story_5037_50371101_62_dialog_content = "¡Bueno, un cumplido es un cumplido! ¿Por qué lo negaría?",
  ui_story_5037_50371101_63_dialog_content = "Si estás de acuerdo con lo que dice, ¡eso te convierte en un objetivo aún más fácil, Vic!",
  ui_story_5037_50371101_64_dialog_content = "¡¿E-entonces cómo debería haber respondido?!",
  ui_story_5037_50371101_65_dialog_content = "Su fraseo estaba destinado a engañarte para que admitas que crees que eres mejor que los otros ídolos.",
  ui_story_5037_50371101_66_dialog_content = "Así que si te encuentras en una situación similar, trata de ser más humilde y di que los demás son mejores que tú. ¡De esa manera, no tendrá nada con qué trabajar!",
  ui_story_5037_50371101_67_dialog_content = "Bien bien. ¡Lo intentaré la próxima vez!",
  ui_story_5037_50371101_68_dialog_content = "Sigamos leyendo...",
  ui_story_5037_50371101_69_dialog_content = "¿\"Se sabe que el productor de Vic amenaza a reporteros inocentes con animales salvajes y violentos\"?",
  ui_story_5037_50371101_70_dialog_content = "Fia... ¿Qué hiciste?",
  ui_story_5037_50371101_71_dialog_content = "¡N-No me mires!",
  ui_story_5037_50371101_72_dialog_content = "Era demasiado molesto, ¡así que hice que Kyllo lo arrojara a la calle!",
  ui_story_5037_50371101_73_dialog_content = "Ya veo... No hagamos eso más, ¿de acuerdo?",
  ui_story_5037_50371101_74_dialog_content = "No importa cuán irritantes sean estos reporteros, recurrir a la violencia nunca es la forma correcta de tratar con ellos.",
  ui_story_5037_50371101_75_dialog_content = "Solo les estás dando más razones para atacarte con sus calumnias.",
  ui_story_5037_50371101_76_dialog_content = "Entonces, ¿cómo debo tratar con ellos?",
  ui_story_5037_50371101_77_dialog_content = "No puedo evitar que entren, y no puedo hacer que se vayan... ¡Son como un enjambre de mosquitos pero aún más feroces!",
  ui_story_5037_50371101_78_dialog_content = "Cuando te molestan así, solo puedes insistir cortésmente en que no estás aceptando entrevistas y rechazarlas.",
  ui_story_5037_50371101_79_dialog_content = "De esa manera, incluso si calumnian Vic en sus artículos, sus afirmaciones no tendrán ninguna evidencia real que las respalde, lo que la gente notará.",
  ui_story_5037_50371101_80_dialog_content = "También, mientras Vic sigue mejorando, ninguna cantidad de chismes podrá dañar su reputación.",
  ui_story_5037_50371101_81_dialog_content = "Está bien, creo que ahora entiendo.",
  ui_story_5037_50371101_82_dialog_content = "Gracias, PlayerName. ¡Realmente eres un salvavidas!",
  ui_story_5037_50371101_83_dialog_content = "No lo menciones. Puede que seamos rivales por el momento, pero siempre seremos amigos primero.",
  ui_story_5037_50371101_84_dialog_content = "¡Nunca dejaría que algo tan trivial como un concurso se interpusiera en ayudar a mis amigos!",
  ui_story_5037_50371101_85_dialog_content = "*Sollozando* ¡Realmente eres mi héroe!",
  ui_story_5037_50371101_86_dialog_content = "Muchas gracias, PlayerName!",
  ui_story_5037_50371101_87_dialog_content = "¡Juro por mi honor como extrozoólogo e ídolo que no los defraudaré!",
  ui_story_5037_50371101_88_dialog_content = "Cuando Fia estaba investigando cómo convertirse en productora, encontró un par de libros que podrían resultarle útiles.",
  ui_story_5037_50371101_89_dialog_content = "Anímate y elige uno entre ellos. Considéralo una muestra de nuestra gratitud.",
  ui_story_5037_50371101_90_dialog_content = "Espera... ¿No son estos mis libros? Con razón no pude encontrarlos todo este tiempo... ¡Los estabas escondiendo en tu ropa!",
  ui_story_5037_50371101_91_dialog_content = "A-De todos modos, ya he leído los dos, así que elige el que quieras, PlayerName.",
  ui_story_5037_50371101_92_dialog_content = "Gracias... Me quedo con este por ahora—",
  ui_story_5037_50371101_93_option_content = "\"Curso intensivo para nuevos ídolos\"",
  ui_story_5037_50371101_94_option_content = "\"Desarrollo profesional para productores profesionales\"",
  ui_story_5037_50371101_95_dialog_content = "¡Derecha! ¡Deberíamos volver a nuestro entrenamiento ahora!",
  ui_story_5037_50371101_96_dialog_content = "¡Vámonos, maestro inútil! ¡El día aún no ha terminado!",
  ui_story_5037_50371101_97_dialog_content = "¡¿E-Eh?! ¡¿Todavía?!",
  ui_story_5037_50371101_98_dialog_content = "¡Así es! Perdimos mucho tiempo precioso hablando con PlayerName, ¡así que ahora te lo vas a inventar todo!",
  ui_story_5037_50371101_99_dialog_content = "Alguien sálvame... Por favor...",
  ui_story_5037_50371201_1_dialog_content = "Vic me pidió que lo esperara aquí... ¿No sabe que el concurso de conciertos está a la vuelta de la esquina?",
  ui_story_5037_50371201_2_dialog_content = "Incluso me dijo que viniera aquí solo, y que lo mantuviera en secreto de Fia...",
  ui_story_5037_50371201_3_dialog_content = "¿Qué diablos está haciendo ahora?",
  ui_story_5037_50371201_4_dialog_content = "¿Oh? A tiempo, tal como esperaba! Que bueno verte, PlayerName!",
  ui_story_5037_50371201_5_dialog_content = "Muy bien Vic, dime qué está pasando...",
  ui_story_5037_50371201_6_dialog_content = "¡Oh, nada terriblemente importante, de verdad! Sólo quería preguntar...",
  ui_story_5037_50371201_7_dialog_content = "¿Podrías dejarme esconderme aquí por un día? ¡¿Por favor?!",
  ui_story_5037_50371201_8_dialog_content = "Eh...?!",
  ui_story_5037_50371201_9_dialog_content = "Es casi la hora del concierto, ¿por qué querrías esconderte aquí en lugar de entrenar?",
  ui_story_5037_50371201_10_dialog_content = "¡Precisamente por mi formación! Solo escucha, así es como se ve un día normal para mí...",
  ui_story_5037_50371201_11_dialog_content = "Fia me despierta todas las mañanas para entrenar antes de que salga el sol.",
  ui_story_5037_50371201_12_dialog_content = "¡Levántate, Maestro perezoso! ¡Es hora de entrenar!",
  ui_story_5037_50371201_13_dialog_content = "¡Comencemos por poner en forma ese cuerpo fofo! ¡Diez vueltas por el bosque, vamos!",
  ui_story_5037_50371201_14_dialog_content = "Hrnnng... Pero tengo tanto sueño...",
  ui_story_5037_50371201_15_dialog_content = "Sólo cinco minutos más...",
  ui_story_5037_50371201_16_dialog_content = "¿No cooperas? Bien por mí... ¡Atrápalo, Kyllo!",
  ui_story_5037_50371201_17_dialog_content = "Lo-!",
  ui_story_5037_50371201_18_dialog_content = "¡¡¡Ay!!!",
  ui_story_5037_50371201_19_dialog_content = "¡D-Deja de morder! ¡¡¡Estoy arriba, estoy arriba!!!",
  ui_story_5037_50371201_20_dialog_content = "Después de correr, me doy una ducha rápida y desayuno.",
  ui_story_5037_50371201_21_dialog_content = "¡El desayuno de hoy es un bollo de aserrín con una guarnición de zanahorias hervidas y un vaso de leche!",
  ui_story_5037_50371201_22_dialog_content = "P-Pero he comido zanahorias hervidas durante tres días seguidos... ¿No podemos cambiar un poco las cosas?",
  ui_story_5037_50371201_23_dialog_content = "¿Como unas brochetas de gusanos de arena a la parrilla chisporroteantes y picantes?",
  ui_story_5037_50371201_24_dialog_content = "¡Eres un ídolo ahora, Maestro, y los ídolos deben cuidar su figura en todo momento! Si no quieres zanahorias hervidas, no tienes suerte... Porque, ¿adivina qué hay para el almuerzo y la cena?",
  ui_story_5037_50371201_25_dialog_content = "¡Nooooooo!",
  ui_story_5037_50371201_26_dialog_content = "Oh y-",
  ui_story_5037_50371201_27_dialog_content = "Urgh... Creo que ya he oído suficiente, Vic...",
  ui_story_5037_50371201_28_dialog_content = "Por eso, en interés de mi salud y de mi cordura, te lo ruego, PlayerName... ¡Déjame esconderme aquí por un día y descansar!",
  ui_story_5037_50371201_29_dialog_content = "¡Solo un día es más que suficiente! ¡Ningún Auroriano debería tener que pasar por este tipo de infierno!",
  ui_story_5037_50371201_30_dialog_content = "¡Si esto continúa, el mundo perderá a su mejor extrozoólogo en muy poco tiempo!",
  ui_story_5037_50371201_31_dialog_content = "Tú... yo... suspiro...",
  ui_story_5037_50371201_32_dialog_content = "Sé que Fia solo está haciendo esto para ayudarte a pasar el concurso de conciertos, pero su régimen de entrenamiento parece un poco... estricto.",
  ui_story_5037_50371201_33_dialog_content = "Puedes quedarte aquí y descansar un poco, pero solo con dos condiciones:",
  ui_story_5037_50371201_34_dialog_content = "Uno, tienes que volver con Fia tan pronto como hayas descansado, para que ella no se preocupe por ti.",
  ui_story_5037_50371201_35_dialog_content = "Y dos... Necesitas tener una charla seria con Fia acerca de sus sentimientos sobre su régimen de entrenamiento.",
  ui_story_5037_50371201_36_dialog_content = "¡No es un problema! Mientras logre perder, er... quiero decir, perder algo de esta fatiga. ¡Yo haré cualquier cosa que usted quiera!",
  ui_story_5037_50371201_37_dialog_content = "Muy bien, entonces descansa un poco, Vic. Todavía tengo que preparar el horario de Goldie para hoy, así que te dejo en paz.",
  ui_story_5037_50371201_38_dialog_content = "¡Sí, sí, adelante! ¡Estaré bien solo!",
  ui_story_5037_50371201_39_dialog_content = "Este sofá se ve terriblemente cómodo... ¡Perfecto para una buena y larga siesta!",
  ui_story_5037_50371201_40_dialog_content = "¡Muy bien, mi Little Furball, ven aquí y déjame abrazarte mientras duermo!",
  ui_story_5037_50371201_41_dialog_content = "¡Chirrido!",
  ui_story_5037_50371201_42_dialog_content = "Ronca... Ronca...",
  ui_story_5037_50371201_43_dialog_content = "(¿Ya está dormido? Esa es Vic para ti, supongo...)",
  ui_story_5037_50371201_44_dialog_content = "(Bueno, debería volver al trabajo ahora).",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371201_46_dialog_content = "(¡Muy bien, eso debería bastar para el horario! ¡Creo que estoy empezando a acostumbrarme a estas cosas!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>¡TOC Toc!</color>",
  ui_story_5037_50371201_48_dialog_content = "(¿Hmm? Alguien está en la puerta...)",
  ui_story_5037_50371201_49_dialog_content = "¿Hola?",
  ui_story_5037_50371201_50_dialog_content = "hola, PlayerName! ¡Soy yo, Fía!",
  ui_story_5037_50371201_51_dialog_content = "(¡¿F-Fia?!)",
  ui_story_5037_50371201_52_dialog_content = "(Oh no... ¡Vic todavía está aquí!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>¡TOC Toc!</color>",
  ui_story_5037_50371201_54_dialog_content = "¿PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "¡J-Solo un segundo!",
  ui_story_5037_50371201_56_dialog_content = "Vic! ¡Despierta, Vic!",
  ui_story_5037_50371201_57_dialog_content = "Nnng... Jaja... Detente, pequeña bola de pelo... Jajaja...",
  ui_story_5037_50371201_58_dialog_content = "¡Él duerme aún más pesado que yo!",
  ui_story_5037_50371201_59_dialog_content = "(Supongo que no se puede evitar... Tendré que esconderlo por ahora.)",
  ui_story_5037_50371201_60_dialog_content = "(Déjame ver... Esta pila de revistas se ve bien. ¡Lo esconderé detrás de ella!)",
  ui_story_5037_50371201_61_dialog_content = "¡Ya voy, Fía!",
  ui_story_5037_50371201_62_dialog_content = "¿Qué te tomó tanto tiempo?",
  ui_story_5037_50371201_63_dialog_content = "Lo siento, solo estaba, eh... ¡Limpiando la habitación!",
  ui_story_5037_50371201_64_dialog_content = "Bueno, parece que al lugar le vendría bien un poco de orden... ¡Esa pila de revistas es tan grande como una montaña!",
  ui_story_5037_50371201_65_dialog_content = "Ajá... ja... De todos modos, ¿necesitas algo? Fia?",
  ui_story_5037_50371201_66_dialog_content = "Sí, en realidad... ¿Has visto al Maestro Vic por aquí últimamente?",
  ui_story_5037_50371201_67_dialog_content = "¿V-Vic? ¡No, no puedo decir que tengo!",
  ui_story_5037_50371201_68_dialog_content = "¿No dices...?",
  ui_story_5037_50371201_69_dialog_content = "Hoy he estado limpiando todo el día, además de trabajar en el horario de Goldie... ¡Así que no, no he visto a Vic nada hoy!",
  ui_story_5037_50371201_70_dialog_content = "Suspiro... Si tú lo dices. Sinceramente, me sorprende que no haya venido corriendo hacia ti primero...",
  ui_story_5037_50371201_71_dialog_content = "¿Adónde se escapó ese inútil maestro mío...?",
  ui_story_5037_50371201_72_dialog_content = "¿Quizás fue a algún lugar para holgazanear un poco? Estoy seguro de que volverá pronto.",
  ui_story_5037_50371201_73_dialog_content = "Faltan solo unos días para el concierto... No puedo creer que ese tipo todavía piense que puede joder así.",
  ui_story_5037_50371201_74_dialog_content = "Me aseguraré de entrenarlo más duro cuando regrese...",
  ui_story_5037_50371201_75_dialog_content = "¿Es posible que tu entrenamiento sea la razón por la que se escapó, Fia?",
  ui_story_5037_50371201_76_dialog_content = "Está bien tomarse el entrenamiento en serio y todo eso... Pero también debes recordar equilibrarlo con el descanso.",
  ui_story_5037_50371201_77_dialog_content = "¿Crees?",
  ui_story_5037_50371201_78_dialog_content = "Sabes, estaba pensando en darle el día libre, para que pudiera descansar un poco...",
  ui_story_5037_50371201_79_dialog_content = "¡Pero de repente desapareció de mí! He buscado por todo Umbraton, pero todavía no hay señales de él.",
  ui_story_5037_50371201_80_dialog_content = "(Fia estaba planeando dar Vic un día libre todo el tiempo? Así que ella ha estado organizando su horario correctamente).",
  ui_story_5037_50371201_81_dialog_content = "No te preocupes Fía. Les pediré a todos que te ayuden a buscarlo.",
  ui_story_5037_50371201_82_dialog_content = "Seguro gracias. Seguiré buscando, entonces.",
  ui_story_5037_50371201_83_dialog_content = "Espera un segundo... ¿No es eso...?",
  ui_story_5037_50371201_84_dialog_content = "(¡Mierda! ¡Se dio cuenta de la pila de revistas debajo de la cual se esconde Vic!)",
  ui_story_5037_50371201_85_dialog_content = "¡Oh! ¡Lo siento, esas son solo algunas revistas que estaba hojeando antes! Los limpiaré en un momento—",
  ui_story_5037_50371201_86_dialog_content = "Parece un poco divertido, ¿no? Como si hubiera algo enterrado debajo...",
  ui_story_5037_50371201_87_dialog_content = "No, espera-!",
  ui_story_5037_50371201_88_dialog_content = "M-Maestro?!",
  ui_story_5037_50371201_89_dialog_content = "Ronca... Ronca...",
  ui_story_5037_50371201_90_dialog_content = "¡¿Q-Qué hace durmiendo aquí?!",
  ui_story_5037_50371201_91_dialog_content = "PlayerName... ¿Me estabas mintiendo?",
  ui_story_5037_50371201_92_dialog_content = "yo, eh...",
  ui_story_5037_50371201_93_option_content = "Confesar",
  ui_story_5037_50371201_94_dialog_content = "Está bien, lo confieso... Te estaba mintiendo antes.",
  ui_story_5037_50371201_95_dialog_content = "Lo siento...",
  ui_story_5037_50371201_96_dialog_content = "Está bien, PlayerName. Sé que no me mentirías a propósito.",
  ui_story_5037_50371201_97_option_content = "Inventar algo",
  ui_story_5037_50371201_98_dialog_content = "¡D-Debe haberse colado aquí antes de que yo llegara! Sí, debe ser eso...",
  ui_story_5037_50371201_99_dialog_content = "Puedo decir que estás mintiendo, PlayerName... Está escrito por toda la cara.",
  ui_story_5037_50371201_100_dialog_content = "Pero creo que sé lo que está pasando aquí.",
  ui_story_5037_50371201_101_dialog_content = "Mi maestro inútil te rogó que lo dejaras quedarse aquí, ¿no es así?",
  ui_story_5037_50371201_102_dialog_content = "Bueno, la verdad es...",
  ui_story_5037_50371201_103_dialog_content = "Vic vino a verme esta mañana y me preguntó si podía esconderse aquí y descansar durante el día.",
  ui_story_5037_50371201_104_dialog_content = "Dijo que su entrenamiento como ídolo lo había dejado completamente exhausto y que se desmayó poco después de llegar aquí.",
  ui_story_5037_50371201_105_dialog_content = "¡Pero no entiendo! ¿Por qué huyó y te encontró en lugar de hablar conmigo?",
  ui_story_5037_50371201_106_dialog_content = "¡Estaba planeando darle el día libre y todo!",
  ui_story_5037_50371201_107_dialog_content = "¿Por qué no hablas con él una vez que se despierta?",
  ui_story_5037_50371201_108_dialog_content = "Suspiro... Olvídalo. Lo dejaré descansar aquí por ahora.",
  ui_story_5037_50371201_109_dialog_content = "Recuérdale que vuelva a entrenar una vez que se despierte, ¿de acuerdo?",
  ui_story_5037_50371201_110_dialog_content = "Reuniré algunos consejos y trucos para el entrenamiento de ídolos para compartirlos contigo más adelante. Tómalo como mi forma de decir gracias por vigilar a mi bueno para nada maestro.",
  ui_story_5037_50371201_111_dialog_content = "¡Seguro gracias!",
  ui_story_5037_50371201_112_dialog_content = "Ah, y una última cosa... No le digas que vine aquí, ¿entendido?",
  ui_story_5037_50371201_113_dialog_content = "Claro, pero ¿por qué?",
  ui_story_5037_50371201_114_dialog_content = "Porque...",
  ui_story_5037_50371201_115_dialog_content = "<size=45>¡El Maestro es completamente desconfiado!</size>",
  ui_story_5037_50371201_116_dialog_content = "¡¿Eh?!",
  ui_story_5037_50371201_117_dialog_content = "¡Si le das una pulgada, tomará una milla antes de que te des cuenta!",
  ui_story_5037_50371201_118_dialog_content = "Ya sea entrenando o simplemente haciendo cosas en la casa, encontrará más excusas para holgazanear si se entera de que le voy a dar un descanso.",
  ui_story_5037_50371201_119_dialog_content = "¡Para personas como él, la única forma de lograr que cooperen es siendo despiadadamente estrictos!",
  ui_story_5037_50371201_120_dialog_content = "¡E-está bien!",
  ui_story_5037_50371201_121_dialog_content = "¡Lo enviaré de regreso a entrenar tan pronto como se despierte!",
  ui_story_5037_50371301_1_dialog_content = "¿Por qué tiene que suceder esto ahora mismo, de todos los tiempos?",
  ui_story_5037_50371301_2_dialog_content = "Bueno, realmente no veo un problema aquí...",
  ui_story_5037_50371301_3_dialog_content = "¡Solo un maestro inútil como tú diría eso en un momento como este!",
  ui_story_5037_50371301_4_dialog_content = "¿Esta situación es realmente mala?",
  ui_story_5037_50371301_5_dialog_content = "Me temo que sí...",
  ui_story_5037_50371301_6_dialog_content = "¡Estamos en serios problemas ahora, todos!",
  ui_story_5037_50371301_7_dialog_content = "Por mucho que lo intentemos... Goldie ¡y el progreso de Vic está empezando a ralentizarse!",
  ui_story_5037_50371301_8_dialog_content = "¡Esto es lo que llaman la temida \"meseta\"!",
  ui_story_5037_50371301_9_dialog_content = "Fia y se me ocurrió una solución única a nuestro problema para que podamos desarrollar todo nuestro potencial antes de nuestros conciertos de graduación.",
  ui_story_5037_50371301_10_dialog_content = "¡Vamos a cambiar de productor!",
  ui_story_5037_50371301_11_dialog_content = "¡¿Eh?!",
  ui_story_5037_50371301_12_dialog_content = "¡Así es! Vas a entrenar a mi amo bueno para nada, PlayerName! Mientras tanto, trabajaré con Goldie en su entrenamiento.",
  ui_story_5037_50371301_13_dialog_content = "¡Prepárese para un programa de intercambio de capacitación de un día súper emocionante!",
  ui_story_5037_50371301_14_dialog_content = "Con nuevos productores, nuevos regímenes de entrenamiento y nuevos entornos para todos los involucrados... ¡Estoy seguro de que encontraremos una inspiración nueva y emocionante para superar nuestros estancamientos!",
  ui_story_5037_50371301_15_dialog_content = "Entonces, ¿significa esto... que estaré a cargo de entrenar a Vic?",
  ui_story_5037_50371301_16_dialog_content = "¡Oh! Me parece una buena idea! Tal vez finalmente pueda tomármelo con calma por un tiempo...",
  ui_story_5037_50371301_17_dialog_content = "¡Ay, ay, ay! ¡Ese era mi pie, Fia!",
  ui_story_5037_50371301_18_dialog_content = "Nosotros también pensamos en eso, Maestro. Aquí tienes, PlayerName; Kyllo será tu asistente para el intercambio de entrenamiento.",
  ui_story_5037_50371301_19_dialog_content = "¡Lo!",
  ui_story_5037_50371301_20_dialog_content = "Y no te preocupes, Kyllo sabe exactamente qué hacer si el Amo hace el tonto o se niega a levantarse de la cama... ¿Verdad, Kyllo?",
  ui_story_5037_50371301_21_dialog_content = "Realmente pensaste en todo, Fia...",
  ui_story_5037_50371301_22_dialog_content = "¡Muy bien, entonces está resuelto!",
  ui_story_5037_50371301_23_dialog_content = "Haz tu mejor esfuerzo para ayudar a Vic como lo haces conmigo, ¿de acuerdo? PlayerName?",
  ui_story_5037_50371301_24_dialog_content = "¡Sé que lo harás genial!",
  ui_story_5037_50371301_25_dialog_content = "Claro, déjamelo a mí.",
  ui_story_5037_50371301_26_dialog_content = "¡Nos vamos, entonces! ¡Buena suerte a los dos!",
  ui_story_5037_50371301_27_dialog_content = "Ahora un merecido descanso—",
  ui_story_5037_50371301_28_dialog_content = "¡¡¡Ay!!!",
  ui_story_5037_50371301_29_dialog_content = "¡L-Suéltame, Kyllo! Mi pierna no es para comer!!!",
  ui_story_5037_50371301_30_dialog_content = "¡Lo!",
  ui_story_5037_50371301_31_dialog_content = "Wow... Kyllo incluso puede darse cuenta cuando estás pensando en holgazanear, Vic. Muy impresionante.",
  ui_story_5037_50371301_32_dialog_content = "Suspiro... Fia realmente te puso en mi contra, ¿verdad, Kyllo?",
  ui_story_5037_50371301_33_dialog_content = "¡Después de todo lo que hice por ti también! Criándote desde que naciste, dándote una manera de sobrevivir en el mundo...",
  ui_story_5037_50371301_34_dialog_content = "¡¡¡Ay!!!",
  ui_story_5037_50371301_35_dialog_content = "Parece que Kyllo habla en serio, Vic... Deberíamos empezar con el entrenamiento.",
  ui_story_5037_50371301_36_dialog_content = "*Sollozando* ¿Por qué siempre soy yo el que sale lastimado...?",
  ui_story_5037_50371301_37_dialog_content = "No te preocupes Vic. Equilibro el trabajo y el descanso con mi entrenamiento, así que deberías estar bien.",
  ui_story_5037_50371301_38_dialog_content = "Lo primero en la agenda de hoy son los ejercicios vocales.",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371301_40_dialog_content = "♪ ¡Ah, la primavera ha llegado aquí y todo ha vuelto a la vida! ♪",
  ui_story_5037_50371301_41_dialog_content = "♪ Los animales salen de sus madrigueras y guaridas ♪",
  ui_story_5037_50371301_42_dialog_content = "♪ En los bosques y en las praderas ♪",
  ui_story_5037_50371301_43_dialog_content = "Muy bien, puedes tomarte un descanso ahora, Vic.",
  ui_story_5037_50371301_44_dialog_content = "¡Por fin! ¡Por fin es tiempo de descanso!",
  ui_story_5037_50371301_45_dialog_content = "Lo...",
  ui_story_5037_50371301_46_dialog_content = "¡No voy a holgazanear esta vez, Kyllo! ¡Este es un descanso real y honesto!",
  ui_story_5037_50371301_47_dialog_content = "Oye Vic? Estuve queriendo preguntar... ¿Qué te hizo querer convertirte en un ídolo en primer lugar?",
  ui_story_5037_50371301_48_dialog_content = "¿Eh? Lo tienes todo mal.",
  ui_story_5037_50371301_49_dialog_content = "¿Ah?",
  ui_story_5037_50371301_50_dialog_content = "En primer lugar, no soy un ídolo. ¡Soy, y siempre seré, un extrozoólogo!",
  ui_story_5037_50371301_51_dialog_content = "Entonces, ¿qué estás haciendo en la competencia?",
  ui_story_5037_50371301_52_dialog_content = "¡Para ganar dinero, obviamente!",
  ui_story_5037_50371301_53_dialog_content = "Estás en esto... ¿por el dinero del premio?",
  ui_story_5037_50371301_54_dialog_content = "Quiero decir, sé que Lady Sheol está ofreciendo un gran premio, y sé que tu situación financiera suele ser bastante sombría...",
  ui_story_5037_50371301_55_dialog_content = "Pero ¿por qué es Fia involucrado también?",
  ui_story_5037_50371301_56_dialog_content = "¡Fue idea de Fia en primer lugar! Vio un cartel para el concurso y decidió arrastrarme a su plan...",
  ui_story_5037_50371301_57_dialog_content = "Nos estábamos quedando sin fondos para cuidar de nuestras maravillosas bestias...",
  ui_story_5037_50371301_58_dialog_content = "¿Qué tan bajo?",
  ui_story_5037_50371301_59_dialog_content = "Bueno... tuve que endeudarme un poco solo para comprar bocadillos de Bica y Drakolion...",
  ui_story_5037_50371301_60_dialog_content = "¡¿Así de mal?!",
  ui_story_5037_50371301_61_dialog_content = "Espera... ¿No deberías dejar de comer bocadillos para ahorrar dinero si las cosas están tan mal?",
  ui_story_5037_50371301_62_dialog_content = "¡De ninguna manera!",
  ui_story_5037_50371301_63_dialog_content = "Esas bestias maravillosas son mis amigos; ¡No podría vivir conmigo mismo si tuvieran que vivir sin sus comodidades!",
  ui_story_5037_50371301_64_dialog_content = "Generalmente, Fia y Shira ganan dinero haciendo trabajos ocasionales entre sus proyectos de investigación, por lo que nunca tuvimos que preocuparnos por endeudarnos.",
  ui_story_5037_50371301_65_dialog_content = "Pero durante la última expedición de Fia, pasó una increíble cantidad de tiempo investigando una extraña bestia maravillosa, solo para regresar sin ningún resultado notable.",
  ui_story_5037_50371301_66_dialog_content = "¡Y así, nuestros ahorros se agotaron y tuve que pedir prestado un montón de dinero!",
  ui_story_5037_50371301_67_dialog_content = "... ¿Puedo preguntar qué estabas haciendo mientras ella no estaba?",
  ui_story_5037_50371301_68_dialog_content = "¿Yo? Bueno, naturalmente, estaba cuidando de las maravillosas bestias y conservando mi energía con muchas siestas...",
  ui_story_5037_50371301_69_dialog_content = "¡Parece que no estabas tratando de ayudar en absoluto!",
  ui_story_5037_50371301_70_dialog_content = "De repente, siento que entiendo Fia y la lucha de Shira mucho mas...",
  ui_story_5037_50371301_71_dialog_content = "Bueno, ahora estoy aquí ganando dinero, ¿no? ¡Incluso acepté todas estas actuaciones tontas!",
  ui_story_5037_50371301_72_dialog_content = "¡He estado trabajando muy duro hasta ahora!",
  ui_story_5037_50371301_73_dialog_content = "Lo sé, lo sé... Honestamente, esperaba que te rindieras a mitad de camino y trataras de encontrar una salida a esto.",
  ui_story_5037_50371301_74_dialog_content = "¡Yo nunca haría tal cosa! ¡Especialmente cuando se trata de asegurar que las maravillosas bestias tengan suficiente para comer!",
  ui_story_5037_50371301_75_dialog_content = "Haría cualquier cosa por esos tipos.",
  ui_story_5037_50371301_76_dialog_content = "¡Y es por eso que con mucho gusto te prestaría mis aprendices, para cualquier cosa que puedas necesitar! Siempre y cuando pagues, por supuesto.",
  ui_story_5037_50371301_77_dialog_content = "¡Olvídalo Vic! ¡No les hagas la vida aún más difícil a esos dos!",
  ui_story_5037_50371301_78_dialog_content = "Lo juro, a veces parece que te preocupas más por tu Little Furball que por Fia y Shira...",
  ui_story_5037_50371301_79_dialog_content = "¡No podrías estar más equivocado! ¡Las palabras no pueden describir lo orgulloso que estoy de mis queridos aprendices!",
  ui_story_5037_50371301_80_dialog_content = "No solo les he transmitido toda mi experiencia en extrozoología... ¡También saben cómo ganar dinero y sobrevivir en el mundo!",
  ui_story_5037_50371301_81_dialog_content = "Además de eso, ¡ninguno de los dos tiene miedo de luchar contra los Eclipsites!",
  ui_story_5037_50371301_82_dialog_content = "Algún día, podré confiarles todos mis proyectos de investigación sobre las maravillosas bestias de Astra...",
  ui_story_5037_50371301_83_dialog_content = "¿Qué harás entonces? ¿Tomar aún más siestas?",
  ui_story_5037_50371301_84_dialog_content = "¡No es una mala idea! ¡Me aseguraré de considerarlo!",
  ui_story_5037_50371301_85_dialog_content = "Pero antes de eso, todavía tengo mucho trabajo importante que hacer.",
  ui_story_5037_50371301_86_dialog_content = "Creo que hay otros continentes como Astra en nuestro mundo.",
  ui_story_5037_50371301_87_dialog_content = "¡Quiero verlos a todos y aprender todo lo que hay que saber sobre las maravillosas bestias que habitan sus tierras!",
  ui_story_5037_50371301_88_dialog_content = "No tenía idea de que tuvieras un sueño tan grandioso...",
  ui_story_5037_50371301_89_dialog_content = "¡Pero por supuesto! Después de todo, yo soy...",
  ui_story_5037_50371301_90_dialog_content = "¡¡¡Ay!!!",
  ui_story_5037_50371301_91_dialog_content = "¿Cuál es la gran idea, Kyllo?",
  ui_story_5037_50371301_92_dialog_content = "Parece que Kyllo te estaba recordando que tu descanso terminó, Vic. ¡Vuelta al entrenamiento!",
  ui_story_5037_50371301_93_dialog_content = "Fia realmente tuvo una mala influencia sobre ti, ¿no Kyllo? ¡Eres incluso más duro que ella ahora!",
  ui_story_5037_50371301_94_dialog_content = "Pero desde PlayerName está a cargo de mi entrenamiento hoy, tal vez pueda extender mi tiempo de descanso unos minutos más, ¿qué dices?",
  ui_story_5037_50371301_95_dialog_content = "Mmm...",
  ui_story_5037_50371301_96_dialog_content = "¡Vamos! ¡Hasta dejaré que acaricies a Little Furball mientras tanto!",
  ui_story_5037_50371301_97_dialog_content = "Bueno, cuando lo pones de esa manera, supongo que podemos...",
  ui_story_5037_50371301_98_option_content = "¡Entrena el doble de duro!",
  ui_story_5037_50371301_99_option_content = "¡Entrena diez veces más duro!",
  ui_story_5037_50371301_100_dialog_content = "Desarrollé un programa de capacitación para ayudar Goldie romper una meseta potencial.",
  ui_story_5037_50371301_101_dialog_content = "Nunca lo puse en práctica porque parecía demasiado difícil, ¡pero primero lo probaré contigo!",
  ui_story_5037_50371301_102_dialog_content = "¡¿Qué?!",
  ui_story_5037_50371301_103_dialog_content = "No te preocupes, es solo un rato. De esa manera, puedo hacer algunos ajustes antes de mostrárselo a Goldie.",
  ui_story_5037_50371301_104_dialog_content = "Naturalmente, esto también debería ayudarte a mejorar.",
  ui_story_5037_50371301_105_dialog_content = "No podemos dejar que todo el arduo trabajo de Fia sea en vano, ¡así que vamos a entrenar con todo nuestro corazón! ¿Estás listo, Vic?",
  ui_story_5037_50371301_106_dialog_content = "¡¡¡Noooo-!!!",
  ui_story_5037_50371401_1_dialog_content = "Equipo PlayerName¡Reunión de emergencia de 's, toma una! Tres, dos, uno... ¡Acción!",
  ui_story_5037_50371401_2_dialog_content = "D-¿Realmente tenemos que filmar esto también?",
  ui_story_5037_50371401_3_dialog_content = "¡Eh! ¡Un gran director nunca deja que se desperdicie una valiosa oportunidad!",
  ui_story_5037_50371401_4_dialog_content = "Si tú lo dices...",
  ui_story_5037_50371401_5_dialog_content = "Entonces, comencemos nuestro primer Taller intensivo para productores.",
  ui_story_5037_50371401_6_dialog_content = "...",
  ui_story_5037_50371401_7_dialog_content = "(Hay libros esparcidos por toda la oficina...)",
  ui_story_5037_50371401_8_dialog_content = "(¿Vice y Carleen realmente trajeron todo esto para el taller?)",
  ui_story_5037_50371401_9_dialog_content = "(Se ven muy serios... Tengo un mal presentimiento sobre esto...)",
  ui_story_5037_50371401_10_dialog_content = "Um, ¿por qué ustedes dos se ven tan serios...?",
  ui_story_5037_50371401_11_dialog_content = "Porque es serio, PlayerName. Esto afectará si puedes o no convertirte en un productor exitoso.",
  ui_story_5037_50371401_12_dialog_content = "Por cierto. Cuando se trata de su éxito, no podemos darnos el lujo de ser descuidados.",
  ui_story_5037_50371401_13_dialog_content = "Gracias por la preocupación, pero yo soy el responsable de eso, no ustedes dos...",
  ui_story_5037_50371401_14_dialog_content = "¿De qué estás hablando? Somos socios, ¿no? ¡Siempre estaremos aquí para respaldarte!",
  ui_story_5037_50371401_15_dialog_content = "Y para ayudarte a entender tu nueva profesión tanto como sea posible, Vice y yo hicimos nuestra propia parte de la investigación.",
  ui_story_5037_50371401_16_dialog_content = "¡Así es! ¡Todo lo que podrías querer aprender, desde ser un ídolo hasta ser un productor, está en estos libros!",
  ui_story_5037_50371401_17_dialog_content = "¡A partir de hoy, este será el lugar donde se llevará a cabo nuestro Taller intensivo para productores!",
  ui_story_5037_50371401_18_dialog_content = "Espera un minuto... ¡¿Todo esto son notas y recortes de artículos?!",
  ui_story_5037_50371401_19_dialog_content = "¡Sí! Carleen fue a la biblioteca y tomó notas en cada libro relacionado con los regímenes de entrenamiento para cantantes y bailarines.",
  ui_story_5037_50371401_20_dialog_content = "Mientras tanto, compré una copia de todos los periódicos impresos en los últimos años y recorté todo lo que tiene que ver con ídolos y productores.",
  ui_story_5037_50371401_21_dialog_content = "Eso es aterrador impresionante...",
  ui_story_5037_50371401_22_dialog_content = "Debe haber tomado días leer todos esos libros y escribir estas notas...",
  ui_story_5037_50371401_23_dialog_content = "Bueno, tuve algo de ayuda de Chloe y Keating durante mi investigación.",
  ui_story_5037_50371401_24_dialog_content = "Ambos saben mucho más de música que yo, por lo que escribieron gran parte de estas notas.",
  ui_story_5037_50371401_25_dialog_content = "Y tuve algo de ayuda de Brandy!",
  ui_story_5037_50371401_26_dialog_content = "Como reportera profesional, ¡está muy familiarizada con todo tipo de noticias y eventos!",
  ui_story_5037_50371401_27_dialog_content = "Sí, todo esto no hubiera sido posible sin la ayuda de todos.",
  ui_story_5037_50371401_28_dialog_content = "En serio...",
  ui_story_5037_50371401_29_dialog_content = "¡Parece que no puedo darme el lujo de holgazanear! ¡Todos esperan mucho de mí!",
  ui_story_5037_50371401_30_dialog_content = "Entonces empecemos.",
  ui_story_5037_50371401_31_dialog_content = "Nuestro próximo orden del día es decidir un plan de entrenamiento para usted, PlayerName!",
  ui_story_5037_50371401_32_dialog_content = "¿Un plan de entrenamiento?",
  ui_story_5037_50371401_33_dialog_content = "Sí. Desarrollamos dos planes de entrenamiento diferentes para ti. Te dejaremos decidir cuál es más adecuado.",
  ui_story_5037_50371401_34_dialog_content = "Este se llama \"Productores: de principiantes a expertos\".",
  ui_story_5037_50371401_35_dialog_content = "¡¡Es tan grueso!!",
  ui_story_5037_50371401_36_dialog_content = "Contiene conocimientos que varían en complejidad desde el nivel rudimentario hasta el nivel profesional. Sin embargo, el material es denso y requerirá más tiempo para estudiar.",
  ui_story_5037_50371401_37_dialog_content = "Y el otro...?",
  ui_story_5037_50371401_38_dialog_content = "Este se llama \"Técnicas Avanzadas de Productor\". Incluye diferentes técnicas de gestión del tiempo utilizadas por eruditos famosos a lo largo de los siglos.",
  ui_story_5037_50371401_39_dialog_content = "Sin embargo, este plan requiere un conocimiento básico de la industria para entenderlo lo suficientemente bien como para usarlo.",
  ui_story_5037_50371401_40_dialog_content = "Avanzar, PlayerName! ¡Elige el plan que creas que más te conviene!",
  ui_story_5037_50371401_41_dialog_content = "El plan que más me conviene...",
  ui_story_5037_50371401_42_dialog_content = "Bueno, todavía soy bastante inexperto como productor, así que creo que este servirá—",
  ui_story_5037_50371401_43_option_content = "\"Productores: de principiantes a expertos\"",
  ui_story_5037_50371401_44_dialog_content = "Si quiero comenzar con los fundamentos, ¡este plan debería ser mi apuesta más segura!",
  ui_story_5037_50371401_45_dialog_content = "Estoy de acuerdo.",
  ui_story_5037_50371401_46_dialog_content = "¡Entonces está resuelto! ¡A partir de hoy, usarás esto para ayudarte a aprender a ser un productor profesional!",
  ui_story_5037_50371401_47_dialog_content = "¡Haré lo mejor que pueda!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371401_49_dialog_content = "Las principales responsabilidades de un productor... Seguimiento del progreso, desarrollo de cronogramas...",
  ui_story_5037_50371401_50_dialog_content = "¿Qué otra cosa? Uf, creo que ya se me olvidó...",
  ui_story_5037_50371401_51_dialog_content = "¿Por qué no te tomas un descanso?",
  ui_story_5037_50371401_52_dialog_content = "Ya has memorizado mucho. Su próximo paso es tratar de poner esos conceptos en práctica.",
  ui_story_5037_50371401_53_option_content = "\"Técnicas Avanzadas de Productor\"",
  ui_story_5037_50371401_54_dialog_content = "Ya decidí desafiarme a mí mismo haciendo esto, ¡así que comencemos con las cosas difíciles!",
  ui_story_5037_50371401_55_dialog_content = "¡¿Está seguro?!",
  ui_story_5037_50371401_56_dialog_content = "Si así es como desea proceder, haremos todo lo posible para ayudarlo.",
  ui_story_5037_50371401_57_dialog_content = "¡Debería estar bien!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371401_59_dialog_content = "¡Es muy dificil!",
  ui_story_5037_50371401_60_dialog_content = "Estoy de acuerdo, esto parece un poco difícil...",
  ui_story_5037_50371401_61_dialog_content = "Sentí lo mismo cuando estaba diseñando este plan... Hay muchos temas complejos involucrados, todos los cuales están interconectados de una forma u otra.",
  ui_story_5037_50371401_62_dialog_content = "Parece que tendré que hacerlo paso a paso si quiero aprender las cosas bien.",
  ui_story_5037_50371401_63_dialog_content = "Aunque se está haciendo tarde. Detengámonos aquí por hoy.",
  ui_story_5037_50371401_64_dialog_content = "Buen trabajo, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "Bien hecho.",
  ui_story_5037_50371401_66_dialog_content = "¡Debería ser yo quien diga eso! Estoy seguro de que no fue fácil reunir todos estos materiales...",
  ui_story_5037_50371401_67_dialog_content = "Somos tan buenos amigos que no hay necesidad de formalidades.",
  ui_story_5037_50371401_68_dialog_content = "Vuelve y descansa un poco, ¿de acuerdo?",
  ui_story_5037_50371401_69_dialog_content = "¡Sí, lo mismo para ustedes dos!",
  ui_story_5037_50371401_70_dialog_content = "Todavía tenemos algunos asuntos que atender antes de regresar, así que no es necesario que nos espere.",
  ui_story_5037_50371401_71_dialog_content = "¿Eh? ¿A dónde vas?",
  ui_story_5037_50371401_72_dialog_content = "Preparamos algunas entrevistas con algunos cantantes aurorianos de la ciudad. Queremos aprender sobre técnicas de canto de ellos.",
  ui_story_5037_50371401_73_dialog_content = "A pesar de que sus estilos y antecedentes son diferentes, aún deben tener algunos consejos que ofrecer.",
  ui_story_5037_50371401_74_dialog_content = "Si podemos precisar sus técnicas y presentárselas a Goldie, seguro que le será de gran utilidad.",
  ui_story_5037_50371401_75_dialog_content = "¡Pero ya has hecho tanto para ayudarme!",
  ui_story_5037_50371401_76_dialog_content = "Siento que si alguien necesita descansar, son ustedes dos...",
  ui_story_5037_50371401_77_dialog_content = "¡No te preocupes por nosotros! ¡Todavía me siento acelerado y listo para empezar!",
  ui_story_5037_50371401_78_dialog_content = "Esta es una experiencia nueva y emocionante para ambos.",
  ui_story_5037_50371401_79_dialog_content = "Quizás es por eso que no nos sentimos cansados, a pesar de todo el trabajo que venimos haciendo.",
  ui_story_5037_50371401_80_dialog_content = "¿No te sientes así a veces, PlayerName?",
  ui_story_5037_50371401_81_dialog_content = "lo hago, si...",
  ui_story_5037_50371401_82_dialog_content = "Desde que comencé a trabajar como productor, no creo que haya pasado un día sin trabajar desde el amanecer hasta el anochecer.",
  ui_story_5037_50371401_83_dialog_content = "Pero debido a todos los nuevos desafíos que enfrento todos los días, ¡no me siento tan cansado como debería!",
  ui_story_5037_50371401_84_dialog_content = "Se siente como cuando salí del subsuelo y los conocí.",
  ui_story_5037_50371401_85_dialog_content = "Aunque los eclipses nos persiguieron durante días, nunca me sentí cansado o desesperanzado.",
  ui_story_5037_50371401_86_dialog_content = "¡Ese es el tipo de emoción que trae una nueva aventura!",
  ui_story_5037_50371401_87_dialog_content = "¡Sí!",
  ui_story_5037_50371401_88_dialog_content = "¡Pero aún así, no puedo quedarme de brazos cruzados mientras ustedes dos están tan ocupados!",
  ui_story_5037_50371401_89_dialog_content = "¿Ah?",
  ui_story_5037_50371401_90_dialog_content = "¿Porqué crees?",
  ui_story_5037_50371401_91_dialog_content = "Porque estamos todos juntos en esto, así ha sido siempre.",
  ui_story_5037_50371401_92_dialog_content = "No importa cuán largo sea el viaje o cuán peligrosa sea la aventura, los tres siempre nos hemos mantenido unidos.",
  ui_story_5037_50371401_93_dialog_content = "¡Así que por eso voy contigo!",
  ui_story_5037_50371401_94_dialog_content = "Pero-",
  ui_story_5037_50371401_95_dialog_content = "¡No te preocupes por mí! Todos haremos nuestro mejor esfuerzo, como siempre lo hacemos.",
  ui_story_5037_50371401_96_dialog_content = "¡Por supuesto! ¡Como siempre lo hacemos!",
  ui_story_5037_50371501_1_dialog_content = "Equipo PlayerName¡Reunión de última hora! Tres, dos, uno... ¡Acción!",
  ui_story_5037_50371501_2_dialog_content = "¡Lo siento, llego tarde!",
  ui_story_5037_50371501_3_dialog_content = "Está bien. ¡Al menos lo lograste!",
  ui_story_5037_50371501_4_dialog_content = "¿Eh? ¿Dónde está Goldie?",
  ui_story_5037_50371501_5_dialog_content = "Fue a hablar con Lady Sheol sobre sus próximos planes, por lo que no volverá por un tiempo.",
  ui_story_5037_50371501_6_dialog_content = "¿De verdad? Qué vergüenza...",
  ui_story_5037_50371501_7_dialog_content = "¿Porqué crees?",
  ui_story_5037_50371501_8_dialog_content = "Queríamos felicitarlos a ambos por organizar un exitoso concierto de debut.",
  ui_story_5037_50371501_9_dialog_content = "Preparamos algunas bebidas y golosinas para cuando tú y Goldie devuelto",
  ui_story_5037_50371501_10_dialog_content = "¡Wow gracias! Y no te preocupes, me aseguraré de traer algo para Goldie.",
  ui_story_5037_50371501_11_dialog_content = "Solo desearía que ella pudiera estar aquí para disfrutarlos ahora mismo...",
  ui_story_5037_50371501_12_dialog_content = "Pasé mucho tiempo horneando estas galletas, así que quería que todos las probaran mientras estaban frescas.",
  ui_story_5037_50371501_13_dialog_content = "También tomó muchos intentos descubrir cómo hornearlos sin quemarlos.",
  ui_story_5037_50371501_14_dialog_content = "Parece que realmente pusiste tu corazón en esto, Vice...",
  ui_story_5037_50371501_15_dialog_content = "(Estas galletas deberían saber bien si se esforzó tanto en ellas... ¿verdad?)",
  ui_story_5037_50371501_16_dialog_content = "El tiempo vuela, ¿no? No puedo creer que el concierto debut ya haya terminado.",
  ui_story_5037_50371501_17_dialog_content = "Sí... ¡También hemos realizado muchos Talleres intensivos para productores!",
  ui_story_5037_50371501_18_dialog_content = "Cuando empezamos a ayudar PlayerName Conviértete en productor, todos estábamos muy ocupados...",
  ui_story_5037_50371501_19_dialog_content = "¡Pero todos nuestros esfuerzos están comenzando a dar sus frutos! PlayerName logró ayudar a Goldie a presentar un espectacular concierto de debut.",
  ui_story_5037_50371501_20_dialog_content = "Se ha convertido en un productor bastante confiable, de hecho.",
  ui_story_5037_50371501_21_dialog_content = "¡En serio! ¡Realmente has mostrado un gran progreso!",
  ui_story_5037_50371501_22_dialog_content = "Jejeje... ¡Ustedes dos me van a hacer sonrojar! ¡Soy yo quien debería estar agradeciéndote!",
  ui_story_5037_50371501_23_dialog_content = "¡Felicidades!",
  ui_story_5037_50371501_24_dialog_content = "Felicitaciones, PlayerName.",
  ui_story_5037_50371501_25_dialog_content = "¡Gracias!",
  ui_story_5037_50371501_26_dialog_content = "¡Bien, ahora comencemos esta fiesta!",
  ui_story_5037_50371501_27_dialog_content = "¡Un poco más y el té se enfriará!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5037_50371501_29_dialog_content = "... ¿Alguno de ustedes escuchó un ruido extraño en este momento?",
  ui_story_5037_50371501_30_dialog_content = "¿Mmm? No, no lo creo?",
  ui_story_5037_50371501_31_dialog_content = "<color=#828282>susurro, susurro——</color>",
  ui_story_5037_50371501_32_dialog_content = "Ahí está de nuevo. Parece que viene de cerca de los instrumentos musicales.",
  ui_story_5037_50371501_33_dialog_content = "¿Quizás fue solo el viento?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>susurro, susurro——</color>",
  ui_story_5037_50371501_35_dialog_content = "...",
  ui_story_5037_50371501_36_dialog_content = "Creo que algo se esconde detrás de la batería...",
  ui_story_5037_50371501_37_dialog_content = "¿Podría ser... un eclipse?",
  ui_story_5037_50371501_38_dialog_content = "Iré a echar un vistazo más de cerca.",
  ui_story_5037_50371501_39_dialog_content = "Flor de Hielo—",
  ui_story_5037_50371501_40_dialog_content = "¡Lo! ¡Lo, lo, lo!",
  ui_story_5037_50371501_41_dialog_content = "Que...? ¡Es Kyllo!",
  ui_story_5037_50371501_42_dialog_content = "Pero, ¿qué hace Kyllo aquí? ¿Dónde está Fía?",
  ui_story_5037_50371501_43_dialog_content = "Lo... (Traducción: Fia me envió a una misión ultrasecreta para espiar PlayerName y los otros...)",
  ui_story_5037_50371501_44_dialog_content = "¡Lo, lo! (Traducción: ¡Pero no esperaba encontrar tanta gente aquí a la vez!)",
  ui_story_5037_50371501_45_dialog_content = "Lo... ¡Lo! (Traducción: Parece que mi tapadera está descubierta... ¡Tengo que encontrar una manera de salir de aquí, rápido!)",
  ui_story_5037_50371501_46_dialog_content = "No estarías espiándonos... ¿o sí?",
  ui_story_5037_50371501_47_dialog_content = "¡Lo, lo, lo!",
  ui_story_5037_50371501_48_dialog_content = "Creo que está tratando de negarlo.",
  ui_story_5037_50371501_49_dialog_content = "Tiene sentido... Dado el comportamiento habitual de Kyllo, supongo que se perdió mientras buscaba algo para comer.",
  ui_story_5037_50371501_50_dialog_content = "¿Tal vez te escabulliste aquí porque tampoco podías soportar más el entrenamiento de Fia, Kyllo?",
  ui_story_5037_50371501_51_dialog_content = "¡Lo!",
  ui_story_5037_50371501_52_dialog_content = "Estoy bastante seguro de que es un sí.",
  ui_story_5037_50371501_53_dialog_content = "Pobrecito. Mantener a Vic en línea durante su entrenamiento todos los días debe ser agotador...",
  ui_story_5037_50371501_54_dialog_content = "Lo...",
  ui_story_5037_50371501_55_dialog_content = "Puede descansar aquí por un tiempo. Tenemos muchos bocadillos para compartir con él.",
  ui_story_5037_50371501_56_dialog_content = "¡Si estoy de acuerdo! Se lo devolveré a Fia una vez que hayamos terminado.",
  ui_story_5037_50371501_57_dialog_content = "¡Lo! ¡Lo! (Traducción: Genial, ¡parece que no se dieron cuenta de la verdadera razón por la que estoy aquí!)",
  ui_story_5037_50371501_58_dialog_content = "¡Lo! (Traducción: ¿Me pregunto de qué tipo de bocadillos estaban hablando?)",
  ui_story_5037_50371501_59_dialog_content = "Fia mencionó que a Kyllo le encantaba comer galletas de animales, ¿no?",
  ui_story_5037_50371501_60_dialog_content = "No sé si mis galletas saben tan bien como las galletas saladas que te gustan, pero...",
  ui_story_5037_50371501_61_dialog_content = "(Uh-oh... ¡Recuerdo este sentimiento!)",
  ui_story_5037_50371501_62_dialog_content = "(¡Es el mismo de antes!)",
  ui_story_5037_50371501_63_dialog_content = "¡Lo! (Traducción: ¡E-Espera un segundo! ¿Es esto comestible?)",
  ui_story_5037_50371501_64_dialog_content = "¡Aquí, Kyllo! ¡Prueba una de mis galletas recién horneadas!",
  ui_story_5037_50371501_65_dialog_content = "Ya se que no se ven tan bonitos como los de las panaderías de Lumopolis, pero la receta es exactamente igual!",
  ui_story_5037_50371501_66_dialog_content = "¡Lo! ¡Lo! (Traducción: ¡A-Aléjate de mí!)",
  ui_story_5037_50371501_67_dialog_content = "Di, ahhh—",
  ui_story_5037_50371501_68_dialog_content = "Lo!!!",
  ui_story_5037_50371501_69_dialog_content = "¡Kyllo se está escapando!",
  ui_story_5037_50371501_70_dialog_content = "¡Está corriendo hacia nuestra pila de libros!",
  ui_story_5037_50371501_71_dialog_content = "¡Agárralo antes de que se convierta en un desastre pegajoso!",
  ui_story_5037_50371501_72_dialog_content = "¡Ven aquí, Kyllo!",
  ui_story_5037_50371501_73_dialog_content = "Lo!!!",
  ui_story_5037_50371501_74_dialog_content = "(¡Mierda! ¡Kyllo está tratando de zambullirse en la pila de libros!)",
  ui_story_5037_50371501_75_option_content = "Proteger los libros profesionales",
  ui_story_5037_50371501_76_option_content = "proteger las revistas",
  ui_story_5037_50371501_77_dialog_content = "<color=#828282>¡Pam!</color>",
  ui_story_5037_50371501_78_dialog_content = "¡Uf—!",
  ui_story_5037_50371501_79_dialog_content = "<size=45>¡¡¡Ay!!!</size>",
  ui_story_5037_50371501_80_dialog_content = "¡¿PlayerName?!",
  ui_story_5037_50371501_81_dialog_content = "Estoy bien... Eso solo me dolió un poco, eso es todo...",
  ui_story_5037_50371501_82_dialog_content = "Lo...",
  ui_story_5037_50371501_83_dialog_content = "¡Lo, lo, lo!",
  ui_story_5037_50371501_84_dialog_content = "¡Corre tan rápido!",
  ui_story_5037_50371501_85_dialog_content = "¿Están bien los libros?",
  ui_story_5037_50371501_86_dialog_content = "*tosiendo* Sí... Bueno, una parte de ellos, de todos modos...",
  ui_story_5037_50371501_87_dialog_content = "También logré conservar algunas de nuestras notas y recortes.",
  ui_story_5037_50371501_88_dialog_content = "El resto de ellos parecen estar completamente empapados...",
  ui_story_5037_50371501_89_dialog_content = "Bueno, no hay tiempo que perder. Necesitamos quitar todos los libros mojados primero.",
  ui_story_5037_50371501_90_dialog_content = "Uno dos...",
  ui_story_5037_50371501_91_dialog_content = "Creo que todavía podemos leerlos si logramos secarlos primero.",
  ui_story_5037_50371501_92_dialog_content = "Estos, por otro lado... La tinta está completamente manchada, así que no podemos hacer nada para salvarlos.",
  ui_story_5037_50371501_93_dialog_content = "¡Creo que hay algunos libros allí que tomamos prestados de otras personas!",
  ui_story_5037_50371501_94_dialog_content = "No se puede evitar. Tenemos que solucionarlos, devolverlos a sus dueños y ofrecer nuestras disculpas, así como una compensación.",
  ui_story_5037_50371501_95_dialog_content = "Supongo que realmente no tenemos otra opción, ¿eh?",
  ui_story_5037_50371501_96_dialog_content = "Aunque no sé si tengo suficiente Nightium para cubrir los daños...",
  ui_story_5037_50371501_97_dialog_content = "Puedo participar también.",
  ui_story_5037_50371501_98_dialog_content = "Yo también. Después de todo, no pude detener a Kyllo, así que también tengo parte de culpa.",
  ui_story_5037_50371501_99_dialog_content = "No te preocupes, PlayerName! ¡No te dejaremos secar!",
  ui_story_5037_50371501_100_dialog_content = "Gracias Vice. Gracias, Carleen.",
  ui_story_5037_50371501_101_dialog_content = "Eso solo deja una última cosa por hacer.",
  ui_story_5037_50371501_102_dialog_content = "Necesitamos encontrar Fia, y asegúrate de disciplinar a Kyllo adecuadamente.",
  ui_story_5037_50371601_1_dialog_content = "Equipo PlayerNamereunión final de! Tres, dos, uno... ¡Acción!",
  ui_story_5037_50371601_2_dialog_content = "Última reunión, ¿eh? Wow, seguro que el tiempo vuela...",
  ui_story_5037_50371601_3_dialog_content = "¿Yo se, verdad? ¡Llegará el momento del concierto de graduación en unos pocos días!",
  ui_story_5037_50371601_4_dialog_content = "Parece que fue ayer cuando trajimos todos esos libros aquí para prepararnos para nuestro primer Taller intensivo para productores.",
  ui_story_5037_50371601_5_dialog_content = "Entonces, ¿cuál es el plan para hoy?",
  ui_story_5037_50371601_6_dialog_content = "Solo tenemos una tarea importante para hoy... ¡y es limpiar el lugar!",
  ui_story_5037_50371601_7_dialog_content = "Después de terminar cada parte de tu plan de entrenamiento, te has convertido en un productor talentoso y respetable. PlayerName!",
  ui_story_5037_50371601_8_dialog_content = "¡Lo que significa que nuestro Taller intensivo para productores ha llegado oficialmente a su fin!",
  ui_story_5037_50371601_9_dialog_content = "De hecho, debemos reunir todos nuestros libros y materiales y devolverlos a sus lugares apropiados hoy.",
  ui_story_5037_50371601_10_dialog_content = "De esa manera, también podemos devolver todos los materiales que tomamos prestados de otros para el taller.",
  ui_story_5037_50371601_11_dialog_content = "Ya veo. ¡Yo también ayudaré!",
  ui_story_5037_50371601_12_dialog_content = "¡Arreglemos todo lo más rápido que podamos!",
  ui_story_5037_50371601_13_dialog_content = "¡Sí!",
  ui_story_5037_50371601_14_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371601_15_dialog_content = "¿Dónde debo poner esta copia de \"Formando buenos hábitos: una guía para principiantes\"?",
  ui_story_5037_50371601_16_dialog_content = "Aquí, dámelo.",
  ui_story_5037_50371601_17_dialog_content = "La oficial Vivian tuvo la amabilidad de prestarlo. ¡Dijo que sería perfecto para tu entrenamiento!",
  ui_story_5037_50371601_18_dialog_content = "Ella misma aprendió una mejor gestión del tiempo después de leerlo.",
  ui_story_5037_50371601_19_dialog_content = "Ella tiene razón, ¡había toneladas de información útil en él!",
  ui_story_5037_50371601_20_dialog_content = "PlayerName? ¿Podría pasarme esa copia de \"300 habilidades corales esenciales\" que tiene a su lado?",
  ui_story_5037_50371601_21_dialog_content = "Claro aquí tienes.",
  ui_story_5037_50371601_22_dialog_content = "Déjame adivinar... Keating nos prestó ese libro, ¿no?",
  ui_story_5037_50371601_23_dialog_content = "¿Cómo lo supiste?",
  ui_story_5037_50371601_24_dialog_content = "Porque aunque la portada se ve perfectamente limpia... Hay todo tipo de garabatos y dibujos en el número de cada página.",
  ui_story_5037_50371601_25_dialog_content = "¡Incluso hay un dibujo crudo de mí en una de las páginas, donde dibujaron estos círculos grandes y oscuros alrededor de mis ojos!",
  ui_story_5037_50371601_26_dialog_content = "... No.",
  ui_story_5037_50371601_27_dialog_content = "Eso suena como algo que harían, sí.",
  ui_story_5037_50371601_28_dialog_content = "Si realmente te molesta, haré que borren todos sus dibujos en este libro.",
  ui_story_5037_50371601_29_dialog_content = "Eso no es realmente necesario...",
  ui_story_5037_50371601_30_dialog_content = "Si les obligas a hacer eso, estoy seguro de que encontrarán una forma aún peor de burlarse de mí.",
  ui_story_5037_50371601_31_dialog_content = "Solo déjalo ser.",
  ui_story_5037_50371601_32_dialog_content = "Esos niños realmente saben cómo poner nerviosos a todos.",
  ui_story_5037_50371601_33_dialog_content = "Parece que casi hemos terminado aquí, ¿verdad?",
  ui_story_5037_50371601_34_dialog_content = "¡Sí! ¡Todo está en orden!",
  ui_story_5037_50371601_35_dialog_content = "Además de todos los libros que usamos, también está esta enorme pila de notas.",
  ui_story_5037_50371601_36_dialog_content = "Acumulamos todas estas notas durante los últimos días.",
  ui_story_5037_50371601_37_dialog_content = "¡Así es, cada página cubierta con notas es un testimonio de todo nuestro arduo trabajo!",
  ui_story_5037_50371601_38_dialog_content = "Realmente es una gran pila, ¿eh?",
  ui_story_5037_50371601_39_dialog_content = "No se sentía así mientras los estábamos tomando...",
  ui_story_5037_50371601_40_dialog_content = "¡pero no puedo creer que hayamos tomado tantas notas!",
  ui_story_5037_50371601_41_dialog_content = "Este es el fruto de vuestro conocimiento adquirido.",
  ui_story_5037_50371601_42_dialog_content = "Debo decir que ha pasado mucho tiempo desde que escribí tantas notas... ¡Se parecía mucho a nuestro tiempo en la academia!",
  ui_story_5037_50371601_43_dialog_content = "Ir a clase, tomar apuntes, almorzar juntos... Eran días tan tranquilos, ¿no? Carleen?",
  ui_story_5037_50371601_44_dialog_content = "Excepto cuando se acercaban los exámenes, por supuesto...",
  ui_story_5037_50371601_45_dialog_content = "Vida de estudiante, ¿eh? Es bastante difícil para mí imaginarlo.",
  ui_story_5037_50371601_46_dialog_content = "Después de todo, nunca antes había ido a la escuela, así que no sé cómo es.",
  ui_story_5037_50371601_47_dialog_content = "Soroz siempre ha sido tu maestro, PlayerName?",
  ui_story_5037_50371601_48_dialog_content = "En ese caso, sería realmente difícil imaginar estudiar con otros.",
  ui_story_5037_50371601_49_dialog_content = "Es muy parecido a nuestras aventuras juntos. Menos los eclipses, por supuesto.",
  ui_story_5037_50371601_50_dialog_content = "deberíamos visitar Dawn Academia cuando tengamos la oportunidad.",
  ui_story_5037_50371601_51_dialog_content = "Puedes experimentar la vida como estudiante allí, al igual que experimentaste la vida como productor aquí.",
  ui_story_5037_50371601_52_dialog_content = "Claro, pero... tal vez pueda saltarme los exámenes.",
  ui_story_5037_50371601_53_dialog_content = "Hemos estado tan ocupados últimamente que estoy empezando a sentirme un poco agotado...",
  ui_story_5037_50371601_54_dialog_content = "No quiero pensar más en concursos o exámenes. ¡En este momento, lo que más deseo es descansar decentemente!",
  ui_story_5037_50371601_55_option_content = "¡Pero todavía no puedo descansar!",
  ui_story_5037_50371601_56_dialog_content = "Todavía tengo mucho trabajo por hacer para el concierto final.",
  ui_story_5037_50371601_57_dialog_content = "¡Si empiezo a tomármelo con calma ahora, no podré terminar lo que empecé!",
  ui_story_5037_50371601_58_dialog_content = "¡Siempre afrontas las nuevas experiencias con tanta ilusión!",
  ui_story_5037_50371601_59_dialog_content = "Bueno, sí... Después de todo, pasé 17 años bajo tierra...",
  ui_story_5037_50371601_60_dialog_content = "Entonces deseas experimentar todo por ti mismo, ¿sí?",
  ui_story_5037_50371601_61_dialog_content = "¡Así es!",
  ui_story_5037_50371601_62_option_content = "Solo quiero acostarme ahora mismo...",
  ui_story_5037_50371601_63_dialog_content = "Todo se sentía tan nuevo y emocionante cuando me convertí en productor por primera vez, pero poco a poco estoy empezando a acostumbrarme.",
  ui_story_5037_50371601_64_dialog_content = "Haciendo exactamente el mismo trabajo, día tras día... Me he familiarizado tanto con el trabajo, pero no puedo evitar sentirme un poco aburrido a veces...",
  ui_story_5037_50371601_65_dialog_content = "Sé exactamente cómo te sientes...",
  ui_story_5037_50371601_66_dialog_content = "Incluso las cosas más emocionantes se vuelven monótonas después de un tiempo.",
  ui_story_5037_50371601_67_dialog_content = "Es por eso que siempre debemos encontrar nuevas formas de desafiarnos a nosotros mismos.",
  ui_story_5037_50371601_68_dialog_content = "Aun así, ¡ha sido una experiencia valiosa!",
  ui_story_5037_50371601_69_dialog_content = "tengo que ayudar Goldie dar conciertos, y pude estudiar junto a ustedes dos.",
  ui_story_5037_50371601_70_dialog_content = "¡No podría pedir una mejor manera de aprender y crecer como persona!",
  ui_story_5037_50371601_71_dialog_content = "Probablemente puedas hacerte un nombre si te quedas aquí y sigues siendo productor.",
  ui_story_5037_50371601_72_dialog_content = "¿Cuál te gusta más? ¿Ser productor o ser aventurero?",
  ui_story_5037_50371601_73_dialog_content = "¿Me estás tomando el pelo? ¡Mi respuesta debe ser clara como el día!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "¡Aventurarme con ustedes es lo que me hace más feliz!",
  ui_story_5037_50371701_1_dialog_content = "florina? ¡No te esperaba aquí! ¡Bienvenido Bienvenido!",
  ui_story_5037_50371701_2_dialog_content = "Si viniste a escuchar a Goldie cantar, me temo que tendré que decepcionarte. El concierto no es hasta dentro de unos días, y ella todavía está en medio del entrenamiento.",
  ui_story_5037_50371701_3_dialog_content = "No estoy aquí para asistir al concierto.",
  ui_story_5037_50371701_4_dialog_content = "¿Ah?",
  ui_story_5037_50371701_5_dialog_content = "Estoy aquí para prestar mi ayuda.",
  ui_story_5037_50371701_6_dialog_content = "¿Escuché que estás probando una nueva profesión? Un productor, creo que lo llamaban.",
  ui_story_5037_50371701_7_dialog_content = "Vine como tu amigo para ver cómo estabas.",
  ui_story_5037_50371701_8_dialog_content = "Dime, última Caelestite... ¿Hay algo que pueda hacer para ayudarte?",
  ui_story_5037_50371701_9_dialog_content = "No se me ocurre ninguna...",
  ui_story_5037_50371701_10_dialog_content = "Es eso así...",
  ui_story_5037_50371701_11_dialog_content = "(¿Eh? ¿Por qué Florine se ve tan decepcionada?)",
  ui_story_5037_50371701_12_dialog_content = "(¿Es porque no necesito su ayuda en este momento...?)",
  ui_story_5037_50371701_13_dialog_content = "¡E-Espera! ¡Hay algo con lo que me vendría bien una mano!",
  ui_story_5037_50371701_14_dialog_content = "¿Qué es?",
  ui_story_5037_50371701_15_dialog_content = "(¿Qué debo decirle?)",
  ui_story_5037_50371701_16_dialog_content = "(No quiero decepcionarla, pero tampoco quiero molestarla...)",
  ui_story_5037_50371701_17_dialog_content = "(Espera, ¿no dijo ella que solía ser presidenta del consejo estudiantil? En ese caso...)",
  ui_story_5037_50371701_18_option_content = "Pide ayuda con la música.",
  ui_story_5037_50371701_19_dialog_content = "Goldie está en el proceso de escribir una nueva canción, pero aún le falta acompañamiento. ¿Tal vez podrías ayudarla con eso?",
  ui_story_5037_50371701_20_dialog_content = "¿Acompañamiento musical? Lo siento, pero no estoy muy familiarizado con el tema...",
  ui_story_5037_50371701_21_dialog_content = "Aunque soy fanático de la ópera, así que sé solo un poco. ¡Lo haré lo mejor que pueda!",
  ui_story_5037_50371701_22_dialog_content = "¡Genial, muchas gracias!",
  ui_story_5037_50371701_23_option_content = "Pide ayuda para estudiar",
  ui_story_5037_50371701_24_dialog_content = "Goldie quiere que brinde algunas críticas constructivas sobre sus actuaciones, pero realmente no entiendo lo que está buscando.",
  ui_story_5037_50371701_25_dialog_content = "Necesito aprender tanto como sea posible sobre música lo más rápido posible, para poder darle la retroalimentación que necesita. ¿Alguna sugerencia?",
  ui_story_5037_50371701_26_dialog_content = "¡Has acudido a la persona adecuada! ¡Sé todo lo que hay que saber sobre el autoaprendizaje sistematizado, y estoy más que dispuesto a compartir mis conocimientos contigo!",
  ui_story_5037_50371701_27_dialog_content = "¡Excelente! ¡Cuento con usted!",
  ui_story_5037_50371701_28_dialog_content = "<color=#828282>Algún tiempo después</color>",
  ui_story_5037_50371701_29_dialog_content = "... ¡Ahí! He compartido todo lo que sé contigo.",
  ui_story_5037_50371701_30_dialog_content = "E-Espera, todavía no lo tengo todo abajo.",
  ui_story_5037_50371701_31_dialog_content = "Déjame revisar mis notas...",
  ui_story_5037_50371701_32_dialog_content = "Escribes notas muy detalladas, ¿no? Ese es un muy buen hábito.",
  ui_story_5037_50371701_33_dialog_content = "Siempre me olvido de las cosas, así que tomo muchas notas cuando estoy estudiando.",
  ui_story_5037_50371701_34_dialog_content = "Es por eso que llevo un diario. Nunca quiero olvidar todas las cosas importantes que suceden en mi vida, así que también las escribo.",
  ui_story_5037_50371701_35_dialog_content = "Supongo que para mí, un buen cuaderno vale más que mil recuerdos.",
  ui_story_5037_50371701_36_dialog_content = "Entonces te deseo la mejor de las suertes, última Caelestite.",
  ui_story_5037_50371701_37_dialog_content = "Su arduo trabajo y dedicación allanarán el camino hacia su éxito.",
  ui_story_5037_50371701_38_dialog_content = "¡Gracias por las palabras de aliento, Florine!",
  ui_story_5037_50371701_39_dialog_content = "Estas no son simplemente palabras de aliento.",
  ui_story_5037_50371701_40_dialog_content = "Ellos no están...?",
  ui_story_5037_50371701_41_dialog_content = "También son la culminación de mis propias experiencias como estudiante.",
  ui_story_5037_50371701_42_dialog_content = "El trabajo duro y la dedicación son los medios por los cuales una persona ordinaria puede lograr lo extraordinario... Así que nunca subestimes el valor del trabajo duro.",
  ui_story_5037_50371701_43_dialog_content = "¡Ya veo! ¡Y no lo haré!",
  ui_story_5037_50371701_44_dialog_content = "De todos modos, ¿cómo es que todavía estás usando todas esas cosas de la era antigua? ¿No quieres cambiarlo?",
  ui_story_5037_50371701_45_dialog_content = "No en realidad no. Es realmente ligero y cómodo. Y me recuerda a mis días de escuela.",
  ui_story_5037_50371701_46_dialog_content = "Usarlo significa que siempre recuerdo...",
  ui_story_5037_50371701_47_dialog_content = "ser más como un estudiante. Ser humilde y tener integridad. Esfuérzate siempre por mejorar y conviértete en una persona responsable.",
  ui_story_5037_50371701_48_dialog_content = "Podrías intentar ponértelo también, PlayerName. Estoy seguro de que sería inspirador.",
  ui_story_5037_50371701_49_dialog_content = "Umm... ¡Creo que voy a pasar!",
  ui_story_5037_50371701_50_dialog_content = "Me siento mucho más cómodo con mi propia ropa.",
  ui_story_5037_50371701_51_dialog_content = "Pues bien, como quieras.",
  ui_story_5037_50371701_52_dialog_content = "Estarás bien mientras siempre hagas tu mejor esfuerzo y no seas perezoso.",
  ui_story_5037_50371701_53_dialog_content = "¿Seguro que no eres demasiado dura contigo misma, Florine?",
  ui_story_5037_50371701_54_dialog_content = "¿Duro conmigo mismo? No me parece.",
  ui_story_5037_50371701_55_dialog_content = "Solo quiero poder ayudar a todos, como la señorita Hedy.",
  ui_story_5037_50371701_56_dialog_content = "Mientras pueda volverme tan confiable como ella, haré lo mejor que pueda, sin importar las dificultades que pueda enfrentar.",
  ui_story_5037_50371701_57_dialog_content = "Todavía tengo espacio para mejorar.",
  ui_story_5037_50371701_58_dialog_content = "¡Creo que eres increíble tal como eres ahora!",
  ui_story_5037_50371701_59_dialog_content = "Ser capaz de perseverar tan tenazmente todo el tiempo es realmente impresionante.",
  ui_story_5037_50371701_60_dialog_content = "Me encantaría ser más como tú.",
  ui_story_5037_50371701_61_dialog_content = "Bueno, trabajemos duro los dos para convertirnos en quienes queremos ser.",
  ui_story_5037_50371701_62_dialog_content = "¡Acuerdo!",
  ui_story_5037_50371701_63_dialog_content = "Ah, una cosa más. Recordar Goldie mantenerse hidratada y cuidarse.",
  ui_story_5037_50371701_64_dialog_content = "Cantar durante tanto tiempo genera una gran tensión en la garganta, por lo que es importante beber mucha agua para evitar la irritación.",
  ui_story_5037_50371701_65_dialog_content = "Bailar también es un ejercicio bastante vigoroso, por lo que la hidratación regular es fundamental.",
  ui_story_5037_50371701_66_dialog_content = "Sin preocupaciones. Me aseguraré de recordárselo.",
  ui_story_5037_50371701_67_dialog_content = "No olvides cuidarte tú también, última Caelestite.",
  ui_story_5037_50371701_68_dialog_content = "No importa cuán ocupado esté el trabajo, debe encontrar tiempo para cuidarse.",
  ui_story_5037_50371701_69_dialog_content = "Bien...",
  ui_story_5037_50371701_70_dialog_content = "Que el Dios de la Luz los bendiga y allane el camino de sus futuros esfuerzos.",
  ui_story_5037_50371701_71_dialog_content = "¡Sí!",
  ui_story_5037_50371801_1_dialog_content = "¡Ay, no me lo puedo perder! Cellulo, toma una buena foto de Goldie, PlayerName, ¡y yo!",
  ui_story_5037_50371801_2_dialog_content = "3... 2... 1... ¡Acción!",
  ui_story_5037_50371801_3_dialog_content = "¡Hola chicos! ¡Es tu intrépida directora, Lilica!",
  ui_story_5037_50371801_4_dialog_content = "Hoy asumo el papel de mentor en una colaboración con Goldie y su productor. PlayerName.",
  ui_story_5037_50371801_5_dialog_content = "¡Vamos a pasar por un entrenamiento de artes escénicas!",
  ui_story_5037_50371801_6_dialog_content = "Saluda a las personas que miran desde casa, Goldie, PlayerName!",
  ui_story_5037_50371801_7_dialog_content = "¡Hola a todos mis adorables fans!",
  ui_story_5037_50371801_8_dialog_content = "H-hola a todos...",
  ui_story_5037_50371801_9_dialog_content = "(Saber que mi actuación será grabada y vista por tanta gente es realmente desconcertante...)",
  ui_story_5037_50371801_10_dialog_content = "¡Preparé un juego especial para ayudarnos con el entrenamiento de hoy!",
  ui_story_5037_50371801_11_dialog_content = "¿Un juego? Genial, me encantan los juegos!",
  ui_story_5037_50371801_12_dialog_content = "¿Qué tipo de juego es?",
  ui_story_5037_50371801_13_dialog_content = "Se llama \"Charadas\".",
  ui_story_5037_50371801_14_dialog_content = "El vestuario, el maquillaje, las líneas y la expresión de uno afectan el resultado de la actuación de uno.",
  ui_story_5037_50371801_15_dialog_content = "¡Lo que un actor puede hacer es profundizar su comprensión del personaje tanto como sea posible y asegurarse de que su forma y sus líneas encajen!",
  ui_story_5037_50371801_16_dialog_content = "¡Suena bien!",
  ui_story_5037_50371801_17_dialog_content = "Observé a muchos de tus compañeros y escribí algunas líneas basadas en sus características individuales.",
  ui_story_5037_50371801_18_dialog_content = "Durante el juego, Goldie elegirá uno de ellos e imitará sus gestos.",
  ui_story_5037_50371801_19_dialog_content = "Entonces, PlayerName, adivinarás quién Goldie esta imitando!",
  ui_story_5037_50371801_20_dialog_content = "¡Su actuación será considerada un éxito si logras hacerlo bien!",
  ui_story_5037_50371801_21_dialog_content = "¡Suena divertido!",
  ui_story_5037_50371801_22_dialog_content = "¡Ya veo!",
  ui_story_5037_50371801_23_dialog_content = "Dado que Goldie es una recién llegada, lo haremos de opción múltiple. Solo tienes que elegir la respuesta correcta.",
  ui_story_5037_50371801_24_dialog_content = "De todos modos, estoy seguro de que no será demasiado difícil, ¡así que divirtámonos!",
  ui_story_5037_50371801_25_dialog_content = "¡Está bien!",
  ui_story_5037_50371801_26_dialog_content = "¡Solo espera mi actuación!",
  ui_story_5037_50371801_27_dialog_content = "Goldie, seleccione a alguien de esta lista. Entonces el escenario es tuyo.",
  ui_story_5037_50371801_28_dialog_content = "Vale... ¡Éste!",
  ui_story_5037_50371801_29_dialog_content = "voy a empezar, PlayerName.",
  ui_story_5037_50371801_30_dialog_content = "\"¡Hey chico!\"",
  ui_story_5037_50371801_31_dialog_content = "(¡Ese tono suena muy familiar...!)",
  ui_story_5037_50371801_32_dialog_content = "\"¿Listo para ir a cazar algo conmigo?\"",
  ui_story_5037_50371801_33_dialog_content = "Listo para adivinar a quién se está haciendo pasar Goldie, PlayerName?",
  ui_story_5037_50371801_34_option_content = "¿Bartón?",
  ui_story_5037_50371801_35_dialog_content = "¡Ohhh, eso está cerca pero no del todo bien!",
  ui_story_5037_50371801_36_dialog_content = "La respuesta correcta es... ¡Sinsa!",
  ui_story_5037_50371801_37_dialog_content = "No puedo creer que me haya equivocado.",
  ui_story_5037_50371801_38_dialog_content = "¿Fue mi actuación? ¡Lo haré mejor la próxima vez!",
  ui_story_5037_50371801_39_option_content = "Sinsa?",
  ui_story_5037_50371801_40_dialog_content = "¡Correcto!",
  ui_story_5037_50371801_41_dialog_content = "¡Parece que la actuación de Goldie fue muy convincente!",
  ui_story_5037_50371801_42_dialog_content = "¡Era realmente! era totalmente como Sinsa!",
  ui_story_5037_50371801_43_dialog_content = "Podría haber jurado que estabas a punto de sacar una gran llave inglesa...",
  ui_story_5037_50371801_44_dialog_content = "Uh... ¿Me lo tomaré como un cumplido?",
  ui_story_5037_50371801_45_option_content = "¿Kleken?",
  ui_story_5037_50371801_46_dialog_content = "Eso es... ¡totalmente incorrecto!",
  ui_story_5037_50371801_47_dialog_content = "La respuesta correcta es... ¡Sinsa!",
  ui_story_5037_50371801_48_dialog_content = "Tienes que ver la actuación de Goldie con más cuidado, PlayerName!",
  ui_story_5037_50371801_49_dialog_content = "Lo-lo siento...",
  ui_story_5037_50371801_50_dialog_content = "¡Debería esforzarme más también!",
  ui_story_5037_50371801_51_dialog_content = "¡Estamos aumentando la dificultad para el próximo!",
  ui_story_5037_50371801_52_dialog_content = "¡Goldie, veamos cómo imitas a esta persona!",
  ui_story_5037_50371801_53_dialog_content = "Guau... Son bastante diferentes a mí, ¡pero haré lo mejor que pueda!",
  ui_story_5037_50371801_54_dialog_content = "\"¿Qué estás haciendo, joven?\"",
  ui_story_5037_50371801_55_dialog_content = "(¿Con quién está jugando esta vez...?)",
  ui_story_5037_50371801_56_dialog_content = "\"¿Podrías traer mi té a mi habitación si tienes un minuto? Soy demasiado perezoso para ir a buscarlo yo mismo\".",
  ui_story_5037_50371801_57_dialog_content = "Adivina, PlayerName!",
  ui_story_5037_50371801_58_option_content = "Migard?",
  ui_story_5037_50371801_59_dialog_content = "¡Correcto!",
  ui_story_5037_50371801_60_dialog_content = "Eso realmente fue bastante duro...",
  ui_story_5037_50371801_61_dialog_content = "También fue duro para mí. Su porte y gestos son bastante difíciles de expresar.",
  ui_story_5037_50371801_62_dialog_content = "¡Aunque lo hice bien! ¡Creo que eso demuestra que la actuación de Goldie fue un éxito!",
  ui_story_5037_50371801_63_option_content = "¿El señor de la ciudad?",
  ui_story_5037_50371801_64_dialog_content = "Bueno, desde la perspectiva de la edad, ciertamente podría llamarte joven...",
  ui_story_5037_50371801_65_dialog_content = "¡Pero la respuesta correcta es Migard!",
  ui_story_5037_50371801_66_dialog_content = "tengo que esforzarme mas...",
  ui_story_5037_50371801_67_dialog_content = "No, tal vez deba prestar más atención...",
  ui_story_5037_50371801_68_option_content = "Tweety?",
  ui_story_5037_50371801_69_dialog_content = "¡No! Cómo podría Tweety ¿Te llamo joven cuando ella misma todavía es tan joven?",
  ui_story_5037_50371801_70_dialog_content = "La respuesta correcta es Migard!",
  ui_story_5037_50371801_71_dialog_content = "A pesar de que es una mujer hermosa, todavía tiene muchos de los modales de un anciano...",
  ui_story_5037_50371801_72_dialog_content = "E-Ciertamente...",
  ui_story_5037_50371801_73_dialog_content = "¡Siempre siento que estoy siendo escudriñado cuando la veo!",
  ui_story_5037_50371801_74_dialog_content = "Esforcémonos más por el próximo, PlayerName!",
  ui_story_5037_50371801_75_dialog_content = "A continuación, ¡nuestro desafío final!",
  ui_story_5037_50371801_76_dialog_content = "¡Goldie, por favor conviértete en esta persona!",
  ui_story_5037_50371801_77_dialog_content = "¡¿Eh?! ¿E-está realmente bien?",
  ui_story_5037_50371801_78_dialog_content = "¡Por supuesto! ¡Eres libre de actuar como mejor te parezca!",
  ui_story_5037_50371801_79_dialog_content = "Muy bien... ¡Aquí voy!",
  ui_story_5037_50371801_80_dialog_content = "\"PlayerName...\"",
  ui_story_5037_50371801_81_dialog_content = "(¿Ya empezó?!)",
  ui_story_5037_50371801_82_dialog_content = "\"¡Vamos a darlo todo hoy también!\"",
  ui_story_5037_50371801_83_dialog_content = "Está bien, PlayerName. ¿Cuál es tu suposición?",
  ui_story_5037_50371801_84_option_content = "Lilica?",
  ui_story_5037_50371801_85_dialog_content = "se parecía Lilica! Pero no es ella.",
  ui_story_5037_50371801_86_dialog_content = "¿No es? ¿En serio?",
  ui_story_5037_50371801_87_dialog_content = "La respuesta está justo frente a tus ojos, PlayerName!",
  ui_story_5037_50371801_88_dialog_content = "¿Estabas... actuando tú mismo?",
  ui_story_5037_50371801_89_dialog_content = "¡Correcto!",
  ui_story_5037_50371801_90_option_content = "¿Goldie?",
  ui_story_5037_50371801_91_dialog_content = "¡Bingo!",
  ui_story_5037_50371801_92_dialog_content = "¡Realmente no esperaba que lo hicieras bien!",
  ui_story_5037_50371801_93_dialog_content = "Sonaba tan enérgico, como sueles ser.",
  ui_story_5037_50371801_94_dialog_content = "Estoy un poco confundido por qué la usaste.",
  ui_story_5037_50371801_95_dialog_content = "La propia percepción de un productor sobre la actuación de su actor influirá en su formación.",
  ui_story_5037_50371801_96_dialog_content = "Además de entender los roles, los mejores productores también tienen otra habilidad...",
  ui_story_5037_50371801_97_dialog_content = "¡Conocen las características y fortalezas de sus propios actores!",
  ui_story_5037_50371801_98_dialog_content = "Solo esto permite una formación específica y personalizada.",
  ui_story_5037_50371801_99_dialog_content = "¡Así que ese desafío final en realidad fue una prueba para ti!",
  ui_story_5037_50371801_100_dialog_content = "¡Así que de eso se trataba todo! Entiendo ahora.",
  ui_story_5037_50371801_101_dialog_content = "¡Yo también aprendí mucho!",
  ui_story_5037_50371801_102_dialog_content = "Hay tantas diferencias entre cada papel. ¡Tengo que seguir trabajando duro!",
  ui_story_5037_50371801_103_dialog_content = "Eso es todo por el entrenamiento de hoy! ¡Les deseamos lo mejor a ambos!",
  ui_story_5037_50371801_104_dialog_content = "¡No olvides poner en práctica lo que aprendiste hoy!",
  ui_story_5037_50371801_105_dialog_content = "¡Entendido!",
  ui_story_5037_50371801_106_dialog_content = "¡Sí, directora Lilica!",
  ui_story_5037_50371901_1_dialog_content = "Entonces, ¿cómo es exactamente una sacerdotisa de la Isla de las Nubes?",
  ui_story_5037_50371901_2_dialog_content = "Escuché que las sacerdotisas son increíbles bailarinas, gráciles y misteriosas, y también muy hábiles en Luminatic.",
  ui_story_5037_50371901_3_dialog_content = "¡Mi imaginación se está volviendo loca!",
  ui_story_5037_50371901_4_dialog_content = "¡Podrás comprobarlo por ti mismo muy pronto!",
  ui_story_5037_50371901_5_dialog_content = "¡Me las arreglé para sacar algo de tiempo para venir a tu Coloso solo para esta reunión!",
  ui_story_5037_50371901_6_dialog_content = "¡Mi corazón comenzó a acelerarse en el momento en que escuché que tenía la oportunidad de pedirle consejos de baile a una verdadera sacerdotisa!",
  ui_story_5037_50371901_7_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5037_50371901_8_dialog_content = "Mis disculpas por hacerlos esperar a ambos.",
  ui_story_5037_50371901_9_dialog_content = "¡De nada! ¡Estoy tan agradecida de que hayas venido desde Cloud Island para entrenarnos!",
  ui_story_5037_50371901_10_dialog_content = "Debes ser Goldie, ¿verdad?",
  ui_story_5037_50371901_11_dialog_content = "¡Sí! Hola Rinne, Soy Goldie, un ídolo.",
  ui_story_5037_50371901_12_dialog_content = "Hola, Goldie. Soy Rinne, una sacerdotisa de Cloud Island.",
  ui_story_5037_50371901_13_dialog_content = "¿Es lo mismo un ídolo que un cantante?",
  ui_story_5037_50371901_14_dialog_content = "Hay algunas diferencias. ¡Además de cantar, también necesito aprender otras habilidades, como bailar y actuar!",
  ui_story_5037_50371901_15_dialog_content = "Veo. ¿Y por eso deseas aprender la danza kagura?",
  ui_story_5037_50371901_16_dialog_content = "¡Sí! ¿Puedes enseñarme, Rinne?",
  ui_story_5037_50371901_17_dialog_content = "¡Por supuesto! ¿Por qué no bailo para ti ahora, como una pequeña demostración?",
  ui_story_5037_50371901_18_dialog_content = "¡¿En realidad?! ¡Oh sí! ¡No puedo creer que pueda presenciar a una sacerdotisa haciendo un baile kagura!",
  ui_story_5037_50371901_19_dialog_content = "Jeje...",
  ui_story_5037_50371901_20_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5037_50371901_21_dialog_content = "<color=#828282>Timbre...</color>",
  ui_story_5037_50371901_22_dialog_content = "Impresionante...",
  ui_story_5037_50371901_23_dialog_content = "El sonido de las campanas y la vista del baile de Rinne me llena de serenidad...",
  ui_story_5037_50371901_24_dialog_content = "Estos son solo algunos de los pasos básicos de kagura. ¿Te gustaría intentarlo? Goldie?",
  ui_story_5037_50371901_25_dialog_content = "¡Sí!",
  ui_story_5037_50371901_26_dialog_content = "¿Es esto correcto?",
  ui_story_5037_50371901_27_dialog_content = "Bien hecho. ¡Tienes los movimientos perfectamente definidos!",
  ui_story_5037_50371901_28_dialog_content = "¡Tengo bastante confianza en mis habilidades de duplicación!",
  ui_story_5037_50371901_29_dialog_content = "Pero aun así, no puedo evitar sentir que a mi Kagura le falta algo...",
  ui_story_5037_50371901_30_dialog_content = "Es cierto que no emite la misma sensación de calma que Rinne's.",
  ui_story_5037_50371901_31_dialog_content = "Extrañar Rinne, ¿usáis algún tipo de Luminatic especial cuando bailáis?",
  ui_story_5037_50371901_32_dialog_content = "De nada. No estoy usando ningún Luminatics. Es solo baile, nada más.",
  ui_story_5037_50371901_33_dialog_content = "Entonces, ¿qué estoy haciendo exactamente diferente?",
  ui_story_5037_50371901_34_dialog_content = "May Te pregunto en que estabas pensando mientras bailabas?",
  ui_story_5037_50371901_35_dialog_content = "¿Qué estaba pensando...?",
  ui_story_5037_50371901_36_dialog_content = "Muchas cosas, como si mis movimientos fueran correctos, y lo que viene después...",
  ui_story_5037_50371901_37_dialog_content = "Era la primera vez que bailaba kagura, así que me preocupaba hacerlo bien.",
  ui_story_5037_50371901_38_dialog_content = "Ahh... Tal vez esa es la fuente del problema.",
  ui_story_5037_50371901_39_dialog_content = "Kagura es una danza para los dioses. Cuando te mueves, tus pensamientos solo deben estar con lo divino.",
  ui_story_5037_50371901_40_dialog_content = "Solo entonces tu corazón podrá expresarse a través de la danza.",
  ui_story_5037_50371901_41_dialog_content = "Oh...! Bien, creo que entiendo!",
  ui_story_5037_50371901_42_dialog_content = "¡Eso fue rápido!",
  ui_story_5037_50371901_43_dialog_content = "¡Es un poco similar a cómo suelo actuar!",
  ui_story_5037_50371901_44_dialog_content = "Mis fans son las únicas cosas en las que pienso cuando estoy cantando o bailando, y cuánto espero estar brindándoles alegría.",
  ui_story_5037_50371901_45_dialog_content = "Cuando estoy en la zona así, mi voz y mis movimientos parecen fluir casi sin esfuerzo.",
  ui_story_5037_50371901_46_dialog_content = "Los bailes pueden ser diferentes, pero algunas cosas son iguales.",
  ui_story_5037_50371901_47_dialog_content = "¿Volverías a intentar el baile teniendo todo eso en mente?",
  ui_story_5037_50371901_48_dialog_content = "¡Sí!",
  ui_story_5037_50371901_49_dialog_content = "Piensa solo en mis fans...",
  ui_story_5037_50371901_50_dialog_content = "(¡Es increíble! ¡Es una vibra totalmente diferente en comparación con la primera vez!)",
  ui_story_5037_50371901_51_dialog_content = "(Pero todavía parece haber algunas diferencias entre el baile de Goldie y el de Rinne).",
  ui_story_5037_50371901_52_dialog_content = "¿Qué piensas, Rinne? PlayerName?",
  ui_story_5037_50371901_53_option_content = "¡Es mucho más como el de Rinne!",
  ui_story_5037_50371901_54_dialog_content = "¿De veras? ¡Estupendo!",
  ui_story_5037_50371901_55_dialog_content = "Hmm... Todavía hay algunas diferencias.",
  ui_story_5037_50371901_56_dialog_content = "¿Oh?",
  ui_story_5037_50371901_57_option_content = "¡Tu versión del baile tiene su propio encanto!",
  ui_story_5037_50371901_58_dialog_content = "¿Oh?",
  ui_story_5037_50371901_59_dialog_content = "Tu baile se sintió un poco más animado, un poco más ligero.",
  ui_story_5037_50371901_60_dialog_content = "Goldie y estoy bailando para diferentes personas, después de todo.",
  ui_story_5037_50371901_61_dialog_content = "El baile de Goldie es para un público entusiasta y apasionado.",
  ui_story_5037_50371901_62_dialog_content = "Movimientos idénticos pueden transmitir emociones muy diferentes según cada individuo.",
  ui_story_5037_50371901_63_dialog_content = "Esto no es algo malo y es completamente natural, por lo que no hay necesidad de preocuparse por ello.",
  ui_story_5037_50371901_64_dialog_content = "Tu mente y tus movimientos son solo tuyos.",
  ui_story_5037_50371901_65_dialog_content = "¡Está bien!",
  ui_story_5037_50371901_66_dialog_content = "¡Gracias por tu guía!",
  ui_story_5037_50372001_1_dialog_content = "Ya que estamos en otro lugar hoy, necesito comenzar a filmar. Cuiden sus expresiones, muchachos.",
  ui_story_5037_50372001_2_dialog_content = "3... 2... 1... ¡Acción!",
  ui_story_5037_50372001_3_dialog_content = "¿Estamos rodando? *Tos*...",
  ui_story_5037_50372001_4_dialog_content = "Mi clase de canto comienza ahora.",
  ui_story_5037_50372001_5_dialog_content = "¡Hola, Nina!",
  ui_story_5037_50372001_6_dialog_content = "Estoy un poco confundido...",
  ui_story_5037_50372001_7_dialog_content = "¿No se supone que debemos tener entrenamiento vocal en este momento? ¿Qué estamos haciendo en la sala de conciertos?",
  ui_story_5037_50372001_8_dialog_content = "una excelente pregunta, PlayerName.",
  ui_story_5037_50372001_9_dialog_content = "Esta lección no será activa sino pasiva. Hoy estamos escuchando.",
  ui_story_5037_50372001_10_dialog_content = "Escuchando...?",
  ui_story_5037_50372001_11_dialog_content = "¡Escuchar las canciones de otros artistas es una parte importante del entrenamiento de un ídolo!",
  ui_story_5037_50372001_12_dialog_content = "Necesitamos saber qué les gusta a los fanáticos actualmente si queremos hacer música que la gente quiera escuchar.",
  ui_story_5037_50372001_13_dialog_content = "¡Sí! Conoce la tendencia, sigue la tendencia y lidera la tendencia. ¡Este es el alma de la industria!",
  ui_story_5037_50372001_14_dialog_content = "Entonces, hoy vamos a escuchar un musical llamado \"El Fantasma del Teatro\".",
  ui_story_5037_50372001_15_dialog_content = "Cuenta la historia de un actor de teatro inmortal.",
  ui_story_5037_50372001_16_dialog_content = "Las obras cambiantes realizadas proporcionan una línea a través que une cada era de Umbraton.",
  ui_story_5037_50372001_17_dialog_content = "¡Eso es increíble!",
  ui_story_5037_50372001_18_dialog_content = "¡Después de todo, la cultura popular es un reflejo del espíritu de la época!",
  ui_story_5037_50372001_19_dialog_content = "Excelente, diez puntos para Goldie.",
  ui_story_5037_50372001_20_dialog_content = "Reparte el material por favor, Minos.",
  ui_story_5037_50372001_21_dialog_content = "Sí señorita.",
  ui_story_5037_50372001_22_dialog_content = "Qué es esto...?",
  ui_story_5037_50372001_23_dialog_content = "La señorita preparó esto ella misma especialmente. Enumera todas las canciones y óperas populares de Umbraton durante la última década.",
  ui_story_5037_50372001_24_dialog_content = "Asegúrate de cuidarlo.",
  ui_story_5037_50372001_25_dialog_content = "E-Está bien...",
  ui_story_5037_50372001_26_dialog_content = "En esta clase, aprenderá sobre cada una de estas canciones, así como las tendencias de Umbraton en los últimos diez años.",
  ui_story_5037_50372001_27_dialog_content = "Esto debería refinar su gusto y ayudarlo a grabar más canciones de moda.",
  ui_story_5037_50372001_28_dialog_content = "Nina, aprecio tus esfuerzos, pero...",
  ui_story_5037_50372001_29_dialog_content = "¿Seguramente esto es demasiado?",
  ui_story_5037_50372001_30_dialog_content = "¿No puedes esperar que los leamos todos hoy?",
  ui_story_5037_50372001_31_dialog_content = "¿Leerlos todos? ¡No claro que no! Nunca me había propuesto una tarea tan imposible. Difícilmente sería razonable.",
  ui_story_5037_50372001_32_dialog_content = "Se hará referencia a cada una de estas canciones en lo que estamos viendo hoy.",
  ui_story_5037_50372001_33_dialog_content = "Puede consultar la lista completa que preparé para obtener una comprensión más profunda de cómo la cultura pop difería entre las épocas.",
  ui_story_5037_50372001_34_dialog_content = "¡Muchas gracias!",
  ui_story_5037_50372001_35_dialog_content = "¡Lo estudiaremos de cerca!",
  ui_story_5037_50372001_36_dialog_content = "La actuación está a punto de comenzar, así que debemos darnos prisa y tomar nuestros asientos.",
  ui_story_5037_50372001_37_dialog_content = "De esta manera, todos.",
  ui_story_5037_50372001_38_dialog_content = "Señorita amablemente consiguió asientos VIP para usted.",
  ui_story_5037_50372001_39_dialog_content = "Wow, tan cerca del escenario! ¡Probablemente tengamos la mejor vista de la actuación en todo el lugar!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>...</color>",
  ui_story_5037_50372001_41_dialog_content = "\"Tiempos felices, hermosa música... Todos son fugaces\".",
  ui_story_5037_50372001_42_dialog_content = "\"Hermosa dama, ¿podría hacerme el honor de un baile?\"",
  ui_story_5037_50372001_43_dialog_content = "Esta es \"Kleo and Jessica\", una de las primeras obras de teatro de Umbraton.",
  ui_story_5037_50372001_44_dialog_content = "¡Conozco esta! ¡Escuché la historia cuando era niño, adaptada de la obra!",
  ui_story_5037_50372001_45_dialog_content = "Cuenta la trágica historia de dos aurorianos de familias rivales que se enamoran el uno del otro.",
  ui_story_5037_50372001_46_dialog_content = "Así es. Como puede ver, durante este tiempo, la cultura de Umbraton estuvo fuertemente influenciada por Lumopolis.",
  ui_story_5037_50372001_47_dialog_content = "Podemos aprender mucho sobre la vida y los hábitos de los Lumo Nobles contemporáneos a partir de esto, como...",
  ui_story_5037_50372001_48_dialog_content = "(Nina y Goldie realmente se están poniendo en marcha.)",
  ui_story_5037_50372001_49_dialog_content = "(La obra está bien, pero realmente no sé mucho sobre la historia de Lumopolis o Umbraton...)",
  ui_story_5037_50372001_50_dialog_content = "(Tengo sueño... no puedo evitarlo, ver algo que realmente no entiendo solo me hace bostezar...)",
  ui_story_5037_50372001_51_dialog_content = "(Pero Nina se tomó muchas molestias para arreglar todo esto...)",
  ui_story_5037_50372001_52_option_content = "No te rindas al cansancio.",
  ui_story_5037_50372001_53_dialog_content = "(No, no puedo dormir. ¡Tengo que ver esto hasta el final!)",
  ui_story_5037_50372001_54_dialog_content = "(¡Este es un material de referencia invaluable!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>Después de permanecer despierto laboriosamente hasta el final de la actuación.</color>",
  ui_story_5037_50372001_56_dialog_content = "¡No tenía ni idea de lo complicado que era el desarrollo cultural de Umbraton hasta ahora!",
  ui_story_5037_50372001_57_dialog_content = "¡Yo también aprendí mucho!",
  ui_story_5037_50372001_58_dialog_content = "Aunque no estaba muy familiarizado con el contenido...",
  ui_story_5037_50372001_59_dialog_content = "¡No te preocupes! Ya he resaltado los puntos pertinentes en el material.",
  ui_story_5037_50372001_60_dialog_content = "Puede hojear para refrescar sus recuerdos cuando lo desee.",
  ui_story_5037_50372001_61_dialog_content = "¡Vaya, gracias de nuevo por tomarte el tiempo de hacer esto por nosotros, Nina!",
  ui_story_5037_50372001_62_option_content = "Entregarse al sueño.",
  ui_story_5037_50372001_63_dialog_content = "(Tengo que quedarme despierto... Tengo que quedarme... Zzzz...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>Quién sabe cuánto tiempo después...</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName? PlayerName!",
  ui_story_5037_50372001_66_dialog_content = "Déjeme intentarlo, señorita Goldie.",
  ui_story_5037_50372001_67_dialog_content = "¿Podrías despertar, por favor? PlayerName!",
  ui_story_5037_50372001_68_dialog_content = "¿Eh?",
  ui_story_5037_50372001_69_dialog_content = "¿Por qué estás durmiendo? El espectáculo ya ha terminado.",
  ui_story_5037_50372001_70_dialog_content = "¿Qué? ¡¿Se acabó?!",
  ui_story_5037_50372001_71_dialog_content = "Estaba demasiado absorto en explicar las cosas para Goldie que ni me di cuenta de que te habías quedado dormido...",
  ui_story_5037_50372001_72_dialog_content = "Es terriblemente ofensivo despreciar la amabilidad de la señorita...",
  ui_story_5037_50372001_73_dialog_content = "¡Lo siento!",
  ui_story_5037_50372001_74_dialog_content = "Fue mi error...",
  ui_story_5037_50372001_75_dialog_content = "Está bien.",
  ui_story_5037_50372001_76_dialog_content = "Es una pena que hayas perdido la oportunidad de aumentar tus conocimientos mientras disfrutas de una actuación.",
  ui_story_5037_50372001_77_dialog_content = "Pero afortunadamente para ti, ya destaqué los puntos pertinentes en el material.",
  ui_story_5037_50372001_78_dialog_content = "Recogerás algunas cosas, siempre que realmente las revises.",
  ui_story_5037_50372001_79_dialog_content = "¡Lo leeré todo super atentamente! ¡Y no se dormirá!",
  ui_story_5037_50372001_80_dialog_content = "Espero que todos hayan ganado algo de esta actuación.",
  ui_story_5037_50372001_81_dialog_content = "Saber lo que quiere el público es la clave de la cultura popular. No puedes simplemente enterrar tu cabeza en la arena e ignorarlo.",
  ui_story_5037_50372001_82_dialog_content = "Esta es toda la ayuda que puedo ofrecerle. De aquí en adelante, depende de ustedes dos hacer el esfuerzo.",
  ui_story_5037_50372001_83_dialog_content = "¡Gracias, señorita Nina, Minos!",
  ui_story_5037_50372001_84_dialog_content = "¡Si, gracias!",
  ui_story_5037_50372101_1_dialog_content = "Fleur, gracias por guiarnos a Goldie y a mí—",
  ui_story_5037_50372101_2_dialog_content = "¡Shhh!",
  ui_story_5037_50372101_3_dialog_content = "¿eh? ¿Por qué estás apoyada en la puerta, Fleur?",
  ui_story_5037_50372101_4_dialog_content = "Por favor, PlayerName, Goldie... Debo molestarte para que te calles por un segundo...",
  ui_story_5037_50372101_5_dialog_content = "...",
  ui_story_5037_50372101_6_dialog_content = "...",
  ui_story_5037_50372101_7_dialog_content = "Uf... Parece que esos tipos se han ido.",
  ui_story_5037_50372101_8_dialog_content = "¿No me digas que te has metido en problemas otra vez?",
  ui_story_5037_50372101_9_dialog_content = "Bueno...",
  ui_story_5037_50372101_10_dialog_content = "Quiero decir, en el camino aquí, saludé a algunas personas a las que había ayudado anteriormente...",
  ui_story_5037_50372101_11_dialog_content = "Hola.",
  ui_story_5037_50372101_12_dialog_content = "¿Eh? ¡Vaya, si no es Fleur! ¡Muchas gracias por tu ayuda el otro día!",
  ui_story_5037_50372101_13_dialog_content = "Pero luego, después de escuchar mi nombre, más y más personas se acercaron...",
  ui_story_5037_50372101_14_dialog_content = "¿Qué? ¿Fleur está aquí? Realmente te debo una por última vez!",
  ui_story_5037_50372101_15_dialog_content = "Flor!! ¡¡¡Soy un gran fan!!!",
  ui_story_5037_50372101_16_dialog_content = "Me tomó mucho tiempo escapar de la multitud de admiradores. Incluso tuve que tomar la ruta larga solo para asegurarme de que nadie me seguía...",
  ui_story_5037_50372101_17_dialog_content = "A veces es una molestia ser tan popular...",
  ui_story_5037_50372101_18_dialog_content = "¡Estoy tan celoso, desearía ser tan popular como tú!",
  ui_story_5037_50372101_19_dialog_content = "Es realmente muy agotador.",
  ui_story_5037_50372101_20_dialog_content = "¡Eso no me molestaría en absoluto!",
  ui_story_5037_50372101_21_dialog_content = "¡Sería increíble atraer a más fanáticos para disfrutar de mi baile y canto!",
  ui_story_5037_50372101_22_dialog_content = "Si eso es lo que quieres, no tengo objeciones.",
  ui_story_5037_50372101_23_dialog_content = "Es solo que solo soy popular gracias a mi constitución especial.",
  ui_story_5037_50372101_24_dialog_content = "No es solo algo que se puede enseñar...",
  ui_story_5037_50372101_25_dialog_content = "¿En serio?",
  ui_story_5037_50372101_26_dialog_content = "Y para ser honesto, tampoco sé exactamente cómo uno se vuelve popular.",
  ui_story_5037_50372101_27_dialog_content = "Gracias a mi peculiaridad, paso la mayor parte de mi tiempo estudiando cómo pasar desapercibido o incluso pasar desapercibido.",
  ui_story_5037_50372101_28_dialog_content = "No puedo creerlo...",
  ui_story_5037_50372101_29_dialog_content = "¿Qué debemos hacer entonces?",
  ui_story_5037_50372101_30_dialog_content = "¡Lo se!",
  ui_story_5037_50372101_31_dialog_content = "¿Se te ocurrió algo?",
  ui_story_5037_50372101_32_dialog_content = "Bueno, dado que Fleur ya ha pensado largo y tendido sobre cómo volverse IMPOPULAR, ¿por qué no hacemos todo lo contrario?",
  ui_story_5037_50372101_33_dialog_content = "¿Quieres decir, hacer que Fleur te enseñe sus tácticas y luego revertirlas?",
  ui_story_5037_50372101_34_dialog_content = "Entonces, ¿convertir el método para la impopularidad en uno para la popularidad?",
  ui_story_5037_50372101_35_dialog_content = "¡Correcto! ¡Es por eso que eres mi productor, te das cuenta tan rápido!",
  ui_story_5037_50372101_36_dialog_content = "¿De verdad crees que funcionará?",
  ui_story_5037_50372101_37_dialog_content = "Nunca lo sabremos si no lo intentamos, ¿verdad? ¿Me enseñarías, Fleur? ¿Por favor?",
  ui_story_5037_50372101_38_dialog_content = "De acuerdo... ¿Quieren aprender a pasar desapercibidos o a que no les guste activamente?",
  ui_story_5037_50372101_39_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_5037_50372101_40_dialog_content = "(Dado que lo invertiremos, seguramente mientras más personas no le gusten, ¿más les gustará cuando se inviertan?)",
  ui_story_5037_50372101_41_option_content = "Cómo ser discreto",
  ui_story_5037_50372101_42_dialog_content = "Pasar desapercibido es bastante simple: el truco consiste en ser como los demás.",
  ui_story_5037_50372101_43_dialog_content = "Todo lo que tienes que hacer es actuar como lo hacen los demás mientras ocultas las características distintivas que te hacen destacar, ¡y eso es todo!",
  ui_story_5037_50372101_44_dialog_content = "¡Haces que suene fácil!",
  ui_story_5037_50372101_45_dialog_content = "Por lo general, no llamarás la atención si usas ropa normal y aburrida y caminas con la cabeza gacha.",
  ui_story_5037_50372101_46_dialog_content = "¡Algunas personas incluso usan sombreros, que pueden ayudar a ocultar sus rostros!",
  ui_story_5037_50372101_47_dialog_content = "Entonces, lo contrario de eso sería... ¿Andar con la frente en alto, mostrando mi canto y mi baile?",
  ui_story_5037_50372101_48_dialog_content = "Suena un poco raro, pero como cantas y bailas muy bien...",
  ui_story_5037_50372101_49_dialog_content = "Debería ser suficiente, ¿verdad?",
  ui_story_5037_50372101_50_option_content = "Cómo ser disgustado",
  ui_story_5037_50372101_51_dialog_content = "Es un poco complicado hacer que a la gente le desagrades activamente.",
  ui_story_5037_50372101_52_dialog_content = "He intentado un montón de cosas diferentes, como escabullirme de forma sospechosa, vestirme con harapos o ensuciarme la cara.",
  ui_story_5037_50372101_53_dialog_content = "Tuve cierto éxito, aunque me confundieron con un ladrón un par de veces...",
  ui_story_5037_50372101_54_dialog_content = "Pero debido a mi problema particular, una vez que la gente viera quién era yo realmente, ningún subterfugio funcionaría.",
  ui_story_5037_50372101_55_dialog_content = "Lo tengo.",
  ui_story_5037_50372101_56_dialog_content = "Entonces lo contrario sería tener una postura digna, vestir bien y verse bien, ¿no?",
  ui_story_5037_50372101_57_dialog_content = "¡Y siempre siendo positivo y mostrando la sonrisa de un ídolo donde quiera que vaya!",
  ui_story_5037_50372101_58_dialog_content = "¡Eso tiene que funcionar!",
  ui_story_5037_50372101_59_dialog_content = "No olvide que su rumbo es un factor importante en cualquier método que utilice.",
  ui_story_5037_50372101_60_dialog_content = "Eres una excelente bailarina, Goldie, así que ya deberías saberlo.",
  ui_story_5037_50372101_61_dialog_content = "¡Totalmente! El porte y la postura son cruciales al bailar. La diferencia entre estar de pie y tener la espalda encorvada cuando bailas es extrema.",
  ui_story_5037_50372101_62_dialog_content = "De todos modos, ¡muchas gracias, Fleur!",
  ui_story_5037_50372101_63_dialog_content = "Mi placer. Si hay algo más en lo que pueda ayudar, no dude en hacérmelo saber.",
  ui_story_5037_50372101_64_dialog_content = "Apuesto a que parte de la razón por la que eres tan popular es que siempre estás dispuesto a ayudar a la gente.",
  ui_story_5037_50372101_65_dialog_content = "T-tú crees??",
  ui_story_5037_50372101_66_dialog_content = "Pero no puedo simplemente ignorar a las personas que necesitan ayuda...",
  ui_story_5037_50372101_67_dialog_content = "Y eso es una gran cosa, ¡definitivamente no cambies eso!",
  ui_story_5037_50372101_68_dialog_content = "Muy bien, lo tengo.",
  ui_story_5037_50372101_69_dialog_content = "Gracias, PlayerName.",
  ui_story_5037_50372101_70_dialog_content = "¡A la gente siempre le gustan los que ayudan a los demás y hacen buenas obras!",
  ui_story_5037_50372101_71_dialog_content = "PlayerName¡Deberíamos ir a probar lo que hemos aprendido!",
  ui_story_5037_50372101_72_dialog_content = "¡¿Ahora?!",
  ui_story_5037_50372101_73_dialog_content = "¡Deberíamos atacar mientras el hierro está caliente! Vamos-",
  ui_story_5037_50372101_74_dialog_content = "¡Espera un minuto, Goldie! ¡No abras la puerta todavía!",
  ui_story_5037_50372101_75_dialog_content = "¿Oh?",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>Crujir-</color>",
  ui_story_5037_50372101_77_dialog_content = "(¡Hay mucha gente afuera!)",
  ui_story_5037_50372101_78_dialog_content = "¿Dónde está Fleur?",
  ui_story_5037_50372101_79_dialog_content = "¡Creí haber escuchado a alguien gritando su nombre!",
  ui_story_5037_50372101_80_dialog_content = "Fleuurrrr! ¡¿Por qué estás corriendo?!",
  ui_story_5037_50372101_81_dialog_content = "Por favor, todos, cálmense...",
  ui_story_5037_50372101_82_dialog_content = "¡¡TE AMAMOS!!",
  ui_story_5037_50372101_83_dialog_content = "¡Guau! ¡Realmente los atraes!",
  ui_story_5037_50372101_84_dialog_content = "La popularidad parece que puede ser una molestia...",
  ui_story_5037_50372201_1_dialog_content = "\"Está solo en la cima\".",
  ui_story_5037_50372201_2_dialog_content = "\"Comer, beber y dormir solos... Esta es la fuente de su arte\".",
  ui_story_5037_50372201_3_dialog_content = "\"Sabiendo esto, sabed también que la soledad no es enemiga sino amiga, ¡compañera constante!\"",
  ui_story_5037_50372201_4_dialog_content = "¡Increíble!",
  ui_story_5037_50372201_5_dialog_content = "¿No es esa una línea de \"Entrevista con los famosos\"?",
  ui_story_5037_50372201_6_dialog_content = "Gracias señorita. Que disfrutes de mi actuación dice mucho sobre tus gustos artísticos.",
  ui_story_5037_50372201_7_dialog_content = "Espera, Caronte. ¿Podrías explicar algo...?",
  ui_story_5037_50372201_8_dialog_content = "¿Cómo apareció todo un set de Eraveil aquí en los diez minutos que estuvimos fuera?",
  ui_story_5037_50372201_9_dialog_content = "No deberías estar tan sorprendido, mi amigo. Los ingenieros de Illumina son los mejores de Astra.",
  ui_story_5037_50372201_10_dialog_content = "No creo que esto sea para lo que se supone que debes usar ingenieros...",
  ui_story_5037_50372201_11_dialog_content = "¡Este es un conjunto realmente increíble! Cuando entré, ¡pensé que de alguna manera me habían transportado a Eraveil!",
  ui_story_5037_50372201_12_dialog_content = "Por favor, créanme, amigos. Todo lo que hago es para apoyar la promoción de los talentos actorales de esta joven.",
  ui_story_5037_50372201_13_dialog_content = "¿En serio?",
  ui_story_5037_50372201_14_dialog_content = "El verdadero conocimiento se obtiene a través de la práctica. Uno debe experimentar la actuación, para ganar experiencia actoral.",
  ui_story_5037_50372201_15_dialog_content = "Preparé tanto el escenario como el guión con la esperanza de que ustedes dos pudieran experimentar la belleza de la actuación.",
  ui_story_5037_50372201_16_dialog_content = "¡Asombroso! Los ídolos a veces también tienen que actuar en obras de teatro.",
  ui_story_5037_50372201_17_dialog_content = "¡Mis habilidades de actuación definitivamente mejorarían con la ayuda de un profesional calificado!",
  ui_story_5037_50372201_18_dialog_content = "En ese caso, comencemos de inmediato.",
  ui_story_5037_50372201_19_dialog_content = "Aquí está el guión que preparé.",
  ui_story_5037_50372201_20_dialog_content = "Er...",
  ui_story_5037_50372201_21_dialog_content = "¿No es esto solo \"Ada and the Colossus\", pero con algunas de las líneas cambiadas?",
  ui_story_5037_50372201_22_dialog_content = "Así es. Elegí intencionalmente una obra adaptada de un cuento de hadas.",
  ui_story_5037_50372201_23_dialog_content = "Los cuentos de hadas son relativamente simples, fáciles de entender y presentan pocos desafíos para los actores novatos.",
  ui_story_5037_50372201_24_dialog_content = "¡Pensaste en todo!",
  ui_story_5037_50372201_25_dialog_content = "Pero por supuesto. ¡Sé lo que es pasar de ser un actor novato a ser el actor talentoso que soy hoy!",
  ui_story_5037_50372201_26_dialog_content = "¿Asignamos roles, PlayerName?",
  ui_story_5037_50372201_27_dialog_content = "Bueno. Como estoy familiarizado con Colossi, puedo asumir el papel de Kaz.",
  ui_story_5037_50372201_28_dialog_content = "¡Haré de Ada entonces!",
  ui_story_5037_50372201_29_dialog_content = "Es un personaje adorable que siente curiosidad por todo y está llena de energía.",
  ui_story_5037_50372201_30_dialog_content = "Asumiré el papel de narrador y otras partes secundarias.",
  ui_story_5037_50372201_31_dialog_content = "Ya que todo está decidido, bien podríamos comenzar.",
  ui_story_5037_50372201_32_dialog_content = "\"En las pacíficas mentiras de Eraveil, un coloso llamado Kaz\".",
  ui_story_5037_50372201_33_dialog_content = "\"Anhela el cielo abierto, pero permanece atrapado en el suelo sin un navegador\".",
  ui_story_5037_50372201_34_dialog_content = "\"¡Sin embargo, los Colosos nacieron para los cielos!\"",
  ui_story_5037_50372201_35_dialog_content = "\"Puede haber modelos adaptados para la tierra y el mar, ¡pero el cielo sigue siendo su verdadero hogar!\"",
  ui_story_5037_50372201_36_dialog_content = "\"Me pregunto cómo es tener un navegador... Qué bueno debe ser...\"",
  ui_story_5037_50372201_37_dialog_content = "\"Tener un navegante debe ser como tener un mejor amigo...\"",
  ui_story_5037_50372201_38_dialog_content = "\"¿Eh? ¿Quién va allí? ¿Cómo es que puedes hablar conmigo...?\"",
  ui_story_5037_50372201_39_dialog_content = "\"¿Es un fantasma? Después de todo, ningún Caelestita deambularía por este viejo Coloso oxidado...\"",
  ui_story_5037_50372201_40_dialog_content = "\"¡Y sin embargo, aquí ante ti hay un Caelestite!\"",
  ui_story_5037_50372201_41_dialog_content = "\"Ada se acerca a Kaz, observa cómo las flores crecen por toda su cabeza y extiende una mano para tocarlo\".",
  ui_story_5037_50372201_42_dialog_content = "(Espera, ¿le toca la cabeza? Eso no está en mi guión...)",
  ui_story_5037_50372201_43_dialog_content = "(¿Qué debo hacer? ¿Simplemente continuar?)",
  ui_story_5037_50372201_44_option_content = "Continuar la actuación",
  ui_story_5037_50372201_45_dialog_content = "\"Yo toco...\"",
  ui_story_5037_50372201_46_dialog_content = "\"¡Heeeeey! ¿Crees que está bien que Caelestites escuche a escondidas los pensamientos privados de alguien, y luego simplemente se acerque y los toque?\"",
  ui_story_5037_50372201_47_dialog_content = "\"¡Mi hermosa cabeza no puede ser tocada por cualquiera!\"",
  ui_story_5037_50372201_48_dialog_content = "\"¡Pero realmente ES hermoso y está adornado con lindas florecillas!\"",
  ui_story_5037_50372201_48X1_dialog_content = "¡Corte!",
  ui_story_5037_50372201_49_dialog_content = "Bien hecho, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "¿Ah?",
  ui_story_5037_50372201_51_option_content = "Hacer una pregunta",
  ui_story_5037_50372201_52_dialog_content = "Un momento, eso no está en el guión.",
  ui_story_5037_50372201_52X1_dialog_content = "¡Corte!",
  ui_story_5037_50372201_53_dialog_content = "Así es.",
  ui_story_5037_50372201_54_dialog_content = "el mio tampoco lo tiene...",
  ui_story_5037_50372201_55_dialog_content = "¿Qué pasa con esto, Caronte?",
  ui_story_5037_50372201_56_dialog_content = "Las actuaciones pueden necesitar guiones, pero las personas interpretan los papeles.",
  ui_story_5037_50372201_57_dialog_content = "Los eventos inesperados pueden ocurrir en el curso de una actuación. El guión no siempre se seguirá al pie de la letra.",
  ui_story_5037_50372201_58_dialog_content = "¡Por lo tanto, un actor sobresaliente debe ser capaz de adaptarse e improvisar frente a circunstancias cambiantes!",
  ui_story_5037_50372201_59_dialog_content = "¡Ya veo!",
  ui_story_5037_50372201_60_dialog_content = "¡En efecto! He visto algunas obras en las que las líneas habladas en el escenario eran diferentes de lo que estaba escrito en el guión.",
  ui_story_5037_50372201_61_dialog_content = "¡Sin embargo, la improvisación del actor era tan natural que nadie podía darse cuenta!",
  ui_story_5037_50372201_62_dialog_content = "La improvisación es una habilidad importante para los actores.",
  ui_story_5037_50372201_63_dialog_content = "Uno debe primero entender el carácter de uno, y luego convertirse en él. Sólo entonces podrás expresarlos con la mayor naturalidad.",
  ui_story_5037_50372201_64_dialog_content = "¡Lo entiendo!",
  ui_story_5037_50372201_65_dialog_content = "¡Trabajaré duro en esto y refinaré mis habilidades de actuación aún más!",
  ui_story_5037_50379901_1_dialog_content = "esto es raro...",
  ui_story_5037_50379901_2_dialog_content = "¡Esto es demasiado raro!",
  ui_story_5037_50379901_3_dialog_content = "¿Por qué Vice y Carleen me han estado evitando durante los últimos días?",
  ui_story_5037_50379901_4_dialog_content = "¿Dije algo que los ofendió?",
  ui_story_5037_50379901_5_dialog_content = "No me digas que tiene algo que ver con lo que pasó...",
  ui_story_5037_50379901_6_option_content = "En el puente",
  ui_story_5037_50379901_7_dialog_content = "Wow, ha pasado un tiempo desde que usé este atuendo. ¡Al menos todavía me queda!",
  ui_story_5037_50379901_8_dialog_content = "Qué opinas, PlayerName? Entre este y mi uniforme habitual de Illumina, ¿cuál crees que se ve mejor?",
  ui_story_5037_50379901_9_dialog_content = "¿Eh? No lo sé.",
  ui_story_5037_50379901_10_dialog_content = "...",
  ui_story_5037_50379901_11_dialog_content = "¡Debería haber dicho que ambos se veían bien!",
  ui_story_5037_50379901_12_option_content = "En el salón",
  ui_story_5037_50379901_13_dialog_content = "¡¿PlayerName?!",
  ui_story_5037_50379901_14_dialog_content = "¡¿Q-Qué haces aquí?! ¡Giro de vuelta! ¡No mires!",
  ui_story_5037_50379901_15_dialog_content = "Solo vine a buscar algo de beber...",
  ui_story_5037_50379901_16_dialog_content = "¿Qué viste hace un momento...?",
  ui_story_5037_50379901_17_dialog_content = "¿Eh? Bueno, te vi en pijama, mirándote felizmente en el espejo...",
  ui_story_5037_50379901_18_dialog_content = "no viste nada!!!",
  ui_story_5037_50379901_19_dialog_content = "¡Argh! ¡Debería haberme quedado en la cama esa noche!",
  ui_story_5037_50379901_20_dialog_content = "Aún así, no creo que esos errores fueran suficientes para que me ignoraran así...",
  ui_story_5037_50379901_21_dialog_content = "¡Aaaaaah! ¿Qué hice mal exactamente? ¡¡Me esta volviendo loco!!",
  ui_story_5037_50379901_22_dialog_content = "¡También es casi fin de año! ¡No podemos entrar en el nuevo año con este tipo de incomodidad entre nosotros!",
  ui_story_5037_50379901_23_dialog_content = "¿M-Tal vez debería preguntarles directamente?",
  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5037_50379901_25_dialog_content = "¿Vicio? ¿Carleen? Tú allí...?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>¿Eh? yo-es PlayerName! Ugh... ¡¿Qué está haciendo él aquí ahora, de todos los tiempos?!</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>Apuro...!</size>",
  ui_story_5037_50379901_28_dialog_content = "Oh hola, PlayerName! ¡Llegaste justo a tiempo!",
  ui_story_5037_50379901_29_dialog_content = "Carleen y yo estábamos a punto de ir a buscarte. ¡Adelante!",
  ui_story_5037_50379901_30_dialog_content = "¿Eh? ¡Pero ustedes dos me han estado evitando durante días! ¿Qué pasa con el repentino cambio de actitud?",
  ui_story_5037_50379901_31_dialog_content = "¡Lo sabrás una vez que entres!",
  ui_story_5037_50379901_32_dialog_content = "Uh... ¿Por qué están todas las luces apagadas? Está tan oscuro aquí... Da un poco de miedo.",
  ui_story_5037_50379901_33_dialog_content = "Solo experimenta el efecto completo si las luces están apagadas.",
  ui_story_5037_50379901_34_dialog_content = "¡¿El efecto completo de qué?!",
  ui_story_5037_50379901_35_dialog_content = "Mantén la vista al frente, está comenzando.",
  ui_story_5037_50379901_36_dialog_content = "¿Ah?",
  ui_story_5037_50379901_38_dialog_content = "Wow... Seguro que el tiempo vuela, ¿no?",
  ui_story_5037_50379901_39_dialog_content = "¡Sin darme cuenta, ya ha pasado un año más!",
  ui_story_5037_50379901_40_dialog_content = "Pero el hecho de que se sintiera tan rápido es algo bueno.",
  ui_story_5037_50379901_41_dialog_content = "Significa que tuvimos un año muy significativo.",
  ui_story_5037_50379901_42_dialog_content = "Jaja, desde que empezamos a aventurarnos con PlayerName, cada día se ha sentido significativo!",
  ui_story_5037_50379901_43_dialog_content = "¿Es eso así? Entonces recordemos, ¿de acuerdo?",
  ui_story_5037_50379901_44_dialog_content = "¿Todavía recuerdas todos los lugares a los que viajamos el año pasado?",
  ui_story_5037_50379901_45_dialog_content = "Jeje, por supuesto!",
  ui_story_5037_50379901_46_dialog_content = "Durante el año pasado, resistimos una fuerte tormenta antes de llegar finalmente a Northland...",
  ui_story_5037_50379901_47_dialog_content = "¡Esa fue la primera vez que vi la aurora sobre el Palacio de Invierno con mis propios ojos!",
  ui_story_5037_50379901_48_dialog_content = "También fue la primera vez que probé las albóndigas fritas en salsa de fresa de Northland. ¡No tenía idea de que los dos iban juntos tan perfectamente!",
  ui_story_5037_50379901_49_dialog_content = "PlayerName Pasé mucho tiempo en Lake Mirror durante ese viaje. Dijo que vio el pasado de la reina en el agua...",
  ui_story_5037_50379901_50_dialog_content = "Me pregunto qué tipo de visiones se le revelaron.",
  ui_story_5037_50379901_51_dialog_content = "¡Luego decoramos el árbol de destellos e hicimos una cuenta regresiva para el nuevo año!",
  ui_story_5037_50379901_52_dialog_content = "Ah, esto realmente me trae recuerdos...",
  ui_story_5037_50379901_53_dialog_content = "¿De qué, albóndigas fritas?",
  ui_story_5037_50379901_54_dialog_content = "Jejejeje...",
  ui_story_5037_50379901_55_dialog_content = "En el camino de regreso de Northland, accidentalmente aterrizamos en las ruinas de una antigua ciudad subterránea.",
  ui_story_5037_50379901_56_dialog_content = "Para evitar ser atacados por los droides de la ciudad, tuvimos que ponernos el atuendo de las personas que alguna vez vivieron allí.",
  ui_story_5037_50379901_57_dialog_content = "¡Jajaja! ¡Todavía recuerdo la mirada en el rostro de PlayerName cuando tuvo que usar ese vestido!",
  ui_story_5037_50379901_58_dialog_content = "Después nos encontramos con un grupo de amigos que también estaban atrapados en la ciudad.",
  ui_story_5037_50379901_59_dialog_content = "Al principio, nuestras diferencias no causaron más que peleas constantes...",
  ui_story_5037_50379901_60_dialog_content = "Pero cuando todos trabajaron juntos, finalmente logramos convencer a esas dos chicas que vivían en la ciudad antigua...",
  ui_story_5037_50379901_61_dialog_content = "Y así todos logramos salir de la ciudad a salvo antes de que fuera completamente destruida.",
  ui_story_5037_50379901_62_dialog_content = "PlayerName ¡incluso recibimos un mensaje de la ciudad después de que regresamos!",
  ui_story_5037_50379901_63_dialog_content = "Quizás algún día tengamos la oportunidad de volver a visitarlo.",
  ui_story_5037_50379901_64_dialog_content = "Sí... ¡Pero eso tendrá que esperar! ¡Todavía tenemos cosas que hacer!",
  ui_story_5037_50379901_65_dialog_content = "Escoge una flor roja para la dama...",
  ui_story_5037_50379901_66_dialog_content = "Petals fall like snow on a piece of jade.",
  ui_story_5037_50379901_67_dialog_content = "Después de llegar a Koufu-jou por trabajo, conocimos a la sacerdotisa de la ciudad.",
  ui_story_5037_50379901_68_dialog_content = "También resultó ser el Festival Kasuga en ese momento, ¡así que toda la ciudad estaba cubierta de flores de cerezo de color rosa brillante!",
  ui_story_5037_50379901_69_dialog_content = "Pero ninguno de nosotros sabía que debajo de la hermosa apariencia de Koufu-jou...",
  ui_story_5037_50379901_70_dialog_content = "Un complot de asesinato estaba en marcha.",
  ui_story_5037_50379901_71_dialog_content = "Una venganza ardiente hizo arder la paz y la prosperidad del pasado.",
  ui_story_5037_50379901_72_dialog_content = "Que cantos de tristeza...",
  ui_story_5037_50379901_73_dialog_content = "espera la ciudad?",
  ui_story_5037_50379901_74_dialog_content = "Yo no estaba allí, así que no tengo forma de responder a esa pregunta...",
  ui_story_5037_50379901_75_dialog_content = "¡Hey sí! ¿No estabas en Lumopolis en ese momento?",
  ui_story_5037_50379901_76_dialog_content = "¡N-La próxima vez, Carleen! ¡Te prometo que recordaremos invitarte la próxima vez!",
  ui_story_5037_50379901_77_dialog_content = "Oye... ¡Espera un segundo! ¿Es por eso que no me pediste que viniera cuando me invitaste? PlayerName para ver ese espectáculo en Lumopolis?!",
  ui_story_5037_50379901_78_dialog_content = "Te lo dije, era solo para buscar a Gretel.",
  ui_story_5037_50379901_79_dialog_content = "Seguimos las pistas hasta llegar a The Manor of Truth.",
  ui_story_5037_50379901_80_dialog_content = "Irónicamente, estaba lleno de tontos completamente irracionales.",
  ui_story_5037_50379901_81_dialog_content = "Confía en mí...",
  ui_story_5037_50379901_82_dialog_content = "Deberías considerarte afortunado de no haber tenido que sentarte durante esa actuación.",
  ui_story_5037_50379901_83_dialog_content = "Hmm, ¡eso solo me hace sentir aún más curioso!",
  ui_story_5037_50379901_84_dialog_content = "De todos modos, ¿no parece que nos olvidamos de algo?",
  ui_story_5037_50379901_85_dialog_content = "Te refieres a ese momento en que PlayerName ¿Fuiste al desierto de Rediesel? Tú también estabas allí, ¿no?",
  ui_story_5037_50379901_86_dialog_content = "¡Oh, sí, el Rally Ardiente! en realidad pensé PlayerName había sido secuestrado por Sinsa en ese momento.",
  ui_story_5037_50379901_87_dialog_content = "Desafortunadamente, solo logré alcanzarlo al final del rally.",
  ui_story_5037_50379901_88_dialog_content = "Como para PlayerName, no tenía idea de cómo terminó en el asiento del pasajero de ese auto...",
  ui_story_5037_50379901_89_dialog_content = "O qué tipo de historias del pasado de Azure le contó, ahora que lo pienso...",
  ui_story_5037_50379901_90_dialog_content = "No tengo ninguno de los detalles.",
  ui_story_5037_50379901_91_dialog_content = "¡Pero una cosa de la que estoy seguro es que la barbacoa Rediesel Desert es absolutamente deliciosa!",
  ui_story_5037_50379901_92_dialog_content = "Ya veo... Parece que este año ha estado lleno de experiencias culinarias muy sólidas para ti, Vice.",
  ui_story_5037_50379901_93_dialog_content = "¿Tú también lo crees, Carleen?",
  ui_story_5037_50379901_94_dialog_content = "¡Sabía que tenía un talento especial para cocinar!",
  ui_story_5037_50379901_95_dialog_content = "PlayerName, ¡solo espera los nuevos platos que inventaré!",
  ui_story_5037_50379901_96_dialog_content = "Sabes, escuché que contrató a un mayordomo profesional cuando no estábamos cerca.",
  ui_story_5037_50379901_97_dialog_content = "Durante ese período...",
  ui_story_5037_50379901_98_dialog_content = "PlayerName probablemente comió mucha comida deliciosa.",
  ui_story_5037_50379901_99_dialog_content = "Sí... al principio me preguntaba cómo sobreviviría sin nosotros a su lado.",
  ui_story_5037_50379901_100_dialog_content = "¡Pero es totalmente capaz de alimentarse solo!",
  ui_story_5037_50379901_101_dialog_content = "Incluso recibe invitados ahora en Cloud Gardens,",
  ui_story_5037_50379901_102_dialog_content = "que se gestiona tan meticulosamente bien!",
  ui_story_5037_50379901_103_dialog_content = "Sus habilidades de gestión han mejorado mucho.",
  ui_story_5037_50379901_104_dialog_content = "Pero si me preguntas, todavía necesita mucha gente a su lado.",
  ui_story_5037_50379901_105_dialog_content = "Después de todo, es del tipo que ayuda a sus propios secuestradores a contar el dinero del rescate.",
  ui_story_5037_50379901_106_dialog_content = "Afortunadamente para él, el único secuestrador con el que se encontró fue solo un maravilloso entrenador de bestias.",
  ui_story_5037_50379901_107_dialog_content = "En cuanto a lo que sucedió exactamente durante esa pequeña escapada...",
  ui_story_5037_50379901_108_dialog_content = "Ahora solo podemos leer sobre esto en \"Las aventuras del extrozoólogo\".",
  ui_story_5037_50379901_109_dialog_content = "En realidad, Fia me contó todo sobre su aventura. Muchas veces, de hecho.",
  ui_story_5037_50379901_110_dialog_content = "¿Eh? ¡¿Cuando?!",
  ui_story_5037_50379901_111_dialog_content = "Nos encontramos con Fia en Harbor City, ¿recuerdas?",
  ui_story_5037_50379901_112_dialog_content = "¡Vaya! ¡Así que fue entonces cuando te lo contó!",
  ui_story_5037_50379901_113_dialog_content = "Ahora lo recuerdo... ¡El carnaval en el Emerald fue muy divertido!",
  ui_story_5037_50379901_114_dialog_content = "De hecho, pero quién podría haberlo adivinado...",
  ui_story_5037_50379901_115_dialog_content = "que detrás de toda la diversión y festividad, Lord Elvis estaba tramando algo muy peligroso.",
  ui_story_5037_50379901_116_dialog_content = "A pesar de darse cuenta de la magnitud de su sufrimiento después...",
  ui_story_5037_50379901_117_dialog_content = "Como señor de la ciudad, hay ciertas acciones que uno nunca debe realizar.",
  ui_story_5037_50379901_118_dialog_content = "Pero al final, Elvis se sacrificó para salvar a Harbor City de una destrucción segura.",
  ui_story_5037_50379901_119_dialog_content = "Ese día me quedó muy claro que no podemos definir a una persona como completamente buena o mala.",
  ui_story_5037_50379901_120_dialog_content = "Me pregunto si Jeno alguna vez encontró una manera de despertar a Elvis de su coma.",
  ui_story_5037_50379901_121_dialog_content = "Si Elvis despertara de su coma, lo escoltaría personalmente de regreso a Lumopolis para ser juzgado.",
  ui_story_5037_50379901_122_dialog_content = "Oh, eh... Cierto...",
  ui_story_5037_50379901_123_dialog_content = "Después de regresar de Harbor City, PlayerName se encontró con Corax, que estaba en medio de la caza de un asesino en serie.",
  ui_story_5037_50379901_124_dialog_content = "Siguieron el rastro del asesino hasta llegar a un pequeño pueblo llamado Euphoria.",
  ui_story_5037_50379901_125_dialog_content = "Aunque la gente alguna vez lo conoció como el País de las Maravillas, Euphoria ahora está completamente sumida en el crimen organizado y la violencia de las pandillas.",
  ui_story_5037_50379901_126_dialog_content = "Todos los días, escuchas sobre todo tipo de asesinatos, robos y luchas internas dentro de las pandillas locales.",
  ui_story_5037_50379901_127_dialog_content = "Pero incluso en un lugar tan sucio y peligroso como Euphoria, todavía florecen hermosas hortensias por todas partes.",
  ui_story_5037_50379901_128_dialog_content = "Creo que Euphoria volverá a convertirse en un verdadero País de las Maravillas pronto.",
  ui_story_5037_50379901_129_dialog_content = "De todos modos, no mucho después de esa aventura...",
  ui_story_5037_50379901_130_dialog_content = "PlayerName ¡y fui a ver la gran inauguración de Andersen Haunted House!",
  ui_story_5037_50379901_131_dialog_content = "Por total coincidencia, terminamos siendo parte de un video de investigación sobrenatural.",
  ui_story_5037_50379901_132_dialog_content = "Solo queríamos divertirnos un poco... ¡¿Quién hubiera adivinado que había actividad paranormal real allí?!",
  ui_story_5037_50379901_133_dialog_content = "¡Los gritos que escuchamos dentro de la casa embrujada eran completamente reales!",
  ui_story_5037_50379901_134_dialog_content = "Y mi director de cine de terror favorito... ¡Había estado usando Eclipsitas en sus tomas todo el tiempo!",
  ui_story_5037_50379901_135_dialog_content = "Gracias a Dios que tenía otros asuntos en ese momento...",
  ui_story_5037_50379901_136_dialog_content = "No me digas el todopoderoso Carleen tiene miedo a las casas embrujadas?",
  ui_story_5037_50379901_137_dialog_content = "Hmph. Solo estaba preocupado de haber asustado a ese fantasma femenino hasta la muerte... Por así decirlo.",
  ui_story_5037_50379901_138_dialog_content = "Jajajaja! ¿De verdad crees que eres tan aterrador?",
  ui_story_5037_50379901_139_dialog_content = "...",
  ui_story_5037_50379901_140_dialog_content = "<size=45>Ah, ¡fantasma!</size>",
  ui_story_5037_50379901_141_dialog_content = "¿Ver? A eso me refería.",
  ui_story_5037_50379901_142_dialog_content = "¡¿E-Eras tú, Carleen?! No me digas... ¿tú también eres un fantasma?",
  ui_story_5037_50379901_143_dialog_content = "¿No es el juego de roles en estos días? Todos lo hacen.",
  ui_story_5037_50379901_144_dialog_content = "S-Sí, tienes razón...",
  ui_story_5037_50379901_145_dialog_content = "¡Ejem! ¡Pero basta de eso! ¡Volvamos a la verdadera razón por la que estamos aquí!",
  ui_story_5037_50379901_146_dialog_content = "El año está llegando a su fin pronto, PlayerName.",
  ui_story_5037_50379901_147_dialog_content = "¡Preparamos este video para ayudarte a recordar todo lo que hicimos este año!",
  ui_story_5037_50379901_148_dialog_content = "En el próximo año debes recordar...",
  ui_story_5037_50379901_149_dialog_content = "para llevarnos contigo en todas tus próximas aventuras!",
  ui_story_5037_50379901_151_dialog_content = "Ustedes...",
  ui_story_5037_50379901_152_dialog_content = "Entonces, ¿es por eso que has estado actuando tan en secreto últimamente? ¿Porque estabas haciendo este video?",
  ui_story_5037_50379901_153_dialog_content = "¡Jejeje! ¡Queríamos que fuera una sorpresa!",
  ui_story_5037_50379901_154_dialog_content = "Hoy es el último día del año. ¿Cómo no hacerlo especial?",
  ui_story_5037_50379901_155_dialog_content = "Podrías haberme dicho, ya sabes...",
  ui_story_5037_50379901_156_dialog_content = "¡Realmente no tuviste que pasar por todos los problemas de grabar un video y todo!",
  ui_story_5037_50379901_157_dialog_content = "Bueno, pagamos Tourdog mucho dinero para encontrar artistas para crear todo este arte...",
  ui_story_5037_50379901_158_dialog_content = "¡así que tuvimos que hacer todo lo posible para obtener el valor de nuestro dinero!",
  ui_story_5037_50379901_159_dialog_content = "Una forma perfectamente razonable de recibir el año nuevo, si me preguntas.",
  ui_story_5037_50379901_160_dialog_content = "Y algunas cosas son demasiado difíciles de decir en persona...",
  ui_story_5037_50379901_161_dialog_content = "A menos que... ¿no te gusta nuestro video sorpresa?",
  ui_story_5037_50379901_162_option_content = "¡Me gusta!",
  ui_story_5037_50379901_163_option_content = "¡Me gusta mucho!",
  ui_story_5037_50379901_164_dialog_content = "Huff, huff...",
  ui_story_5037_50379901_165_dialog_content = "¡Yo... finalmente lo logré! Espero... no llegar tarde... ¿o sí?",
  ui_story_5037_50379901_166_dialog_content = "¿Lola? ¿No deberías estar en Northland ahora mismo?",
  ui_story_5037_50379901_167_dialog_content = "Pero Vice y Carleen me invitaron a venir y celebrar el año nuevo contigo. PlayerName!",
  ui_story_5037_50379901_168_dialog_content = "R-¿En serio? ¿Les importa explicar, ustedes dos?",
  ui_story_5037_50379901_169_dialog_content = "Si, sobre eso...",
  ui_story_5037_50379901_170_dialog_content = "¡Salgan todos!",
  ui_story_5037_50379901_171_dialog_content = "Oye, PlayerName! ¿Has estado bien?",
  ui_story_5037_50379901_172_dialog_content = "PlayerName! ¿Cuándo conseguiste un gato blanco? ¡Le asustó muchísimo a Bently y Lompty!",
  ui_story_5037_50379901_173_dialog_content = "No te preocupes, Ruby! ¡Te ayudaré a atraparlo!",
  ui_story_5037_50379901_174_dialog_content = "¡No intimides al Sr. Beau!",
  ui_story_5037_50379901_175_dialog_content = "Baaaa!",
  ui_story_5037_50379901_176_dialog_content = "May, Lenore ayudará a proteger al Sr. Beau.",
  ui_story_5037_50379901_177_dialog_content = "Ow... Me tropecé de nuevo... ¿Qué hace una serpiente aquí, de todos modos?",
  ui_story_5037_50379901_178_dialog_content = "¡Ssss!",
  ui_story_5037_50379901_179_dialog_content = "¿Erica? Por favor, no intentes hablar serpiente, podrías ofender a Alba...",
  ui_story_5037_50379901_180_dialog_content = "¿Tener una fiesta sin mí? Qué Caelestite tan traviesa...",
  ui_story_5037_50379901_181_dialog_content = "¡Oh, no!",
  ui_story_5037_50379901_182_dialog_content = "¿Ah?",
